-- =====================================================================
-- Chosen · Phase 4 seed: the 15 approved base roadmaps (EN + PL) and the
-- daily motivation messages.
--
-- HOW TO USE: run AFTER 20260929120000_phase4_progress.sql.
-- Supabase → SQL Editor → New query → paste this whole file → Run.
-- Safe to run again (it refreshes version 1 of each base roadmap).
--
-- This file is generated from src/data/roadmaps by
-- scripts/generate-phase4-seed.js (npm run seed:phase4). Edit the JSON
-- files there, not this file.
-- =====================================================================

-- BEGIN PHASE 4 SEED
insert into public.roadmaps (hustle_id, locale, version, status, content)
select h.id, v.locale, 1, 'approved', v.content::jsonb
from (values
  ('ai-automations', 'en', $roadmap${"hustle_slug":"ai-automations","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Skills & offer","goal":"Learn the basics of Make or Zapier and define one automation you can sell.","weeks":"1-2","steps":[{"id":"p1s1","title":"Learn the basics of Make or Zapier","why":"You only need to master a few building blocks (triggers, filters, AI steps, spreadsheets, email) to solve most small-business problems.","instructions":["Create a free account on Make or Zapier.","Complete the beginner lessons in their academy.","Build 3 practice automations: form → spreadsheet, new email → summary with AI, new lead → reminder email."],"est_minutes":180,"resources":[{"title":"Make Academy","url":"https://academy.make.com"}],"tools":[{"name":"Make","url":"https://www.make.com","affiliate":false},{"name":"Zapier","url":"https://zapier.com","affiliate":false}],"xp":40,"metric_to_track":"Practice automations built"},{"id":"p1s2","title":"Pick one industry and one painful task","why":"‘I automate lead follow-ups for dental clinics’ is easy to understand and easy to buy. ‘I do automations’ isn't.","instructions":["List 5 local business types (clinics, salons, agencies, trades, e-commerce).","For each, write the repetitive task that costs them the most time or lost customers.","Pick one industry and one task to specialize in."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Offer defined"},{"id":"p1s3","title":"Build a demo automation","why":"A working demo that solves your chosen task is the most convincing thing you can show a business owner.","instructions":["Build the automation end to end with test data.","Add error handling so nothing breaks silently.","Record a 2-minute Loom video showing the before and after."],"est_minutes":240,"resources":[],"tools":[{"name":"Loom","url":"https://www.loom.com","affiliate":false}],"xp":50,"metric_to_track":"Demo recorded"},{"id":"p1s4","title":"Price your offer","why":"Pricing by value (hours saved, customers not lost) lets you charge fairly for work that took you a few hours.","instructions":["Estimate how many hours per month your automation saves a business.","Set a setup fee (early projects often pay $200–$1,000) plus an optional monthly maintenance fee.","Write a one-page offer: problem, solution, price, timeline."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Offer page ready"}]},{"id":"p2","title":"First clients","goal":"Reach out to local businesses, book calls and close your first project.","weeks":"3-5","steps":[{"id":"p2s1","title":"Contact 30 businesses","why":"Most small businesses don't search for automation. You find them, show them the demo, and solve a problem they feel every day.","instructions":["Build a list of 30 businesses in your industry (Google Maps, LinkedIn, local directories).","Send a short personal message with your 2-minute demo video.","Ask for a 15-minute call, not a sale."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Businesses contacted"},{"id":"p2s2","title":"Run discovery calls","why":"Listening to how the business really works reveals the automation worth paying for, often a different one than you expected.","instructions":["Ask which tools they use and which tasks they repeat every day.","Ask what one lost customer or wasted hour costs them.","Summarize the problem back and propose a clear next step."],"est_minutes":120,"resources":[],"tools":[{"name":"Calendly","url":"https://calendly.com","affiliate":false}],"xp":40,"metric_to_track":"Calls booked"},{"id":"p2s3","title":"Close and deliver your first project","why":"Your first project becomes your case study. Delivering it well matters more than the price.","instructions":["Send a short proposal with scope, price and timeline, and take a deposit.","Build in the client's own accounts so they own the automation.","Hand over a short video guide and check in after one week."],"est_minutes":300,"resources":[{"title":"Stripe Payment Links","url":"https://docs.stripe.com/payment-links"}],"tools":[{"name":"Stripe","url":"https://stripe.com","affiliate":false}],"xp":60,"metric_to_track":"Paying clients"},{"id":"p2s4","title":"Track income and taxes","why":"Service income needs proper invoices and records. Set it up before the second client.","instructions":["Log each project: client, price, hours, tools cost, profit.","Check how service income and invoicing work where you live.","Set aside part of every payment for taxes."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Profit per project"}]},{"id":"p3","title":"Proof & pipeline","goal":"Turn your first project into a case study and fill your pipeline.","weeks":"6-8","steps":[{"id":"p3s1","title":"Write a case study","why":"‘Saved a clinic 6 hours a week’ is the sentence that sells your next ten projects.","instructions":["Measure the result with your client: hours saved, leads answered, errors avoided.","Write a short before/after story with numbers and a client quote.","Add it to your outreach messages and LinkedIn."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Case studies"},{"id":"p3s2","title":"Contact 30 more businesses","why":"With a real case study, your reply rate goes up. Keep the outreach engine running.","instructions":["Reach out to 30 new businesses in the same industry.","Lead with the case study result in the first sentence.","Follow up once after 4–5 days."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Pitches sent"},{"id":"p3s3","title":"Offer monthly maintenance","why":"Automations need monitoring and small changes. A monthly fee turns one-off projects into recurring income.","instructions":["Define what maintenance includes (monitoring, fixes, one small change per month).","Offer it to every past and new client.","Put it in writing with a clear monthly price."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Monthly retainers"}]},{"id":"p4","title":"Scale","goal":"Package your best automation and build steady monthly clients.","weeks":"9-12","steps":[{"id":"p4s1","title":"Turn your best project into a reusable template","why":"Reusing a proven automation for similar businesses cuts delivery time while the value to the client stays the same.","instructions":["Duplicate your best automation and remove client-specific data.","Document setup steps so you can deploy it in a few hours.","Offer it as a fixed-price package."],"est_minutes":180,"resources":[],"tools":[{"name":"n8n","url":"https://n8n.io","affiliate":false}],"xp":50,"metric_to_track":"Hours per project"},{"id":"p4s2","title":"Ask for referrals","why":"Business owners know other business owners. One happy client can introduce you to several more.","instructions":["Ask each happy client for one or two introductions.","Offer a small thank-you, like a free month of maintenance.","Follow up with every referral within 24 hours."],"est_minutes":90,"resources":[],"tools":[],"xp":40,"metric_to_track":"Referrals"},{"id":"p4s3","title":"Share your work on LinkedIn weekly","why":"Short posts showing real automations and results bring inbound leads over time.","instructions":["Post one short before/after or screen recording per week.","Explain the business result in plain language, not technical terms.","End with an invitation to a free 15-minute call."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Inbound inquiries"}]}],"weekly_metrics":["pitches_sent","calls_booked","clients"],"earning_milestones":[{"label":"Weeks 3–8","range":"$200–$1,000","note":"Your first 1–2 projects."},{"label":"Months 3–6","range":"$500–$2,000 / month","note":"New projects plus the first maintenance retainers."},{"label":"Months 6–12","range":"$1,000–$4,000 / month","note":"Realistic with 2–4 monthly clients."}]}$roadmap$),
  ('ai-automations', 'pl', $roadmap${"hustle_slug":"ai-automations","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Umiejętności i oferta","goal":"Poznaj podstawy Make lub Zapier i określ jedną automatyzację, którą możesz sprzedać.","weeks":"1-2","steps":[{"id":"p1s1","title":"Poznaj podstawy Make lub Zapier","why":"Wystarczy opanować kilka elementów (wyzwalacze, filtry, kroki AI, arkusze, e-mail), by rozwiązać większość problemów małych firm.","instructions":["Załóż darmowe konto w Make lub Zapier.","Przejdź lekcje dla początkujących w ich akademii.","Zbuduj 3 automatyzacje ćwiczeniowe: formularz → arkusz, nowy e-mail → podsumowanie AI, nowy lead → e-mail z przypomnieniem."],"est_minutes":180,"resources":[{"title":"Make Academy (ang.)","url":"https://academy.make.com"}],"tools":[{"name":"Make","url":"https://www.make.com","affiliate":false},{"name":"Zapier","url":"https://zapier.com","affiliate":false}],"xp":40,"metric_to_track":"Zbudowane automatyzacje ćwiczeniowe"},{"id":"p1s2","title":"Wybierz jedną branżę i jedno uciążliwe zadanie","why":"„Automatyzuję kontakt z pacjentami dla gabinetów stomatologicznych” łatwo zrozumieć i kupić. „Robię automatyzacje” już nie.","instructions":["Wypisz 5 rodzajów lokalnych firm (gabinety, salony, agencje, usługi, e-commerce).","Przy każdej zapisz powtarzalne zadanie, które kosztuje je najwięcej czasu lub klientów.","Wybierz jedną branżę i jedno zadanie do specjalizacji."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Określona oferta"},{"id":"p1s3","title":"Zbuduj automatyzację demonstracyjną","why":"Działające demo rozwiązujące wybrane zadanie to najbardziej przekonująca rzecz, jaką pokażesz właścicielowi firmy.","instructions":["Zbuduj automatyzację od początku do końca na danych testowych.","Dodaj obsługę błędów, by nic nie psuło się po cichu.","Nagraj 2-minutowy film w Loomie pokazujący sytuację przed i po."],"est_minutes":240,"resources":[],"tools":[{"name":"Loom","url":"https://www.loom.com","affiliate":false}],"xp":50,"metric_to_track":"Nagrane demo"},{"id":"p1s4","title":"Wyceń ofertę","why":"Wycena według wartości (zaoszczędzone godziny, zatrzymani klienci) pozwala uczciwie liczyć za pracę, która zajęła Ci kilka godzin.","instructions":["Oszacuj, ile godzin miesięcznie automatyzacja oszczędza firmie.","Ustal opłatę za wdrożenie (pierwsze projekty to często 200–1000 $) i opcjonalny miesięczny abonament za utrzymanie.","Napisz jednostronicową ofertę: problem, rozwiązanie, cena, termin."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Gotowa oferta"}]},{"id":"p2","title":"Pierwsi klienci","goal":"Skontaktuj się z lokalnymi firmami, umów rozmowy i zamknij pierwszy projekt.","weeks":"3-5","steps":[{"id":"p2s1","title":"Skontaktuj się z 30 firmami","why":"Większość małych firm nie szuka automatyzacji. To Ty je znajdujesz, pokazujesz demo i rozwiązujesz problem, który czują codziennie.","instructions":["Zbuduj listę 30 firm z wybranej branży (Mapy Google, LinkedIn, lokalne katalogi).","Wyślij krótką, osobistą wiadomość z 2-minutowym filmem demo.","Poproś o 15-minutową rozmowę, a nie o zakup."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Firmy, z którymi nawiązano kontakt"},{"id":"p2s2","title":"Przeprowadź rozmowy wstępne","why":"Słuchanie, jak firma naprawdę działa, pokazuje automatyzację wartą zapłaty, często inną niż zakładano.","instructions":["Zapytaj, z jakich narzędzi korzystają i jakie zadania powtarzają codziennie.","Zapytaj, ile kosztuje ich jeden stracony klient lub zmarnowana godzina.","Podsumuj problem własnymi słowami i zaproponuj jasny następny krok."],"est_minutes":120,"resources":[],"tools":[{"name":"Calendly","url":"https://calendly.com","affiliate":false}],"xp":40,"metric_to_track":"Umówione rozmowy"},{"id":"p2s3","title":"Zamknij i zrealizuj pierwszy projekt","why":"Pierwszy projekt staje się Twoim studium przypadku. Dobra realizacja jest ważniejsza niż cena.","instructions":["Wyślij krótką propozycję z zakresem, ceną i terminem oraz pobierz zaliczkę.","Buduj na kontach klienta, aby to on był właścicielem automatyzacji.","Przekaż krótki film instruktażowy i odezwij się po tygodniu."],"est_minutes":300,"resources":[{"title":"Stripe Payment Links (ang.)","url":"https://docs.stripe.com/payment-links"}],"tools":[{"name":"Stripe","url":"https://stripe.com","affiliate":false}],"xp":60,"metric_to_track":"Płacący klienci"},{"id":"p2s4","title":"Śledź dochody i podatki","why":"Dochód z usług wymaga poprawnych faktur i ewidencji. Ustaw to przed drugim klientem.","instructions":["Zapisuj każdy projekt: klient, cena, godziny, koszt narzędzi, zysk.","Sprawdź, jak w Twoim kraju rozlicza się usługi i wystawia rachunki (w Polsce np. działalność nierejestrowana).","Odkładaj część każdej wpłaty na podatki."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Zysk na projekcie"}]},{"id":"p3","title":"Dowody i lejek","goal":"Zamień pierwszy projekt w studium przypadku i zapełnij lejek sprzedaży.","weeks":"6-8","steps":[{"id":"p3s1","title":"Napisz studium przypadku","why":"„Klinika oszczędza 6 godzin tygodniowo” to zdanie, które sprzeda kolejne dziesięć projektów.","instructions":["Zmierz z klientem efekt: zaoszczędzone godziny, obsłużone leady, uniknięte błędy.","Napisz krótką historię przed/po z liczbami i cytatem klienta.","Dodaj ją do wiadomości i na LinkedIn."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Studia przypadku"},{"id":"p3s2","title":"Skontaktuj się z 30 kolejnymi firmami","why":"Z prawdziwym studium przypadku rośnie odsetek odpowiedzi. Utrzymuj stały kontakt z nowymi firmami.","instructions":["Skontaktuj się z 30 nowymi firmami z tej samej branży.","W pierwszym zdaniu pokaż wynik ze studium przypadku.","Przypomnij się raz po 4–5 dniach."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Wysłane propozycje"},{"id":"p3s3","title":"Zaproponuj miesięczne utrzymanie","why":"Automatyzacje wymagają nadzoru i drobnych zmian. Miesięczna opłata zamienia jednorazowe projekty w stały dochód.","instructions":["Określ, co obejmuje utrzymanie (monitoring, poprawki, jedna drobna zmiana miesięcznie).","Proponuj je każdemu dawnemu i nowemu klientowi.","Spisz warunki z jasną ceną miesięczną."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Stałe umowy miesięczne"}]},{"id":"p4","title":"Skalowanie","goal":"Zamień najlepszą automatyzację w pakiet i zbuduj grupę stałych klientów.","weeks":"9-12","steps":[{"id":"p4s1","title":"Zamień najlepszy projekt w szablon wielokrotnego użytku","why":"Ponowne użycie sprawdzonej automatyzacji w podobnych firmach skraca realizację, a wartość dla klienta pozostaje ta sama.","instructions":["Zduplikuj najlepszą automatyzację i usuń dane klienta.","Opisz kroki wdrożenia, by uruchomić ją w kilka godzin.","Oferuj ją jako pakiet w stałej cenie."],"est_minutes":180,"resources":[],"tools":[{"name":"n8n","url":"https://n8n.io","affiliate":false}],"xp":50,"metric_to_track":"Godziny na projekt"},{"id":"p4s2","title":"Poproś o polecenia","why":"Właściciele firm znają innych właścicieli firm. Jeden zadowolony klient może przedstawić Cię kilku kolejnym.","instructions":["Poproś każdego zadowolonego klienta o jedno lub dwa polecenia.","Zaproponuj drobne podziękowanie, np. darmowy miesiąc utrzymania.","Odezwij się do każdej poleconej osoby w ciągu 24 godzin."],"est_minutes":90,"resources":[],"tools":[],"xp":40,"metric_to_track":"Polecenia"},{"id":"p4s3","title":"Co tydzień pokazuj pracę na LinkedIn","why":"Krótkie posty z prawdziwymi automatyzacjami i wynikami z czasem przyciągają zapytania.","instructions":["Publikuj co tydzień jedno krótkie przed/po lub nagranie ekranu.","Wyjaśniaj efekt biznesowy prostym językiem, bez technicznego żargonu.","Kończ zaproszeniem na darmową 15-minutową rozmowę."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Zapytania przychodzące"}]}],"weekly_metrics":["pitches_sent","calls_booked","clients"],"earning_milestones":[{"label":"Tygodnie 3–8","range":"200–1000 $","note":"Pierwsze 1–2 projekty."},{"label":"Miesiące 3–6","range":"500–2000 $ / mies.","note":"Nowe projekty i pierwsze umowy na utrzymanie."},{"label":"Miesiące 6–12","range":"1000–4000 $ / mies.","note":"Realne przy 2–4 stałych klientach."}]}$roadmap$),
  ('ai-freelancing', 'en', $roadmap${"hustle_slug":"ai-freelancing","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Offer & portfolio","goal":"Pick one clear service, build 3 portfolio samples and set up your profiles.","weeks":"1-2","steps":[{"id":"p1s1","title":"Pick one service for one type of client","why":"Clients hire specialists. ‘Product descriptions for Shopify stores’ wins more jobs than ‘writer for anything’.","instructions":["List services you can deliver well with AI tools (copywriting, translation, design, video editing, research).","Search Fiverr and Upwork for each and note demand and typical prices.","Pick one service and one client type you understand."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Service chosen"},{"id":"p1s2","title":"Create 3 portfolio samples","why":"Clients buy what they can see. Three strong samples for your target client beat any description of your skills.","instructions":["Pick 3 realistic tasks your target client would pay for.","Use AI to speed up drafts, then edit carefully so the result is accurate and sounds human.","Show before/after or explain the result each sample would bring."],"est_minutes":240,"resources":[],"tools":[{"name":"Claude","url":"https://claude.ai","affiliate":false},{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Samples ready"},{"id":"p1s3","title":"Set up your Fiverr and Upwork profiles","why":"A focused profile with a clear headline and samples makes clients trust a new freelancer.","instructions":["Use a friendly, clear profile photo.","Write a headline with your service and client type (e.g. ‘SEO product descriptions for Shopify stores’).","Add your 3 samples to the portfolio sections.","Complete every profile field; complete profiles rank better in search."],"est_minutes":90,"resources":[{"title":"Upwork Help Center","url":"https://support.upwork.com"}],"tools":[{"name":"Fiverr","url":"https://www.fiverr.com","affiliate":false},{"name":"Upwork","url":"https://www.upwork.com","affiliate":false}],"xp":40,"metric_to_track":"Profiles live"},{"id":"p1s4","title":"Define your quality process","why":"AI makes you fast, but reviews depend on quality. A checklist protects your reputation on every job.","instructions":["Write a 5-point checklist: facts checked, brief followed, tone matched, formatting clean, spelling checked.","Never paste clients' confidential data into AI tools without their permission.","Be honest with clients about how you use AI if they ask."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Checklist ready"}]},{"id":"p2","title":"First clients","goal":"Publish your offer, send tailored proposals and land your first 1–3 clients.","weeks":"3-5","steps":[{"id":"p2s1","title":"Publish a gig with 3 packages","why":"Three packages (basic, standard, premium) let clients choose and often pick the middle one.","instructions":["Create a Fiverr gig with a clear title, your samples and 3 packages.","Start slightly below market prices to win first reviews.","Use a gig image that shows the result, not just your name."],"est_minutes":90,"resources":[],"tools":[{"name":"Fiverr","url":"https://www.fiverr.com","affiliate":false}],"xp":40,"metric_to_track":"Gig live"},{"id":"p2s2","title":"Send 10 tailored proposals","why":"Generic proposals get ignored. Mentioning the client's exact problem and a relevant sample gets replies.","instructions":["Find 10 fresh Upwork jobs that match your service exactly.","Open each proposal with the client's goal in your own words.","Link one relevant sample and suggest a clear first step.","Keep it under 150 words."],"est_minutes":180,"resources":[],"tools":[{"name":"Upwork","url":"https://www.upwork.com","affiliate":false}],"xp":50,"metric_to_track":"Proposals sent"},{"id":"p2s3","title":"Overdeliver on your first job","why":"Your first reviews decide how fast you grow. A delighted first client is worth more than the fee.","instructions":["Confirm the brief in writing before you start.","Deliver early, with a short note explaining your choices.","Ask politely for a review once the client is happy."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Paying clients"},{"id":"p2s4","title":"Track income, fees and taxes","why":"Platforms take a fee from each job. Knowing your real hourly rate shows when to raise prices.","instructions":["Log each job: client, price, platform fee, hours, net per hour.","Update it before each weekly check-in.","Check how freelance income is taxed where you live."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Net per hour"}]},{"id":"p3","title":"Momentum","goal":"Keep a steady flow of proposals, collect reviews and raise your prices.","weeks":"6-8","steps":[{"id":"p3s1","title":"Send 20 more proposals","why":"Freelancing is a numbers game at the start. Volume plus quality lands steady work.","instructions":["Set a daily target of 2–3 proposals.","Save your best-performing opening lines as templates, but always personalize.","Track reply rate and adjust what doesn't work."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Proposals sent"},{"id":"p3s2","title":"Raise your prices","why":"After 3–5 good reviews, you're no longer a beginner on the platform. Your prices should reflect that.","instructions":["Raise package prices by 20–30%.","Keep existing clients on their current rate for a while if you want to retain them.","Watch whether orders drop, and adjust after 2 weeks."],"est_minutes":30,"resources":[],"tools":[],"xp":40,"metric_to_track":"Average job value"},{"id":"p3s3","title":"Create client message templates","why":"Fast, clear communication earns 5-star reviews and saves you hours each week.","instructions":["Write templates for: first reply, brief questions, delivery, revision, review request.","Define how many revisions each package includes.","Reply to new messages within a few hours."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Average rating"}]},{"id":"p4","title":"Steady income","goal":"Turn one-off jobs into repeat work and build a presence outside the platforms.","weeks":"9-12","steps":[{"id":"p4s1","title":"Offer a monthly package to past clients","why":"Repeat clients are the easiest income. A monthly package turns good clients into predictable revenue.","instructions":["Design a monthly package (e.g. 10 product descriptions per month).","Message your 3 best clients with a short proposal.","Keep all work and payments on the platform while it's a platform client, as its rules require."],"est_minutes":60,"resources":[],"tools":[],"xp":50,"metric_to_track":"Repeat clients"},{"id":"p4s2","title":"Build a simple portfolio and LinkedIn profile","why":"Clients you find yourself pay no platform fee. A portfolio and LinkedIn profile make direct outreach possible.","instructions":["Create a one-page portfolio with your best 5 samples and reviews.","Update your LinkedIn headline to match your service.","Post one useful tip or before/after example per week."],"est_minutes":120,"resources":[],"tools":[{"name":"Behance","url":"https://www.behance.net","affiliate":false}],"xp":40,"metric_to_track":"Direct inquiries"},{"id":"p4s3","title":"Speed up delivery with reusable AI workflows","why":"Saved prompts and templates cut delivery time, which raises your real hourly rate.","instructions":["Save your best prompts and document templates in one place.","Time three jobs before and after using them.","Invest the saved time in more proposals or a higher-value service."],"est_minutes":60,"resources":[],"tools":[{"name":"Claude","url":"https://claude.ai","affiliate":false}],"xp":40,"metric_to_track":"Hours per job"}]}],"weekly_metrics":["proposals_sent","clients","reviews"],"earning_milestones":[{"label":"Weeks 2–6","range":"$0–$300","note":"Landing the first clients can take a few weeks of steady proposals."},{"label":"Months 2–4","range":"$300–$1,500 / month","note":"Common once you have 5+ good reviews."},{"label":"Months 6–12","range":"$1,000–$3,000 / month","note":"Typical with repeat clients and higher prices."}]}$roadmap$),
  ('ai-freelancing', 'pl', $roadmap${"hustle_slug":"ai-freelancing","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Oferta i portfolio","goal":"Wybierz jedną konkretną usługę, przygotuj 3 próbki do portfolio i załóż profile.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz jedną usługę dla jednego typu klienta","why":"Klienci zatrudniają specjalistów. „Opisy produktów dla sklepów Shopify” wygrywa więcej zleceń niż „piszę wszystko”.","instructions":["Wypisz usługi, które dobrze wykonasz z pomocą AI (copywriting, tłumaczenia, grafika, montaż, research).","Wyszukaj każdą na Fiverr i Upwork i zanotuj popyt oraz typowe ceny.","Wybierz jedną usługę i jeden typ klienta, który rozumiesz."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Wybrana usługa"},{"id":"p1s2","title":"Przygotuj 3 próbki do portfolio","why":"Klienci kupują to, co widzą. Trzy mocne próbki dla docelowego klienta są lepsze niż każdy opis umiejętności.","instructions":["Wybierz 3 realistyczne zadania, za które zapłaciłby Twój klient.","Używaj AI do przyspieszenia szkiców, a potem starannie redaguj, by wynik był poprawny i brzmiał naturalnie.","Pokaż przed/po lub wyjaśnij efekt, jaki dałaby każda próbka."],"est_minutes":240,"resources":[],"tools":[{"name":"Claude","url":"https://claude.ai","affiliate":false},{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Gotowe próbki"},{"id":"p1s3","title":"Załóż profile na Fiverr i Upwork","why":"Skupiony profil z czytelnym nagłówkiem i próbkami sprawia, że klienci ufają nowemu freelancerowi.","instructions":["Dodaj przyjazne, wyraźne zdjęcie profilowe.","Napisz nagłówek z usługą i typem klienta (np. „Opisy produktów SEO dla sklepów Shopify”).","Dodaj 3 próbki do sekcji portfolio.","Uzupełnij każde pole profilu; pełne profile są wyżej w wynikach."],"est_minutes":90,"resources":[{"title":"Centrum pomocy Upwork (ang.)","url":"https://support.upwork.com"}],"tools":[{"name":"Fiverr","url":"https://www.fiverr.com","affiliate":false},{"name":"Upwork","url":"https://www.upwork.com","affiliate":false}],"xp":40,"metric_to_track":"Aktywne profile"},{"id":"p1s4","title":"Ustal proces kontroli jakości","why":"AI przyspiesza pracę, ale opinie zależą od jakości. Checklista chroni reputację przy każdym zleceniu.","instructions":["Napisz 5-punktową checklistę: sprawdzone fakty, zgodność z briefem, dopasowany ton, czyste formatowanie, poprawna pisownia.","Nie wklejaj poufnych danych klientów do narzędzi AI bez ich zgody.","Jeśli klient zapyta, mów szczerze, jak korzystasz z AI."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Gotowa checklista"}]},{"id":"p2","title":"Pierwsi klienci","goal":"Opublikuj ofertę, wysyłaj dopasowane propozycje i zdobądź pierwszych 1–3 klientów.","weeks":"3-5","steps":[{"id":"p2s1","title":"Opublikuj usługę w 3 pakietach","why":"Trzy pakiety (podstawowy, standardowy, premium) pozwalają wybierać, a klienci często biorą środkowy.","instructions":["Utwórz usługę na Fiverr z jasnym tytułem, próbkami i 3 pakietami.","Zacznij od cen nieco poniżej rynku, by zdobyć pierwsze opinie.","Użyj grafiki pokazującej efekt, a nie tylko Twoje imię."],"est_minutes":90,"resources":[],"tools":[{"name":"Fiverr","url":"https://www.fiverr.com","affiliate":false}],"xp":40,"metric_to_track":"Aktywna usługa"},{"id":"p2s2","title":"Wyślij 10 dopasowanych propozycji","why":"Ogólne propozycje są ignorowane. Nawiązanie do konkretnego problemu klienta i trafnej próbki daje odpowiedzi.","instructions":["Znajdź 10 świeżych zleceń na Upwork dokładnie pasujących do usługi.","Zaczynaj każdą propozycję od celu klienta własnymi słowami.","Podlinkuj jedną trafną próbkę i zaproponuj jasny pierwszy krok.","Zmieść się w 150 słowach."],"est_minutes":180,"resources":[],"tools":[{"name":"Upwork","url":"https://www.upwork.com","affiliate":false}],"xp":50,"metric_to_track":"Wysłane propozycje"},{"id":"p2s3","title":"Przekrocz oczekiwania przy pierwszym zleceniu","why":"Pierwsze opinie decydują o tempie rozwoju. Zachwycony pierwszy klient jest wart więcej niż wynagrodzenie.","instructions":["Potwierdź brief na piśmie przed rozpoczęciem.","Oddaj pracę przed terminem z krótką notatką wyjaśniającą decyzje.","Gdy klient jest zadowolony, uprzejmie poproś o opinię."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Płacący klienci"},{"id":"p2s4","title":"Śledź dochody, opłaty i podatki","why":"Platformy pobierają opłatę od każdego zlecenia. Znajomość realnej stawki godzinowej pokazuje, kiedy podnieść ceny.","instructions":["Zapisuj każde zlecenie: klient, cena, opłata platformy, godziny, zarobek netto na godzinę.","Aktualizuj zapis przed każdym cotygodniowym podsumowaniem.","Sprawdź, jak rozlicza się dochody z freelancingu w Twoim kraju (w Polsce np. działalność nierejestrowana)."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Zarobek netto na godzinę"}]},{"id":"p3","title":"Rozpęd","goal":"Utrzymuj stały napływ propozycji, zbieraj opinie i podnieś ceny.","weeks":"6-8","steps":[{"id":"p3s1","title":"Wyślij 20 kolejnych propozycji","why":"Na początku freelancing to gra liczb. Ilość połączona z jakością daje stałe zlecenia.","instructions":["Ustal dzienny cel 2–3 propozycji.","Zapisuj najlepiej działające otwarcia jako szablony, ale zawsze je personalizuj.","Śledź odsetek odpowiedzi i zmieniaj to, co nie działa."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Wysłane propozycje"},{"id":"p3s2","title":"Podnieś ceny","why":"Po 3–5 dobrych opiniach masz już ugruntowaną pozycję na platformie. Ceny powinny to odzwierciedlać.","instructions":["Podnieś ceny pakietów o 20–30%.","Obecnym klientom możesz przez jakiś czas zostawić dotychczasową stawkę.","Obserwuj, czy zamówień nie ubywa, i dostosuj po 2 tygodniach."],"est_minutes":30,"resources":[],"tools":[],"xp":40,"metric_to_track":"Średnia wartość zlecenia"},{"id":"p3s3","title":"Przygotuj szablony wiadomości do klientów","why":"Szybka, jasna komunikacja zdobywa oceny 5 gwiazdek i oszczędza godziny tygodniowo.","instructions":["Napisz szablony: pierwsza odpowiedź, pytania do briefu, oddanie pracy, poprawki, prośba o opinię.","Określ, ile poprawek obejmuje każdy pakiet.","Odpowiadaj na nowe wiadomości w ciągu kilku godzin."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Średnia ocena"}]},{"id":"p4","title":"Stały dochód","goal":"Zamień jednorazowe zlecenia w stałą współpracę i zbuduj obecność poza platformami.","weeks":"9-12","steps":[{"id":"p4s1","title":"Zaproponuj miesięczny pakiet dawnym klientom","why":"Powracający klienci to najłatwiejszy dochód. Miesięczny pakiet zamienia dobrych klientów w przewidywalny przychód.","instructions":["Zaprojektuj miesięczny pakiet (np. 10 opisów produktów miesięcznie).","Wyślij 3 najlepszym klientom krótką propozycję.","Klientów z platformy obsługuj i rozliczaj na platformie, zgodnie z jej zasadami."],"est_minutes":60,"resources":[],"tools":[],"xp":50,"metric_to_track":"Powracający klienci"},{"id":"p4s2","title":"Zbuduj proste portfolio i profil na LinkedIn","why":"Klienci pozyskani samodzielnie nie oznaczają prowizji platformy. Portfolio i profil na LinkedIn umożliwiają bezpośredni kontakt.","instructions":["Stwórz jednostronicowe portfolio z 5 najlepszymi próbkami i opiniami.","Zmień nagłówek na LinkedIn, by pasował do usługi.","Publikuj co tydzień jedną przydatną wskazówkę lub przykład przed/po."],"est_minutes":120,"resources":[],"tools":[{"name":"Behance","url":"https://www.behance.net","affiliate":false}],"xp":40,"metric_to_track":"Bezpośrednie zapytania"},{"id":"p4s3","title":"Przyspiesz realizację powtarzalnymi procesami z AI","why":"Zapisane polecenia i szablony skracają czas realizacji, co podnosi realną stawkę godzinową.","instructions":["Zapisz najlepsze polecenia i szablony dokumentów w jednym miejscu.","Zmierz czas trzech zleceń przed i po ich użyciu.","Zaoszczędzony czas zainwestuj w kolejne propozycje lub droższą usługę."],"est_minutes":60,"resources":[],"tools":[{"name":"Claude","url":"https://claude.ai","affiliate":false}],"xp":40,"metric_to_track":"Godziny na zlecenie"}]}],"weekly_metrics":["proposals_sent","clients","reviews"],"earning_milestones":[{"label":"Tygodnie 2–6","range":"0–300 $","note":"Zdobycie pierwszych klientów może zająć kilka tygodni regularnych propozycji."},{"label":"Miesiące 2–4","range":"300–1500 $ / mies.","note":"Częste po zebraniu 5+ dobrych opinii."},{"label":"Miesiące 6–12","range":"1000–3000 $ / mies.","note":"Typowe przy stałych klientach i wyższych cenach."}]}$roadmap$),
  ('amazon-kdp', 'en', $roadmap${"hustle_slug":"amazon-kdp","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Research & account","goal":"Find a book niche with proven demand and set up your KDP account.","weeks":"1-2","steps":[{"id":"p1s1","title":"Find a niche with proven demand","why":"Books sell when people already search for them. A good niche has steady sellers but not a wall of big-brand competitors.","instructions":["Browse Amazon for low-content books (journals, logbooks, puzzle books) or short guides in areas you know.","Open 10 books per idea and check their Best Sellers Rank. A rank under about 100,000 usually means regular sales.","Read 1- and 3-star reviews to see what buyers wish were better.","Pick one niche and one specific buyer (e.g. ‘gratitude journal for new moms’)."],"est_minutes":90,"resources":[],"tools":[{"name":"Publisher Rocket","url":"https://publisherrocket.com","affiliate":false}],"xp":30,"metric_to_track":"Niche chosen"},{"id":"p1s2","title":"Set up your KDP account","why":"KDP lets you publish for free. Amazon prints each copy when it's ordered, so there's no stock to buy.","instructions":["Create an account at KDP with your Amazon login.","Complete the tax interview and add bank details for royalty payments.","Read KDP's content guidelines, including the rules for AI-generated content."],"est_minutes":45,"resources":[{"title":"KDP Help Center","url":"https://kdp.amazon.com/en_US/help"}],"tools":[{"name":"Amazon KDP","url":"https://kdp.amazon.com","affiliate":false}],"xp":30,"metric_to_track":"Account ready"},{"id":"p1s3","title":"Collect keywords and categories","why":"Amazon is a search engine. The right title, subtitle and keywords decide whether buyers ever see your book.","instructions":["Type your niche into Amazon's search bar and write down the autocomplete suggestions.","Pick 7 keyword phrases for the 7 keyword boxes in KDP.","Note 2–3 specific categories where similar books rank well."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"7 keywords chosen"},{"id":"p1s4","title":"Plan your first book","why":"A clear outline (pages, sections, trim size) turns a vague idea into a book you can finish in two weeks.","instructions":["Choose a common trim size (e.g. 6×9 in for guides, 8.5×11 in for activity books).","Outline sections and page count.","List what will make your book better than the reviews you read."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Outline ready"}]},{"id":"p2","title":"First book","goal":"Create, check and publish your first title.","weeks":"3-5","steps":[{"id":"p2s1","title":"Create the interior","why":"The interior is what buyers use every day. Clean layout and useful content earn good reviews.","instructions":["Design the pages in Canva or a word processor at your exact trim size, with margins for printing.","Keep text and important elements inside the safe area KDP specifies.","Export a print-ready PDF and check every page."],"est_minutes":480,"resources":[{"title":"KDP Help Center","url":"https://kdp.amazon.com/en_US/help"}],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":60,"metric_to_track":"Interior PDF ready"},{"id":"p2s2","title":"Design a cover that stands out","why":"Buyers see a thumbnail first. A clear, readable cover in your niche's style gets the click.","instructions":["Use KDP's cover calculator to get the exact full-cover size for your page count.","Make the title readable even at thumbnail size.","Compare your cover side by side with the top 10 books in your niche."],"est_minutes":120,"resources":[{"title":"KDP cover calculator","url":"https://kdp.amazon.com/cover-calculator"}],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Cover ready"},{"id":"p2s3","title":"Publish your first title","why":"Publishing teaches you the whole KDP process. After review, your book can be for sale within a few days.","instructions":["Enter the title, subtitle and description using your keywords naturally.","Add your 7 keywords and choose categories.","Upload interior and cover, fix any issues in the previewer, and set a competitive price.","Disclose AI-generated content if you used AI, as KDP requires."],"est_minutes":90,"resources":[],"tools":[{"name":"Amazon KDP","url":"https://kdp.amazon.com","affiliate":false}],"xp":50,"metric_to_track":"Titles published"},{"id":"p2s4","title":"Order an author copy","why":"Holding the printed book reveals problems a screen hides: margins, paper, color.","instructions":["Order one author copy at printing cost.","Check every page and the cover.","Fix and re-upload anything that's off."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Author copy checked"}]},{"id":"p3","title":"Build a catalog","goal":"Publish 3–4 more titles in the same niche and get your first reviews.","weeks":"6-8","steps":[{"id":"p3s1","title":"Publish 3 related titles","why":"Most KDP income comes from a catalog, not one hit. Related titles also get shown next to each other.","instructions":["Create variations for new buyers, themes or formats (e.g. large print, a different audience).","Reuse your interior template to save time.","Keep in mind that KDP limits how many titles you can publish per day."],"est_minutes":600,"resources":[],"tools":[],"xp":60,"metric_to_track":"Titles published"},{"id":"p3s2","title":"Get honest first reviews","why":"Reviews build trust with buyers. Amazon has strict rules, so only ask in allowed ways.","instructions":["Add a short, polite note at the end of your book asking readers for an honest review.","Never pay for reviews or ask family and friends to review. Amazon removes those.","Share the book in communities where it genuinely helps, following their rules."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Reviews"},{"id":"p3s3","title":"Track royalties and taxes","why":"Royalties arrive about two months after the sales month. Tracking shows which titles really earn.","instructions":["Check the KDP Reports page weekly.","Log units sold and royalties per title in a sheet.","Check how book royalties are taxed where you live."],"est_minutes":30,"resources":[],"tools":[],"xp":30,"metric_to_track":"Royalties per title"}]},{"id":"p4","title":"Scale","goal":"Double down on titles that sell and test small ads.","weeks":"9-12","steps":[{"id":"p4s1","title":"Find your best title and why it sells","why":"Your data now shows which niche angle works. The next books should build on it.","instructions":["Compare sales per title over the last 30 days.","Note what the best seller does differently (keywords, cover, audience).","Plan 3 new titles that use the same winning angle."],"est_minutes":60,"resources":[],"tools":[],"xp":50,"metric_to_track":"Sales per title"},{"id":"p4s2","title":"Test Amazon Ads on your best title","why":"Small, targeted ads can push a proven book higher in search. Unproven books usually just burn budget.","instructions":["Start an automatic Sponsored Products campaign with a small daily budget.","After 2 weeks, check which search terms led to sales.","Keep only campaigns where ad cost is lower than your royalty."],"est_minutes":60,"resources":[],"tools":[{"name":"Amazon Ads","url":"https://advertising.amazon.com","affiliate":false}],"xp":50,"metric_to_track":"Ad cost per sale"},{"id":"p4s3","title":"Publish your next 3 titles","why":"Authors with 10+ titles in a good niche are the ones who reach steady monthly income.","instructions":["Create the 3 titles you planned from your best seller's angle.","Link them together as a series where it makes sense.","Keep a steady rhythm of 1–2 new titles per month."],"est_minutes":480,"resources":[],"tools":[],"xp":40,"metric_to_track":"Titles published"}]}],"weekly_metrics":["titles_published","sales","reviews"],"earning_milestones":[{"label":"Months 1–3","range":"$0–$100 / month","note":"Early titles often sell a few copies while you learn."},{"label":"Months 4–6","range":"$50–$400 / month","note":"A catalog of 5–10 related titles in one niche."},{"label":"Months 6–12","range":"$200–$1,500 / month","note":"Typical for authors with 10+ titles and some ads."}]}$roadmap$),
  ('amazon-kdp', 'pl', $roadmap${"hustle_slug":"amazon-kdp","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Badanie rynku i konto","goal":"Znajdź niszę książkową ze sprawdzonym popytem i załóż konto KDP.","weeks":"1-2","steps":[{"id":"p1s1","title":"Znajdź niszę ze sprawdzonym popytem","why":"Książki sprzedają się, gdy ludzie już ich szukają. Dobra nisza ma stale sprzedające się tytuły, ale nie mur dużych wydawnictw.","instructions":["Przejrzyj Amazon pod kątem książek low-content (dzienniki, logbooki, łamigłówki) lub krótkich poradników z dziedzin, które znasz.","Otwórz po 10 książek na pomysł i sprawdź Best Sellers Rank. Ranking poniżej około 100 000 zwykle oznacza regularną sprzedaż.","Przeczytaj opinie 1- i 3-gwiazdkowe, by zobaczyć, czego brakuje kupującym.","Wybierz jedną niszę i konkretnego odbiorcę (np. „dziennik wdzięczności dla młodych mam”)."],"est_minutes":90,"resources":[],"tools":[{"name":"Publisher Rocket","url":"https://publisherrocket.com","affiliate":false}],"xp":30,"metric_to_track":"Wybrana nisza"},{"id":"p1s2","title":"Załóż konto KDP","why":"KDP pozwala publikować za darmo. Amazon drukuje każdy egzemplarz po zamówieniu, więc nie kupujesz nakładu.","instructions":["Załóż konto na KDP, logując się kontem Amazon.","Wypełnij formularz podatkowy i dodaj dane bankowe do wypłat tantiem.","Przeczytaj wytyczne KDP dotyczące treści, w tym zasady dla treści generowanych przez AI."],"est_minutes":45,"resources":[{"title":"Centrum pomocy KDP (ang.)","url":"https://kdp.amazon.com/en_US/help"}],"tools":[{"name":"Amazon KDP","url":"https://kdp.amazon.com","affiliate":false}],"xp":30,"metric_to_track":"Konto gotowe"},{"id":"p1s3","title":"Zbierz słowa kluczowe i kategorie","why":"Amazon to wyszukiwarka. Właściwy tytuł, podtytuł i słowa kluczowe decydują, czy kupujący w ogóle zobaczą książkę.","instructions":["Wpisz niszę w wyszukiwarkę Amazona i zapisz podpowiedzi autouzupełniania.","Wybierz 7 fraz do 7 pól słów kluczowych w KDP.","Zanotuj 2–3 konkretne kategorie, w których podobne książki mają dobry ranking."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"7 wybranych słów kluczowych"},{"id":"p1s4","title":"Zaplanuj pierwszą książkę","why":"Jasny plan (strony, sekcje, format) zamienia ogólny pomysł w książkę, którą skończysz w dwa tygodnie.","instructions":["Wybierz popularny format (np. 6×9 cala dla poradników, 8,5×11 cala dla książek z zadaniami).","Rozpisz sekcje i liczbę stron.","Zapisz, co sprawi, że książka będzie lepsza od tych z przeczytanych opinii."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Gotowy plan"}]},{"id":"p2","title":"Pierwsza książka","goal":"Stwórz, sprawdź i opublikuj pierwszy tytuł.","weeks":"3-5","steps":[{"id":"p2s1","title":"Przygotuj wnętrze książki","why":"Wnętrze to to, z czego kupujący korzystają na co dzień. Czysty układ i przydatna treść zbierają dobre opinie.","instructions":["Zaprojektuj strony w Canvie lub edytorze tekstu w dokładnym formacie, z marginesami do druku.","Trzymaj tekst i ważne elementy w bezpiecznym obszarze wskazanym przez KDP.","Wyeksportuj PDF gotowy do druku i sprawdź każdą stronę."],"est_minutes":480,"resources":[{"title":"Centrum pomocy KDP (ang.)","url":"https://kdp.amazon.com/en_US/help"}],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":60,"metric_to_track":"Gotowy PDF wnętrza"},{"id":"p2s2","title":"Zaprojektuj wyróżniającą się okładkę","why":"Kupujący najpierw widzą miniaturę. Czytelna okładka w stylu niszy zdobywa kliknięcie.","instructions":["Użyj kalkulatora okładek KDP, by poznać dokładny rozmiar okładki dla liczby stron.","Zadbaj, by tytuł był czytelny nawet w miniaturze.","Porównaj okładkę obok 10 najlepszych książek w niszy."],"est_minutes":120,"resources":[{"title":"Kalkulator okładek KDP","url":"https://kdp.amazon.com/cover-calculator"}],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Gotowa okładka"},{"id":"p2s3","title":"Opublikuj pierwszy tytuł","why":"Publikacja uczy całego procesu KDP. Po weryfikacji książka może być w sprzedaży w ciągu kilku dni.","instructions":["Wpisz tytuł, podtytuł i opis, naturalnie używając słów kluczowych.","Dodaj 7 słów kluczowych i wybierz kategorie.","Wgraj wnętrze i okładkę, popraw błędy w podglądzie i ustaw konkurencyjną cenę.","Jeśli korzystasz z AI, zaznacz treści wygenerowane przez AI, zgodnie z wymogami KDP."],"est_minutes":90,"resources":[],"tools":[{"name":"Amazon KDP","url":"https://kdp.amazon.com","affiliate":false}],"xp":50,"metric_to_track":"Opublikowane tytuły"},{"id":"p2s4","title":"Zamów egzemplarz autorski","why":"Wydrukowana książka ujawnia problemy niewidoczne na ekranie: marginesy, papier, kolor.","instructions":["Zamów jeden egzemplarz autorski w cenie druku.","Sprawdź każdą stronę i okładkę.","Popraw i wgraj ponownie wszystko, co odstaje."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Sprawdzony egzemplarz"}]},{"id":"p3","title":"Budowa katalogu","goal":"Opublikuj 3–4 kolejne tytuły w tej samej niszy i zdobądź pierwsze opinie.","weeks":"6-8","steps":[{"id":"p3s1","title":"Opublikuj 3 powiązane tytuły","why":"Większość dochodu z KDP pochodzi z katalogu, a nie z jednego hitu. Powiązane tytuły wyświetlają się też obok siebie.","instructions":["Twórz warianty dla nowych odbiorców, motywów lub formatów (np. duży druk, inna grupa).","Korzystaj z szablonu wnętrza, by oszczędzić czas.","Pamiętaj, że KDP ogranicza liczbę tytułów publikowanych dziennie."],"est_minutes":600,"resources":[],"tools":[],"xp":60,"metric_to_track":"Opublikowane tytuły"},{"id":"p3s2","title":"Zdobądź pierwsze uczciwe opinie","why":"Opinie budują zaufanie kupujących. Amazon ma ścisłe zasady, więc proś tylko w dozwolony sposób.","instructions":["Dodaj na końcu książki krótką, uprzejmą prośbę o szczerą opinię.","Nigdy nie płać za opinie ani nie proś o nie rodziny i znajomych. Amazon je usuwa.","Poleć książkę w społecznościach, w których naprawdę pomoże, zgodnie z ich zasadami."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Opinie"},{"id":"p3s3","title":"Śledź tantiemy i podatki","why":"Tantiemy wpływają około dwóch miesięcy po miesiącu sprzedaży. Śledzenie pokazuje, które tytuły naprawdę zarabiają.","instructions":["Co tydzień sprawdzaj raporty w KDP.","Zapisuj w arkuszu sprzedane egzemplarze i tantiemy dla każdego tytułu.","Sprawdź, jak rozlicza się tantiemy w Twoim kraju."],"est_minutes":30,"resources":[],"tools":[],"xp":30,"metric_to_track":"Tantiemy na tytuł"}]},{"id":"p4","title":"Skalowanie","goal":"Postaw na tytuły, które się sprzedają, i przetestuj małe reklamy.","weeks":"9-12","steps":[{"id":"p4s1","title":"Znajdź najlepszy tytuł i powód jego sprzedaży","why":"Dane pokazują już, które podejście do niszy działa. Kolejne książki powinny na nim bazować.","instructions":["Porównaj sprzedaż tytułów z ostatnich 30 dni.","Zanotuj, czym różni się bestseller (słowa kluczowe, okładka, odbiorcy).","Zaplanuj 3 nowe tytuły korzystające z tego samego podejścia."],"est_minutes":60,"resources":[],"tools":[],"xp":50,"metric_to_track":"Sprzedaż na tytuł"},{"id":"p4s2","title":"Przetestuj Amazon Ads na najlepszym tytule","why":"Małe, celowane reklamy mogą podnieść sprawdzoną książkę w wynikach. Przy niesprawdzonych zwykle tylko przepalają budżet.","instructions":["Uruchom automatyczną kampanię Sponsored Products z małym dziennym budżetem.","Po 2 tygodniach sprawdź, które wyszukiwane frazy przyniosły sprzedaż.","Zostaw tylko kampanie, w których koszt reklamy jest niższy niż tantiemy."],"est_minutes":60,"resources":[],"tools":[{"name":"Amazon Ads","url":"https://advertising.amazon.com","affiliate":false}],"xp":50,"metric_to_track":"Koszt reklamy na sprzedaż"},{"id":"p4s3","title":"Opublikuj kolejne 3 tytuły","why":"Autorzy z 10+ tytułami w dobrej niszy to ci, którzy osiągają stały miesięczny dochód.","instructions":["Stwórz 3 zaplanowane tytuły w oparciu o podejście bestsellera.","Połącz je w serię, gdzie ma to sens.","Utrzymuj rytm 1–2 nowych tytułów miesięcznie."],"est_minutes":480,"resources":[],"tools":[],"xp":40,"metric_to_track":"Opublikowane tytuły"}]}],"weekly_metrics":["titles_published","sales","reviews"],"earning_milestones":[{"label":"Miesiące 1–3","range":"0–100 $ / mies.","note":"Pierwsze tytuły często sprzedają kilka egzemplarzy, gdy się uczysz."},{"label":"Miesiące 4–6","range":"50–400 $ / mies.","note":"Katalog 5–10 powiązanych tytułów w jednej niszy."},{"label":"Miesiące 6–12","range":"200–1500 $ / mies.","note":"Typowe dla autorów z 10+ tytułami i niewielkimi reklamami."}]}$roadmap$),
  ('etsy-digital-products', 'en', $roadmap${"hustle_slug":"etsy-digital-products","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Product idea & shop","goal":"Find a digital product people already buy and open your Etsy shop.","weeks":"1-2","steps":[{"id":"p1s1","title":"Research what already sells","why":"Digital products win when they solve a clear, specific need. Copying the need (not the design) of proven bestsellers removes guesswork.","instructions":["Search Etsy for categories like ‘budget planner printable’, ‘wedding seating chart template’ or ‘nursery wall art’.","Open 10 bestsellers and note the price, number of reviews and what buyers praise or complain about.","Look for complaints you could fix (too generic, hard to edit, missing sizes).","Pick one product type and one audience, e.g. ‘ADHD-friendly weekly planner for students’."],"est_minutes":60,"resources":[{"title":"Etsy Seller Handbook","url":"https://www.etsy.com/seller-handbook"}],"tools":[{"name":"eRank","url":"https://erank.com","affiliate":false}],"xp":30,"metric_to_track":"1 product type and audience chosen"},{"id":"p1s2","title":"Open your Etsy shop","why":"Etsy already has millions of buyers searching for printables and templates. You borrow its traffic from day one.","instructions":["Create an Etsy seller account with your ID and bank details. Some countries pay a small one-time setup fee.","Choose a shop name that fits your audience, not just your first product.","Write a short shop ‘About’ and set a clear policy that digital files are non-refundable once downloaded."],"est_minutes":60,"resources":[{"title":"Etsy fees explained","url":"https://www.etsy.com/legal/fees/"}],"tools":[{"name":"Etsy","url":"https://www.etsy.com/sell","affiliate":false}],"xp":30,"metric_to_track":"Shop open"},{"id":"p1s3","title":"Create your first product","why":"One polished product teaches you the whole process: design, export, listing. Every next product gets faster.","instructions":["Design the product in Canva or a similar tool, fixing the complaints you found in your research.","Export print-ready PDFs in common sizes (US Letter and A4), or an editable template link if it's a template.","Print one page yourself to check margins and readability.","Use only fonts and graphics your license allows for commercial use."],"est_minutes":180,"resources":[{"title":"Canva content license","url":"https://www.canva.com/policies/content-license-agreement/"}],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Product files ready"},{"id":"p1s4","title":"Make listing images that sell","why":"Buyers can't touch a digital file. Your images must show exactly what they get and how it looks in real life.","instructions":["Create a main image that shows the product clearly on a clean background, with 3–5 words of benefit text.","Add images showing inside pages, sizes included and a ‘what you get’ summary.","Add one mockup of the product in use (on a desk, a wall or a tablet)."],"est_minutes":60,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":30,"metric_to_track":"Images per listing"}]},{"id":"p2","title":"Launch your catalog","goal":"Publish 15 listings with clear titles, tags and delivery files.","weeks":"3-5","steps":[{"id":"p2s1","title":"Publish your first listing","why":"A live listing starts collecting data about views and clicks. Nothing is learned while a product sits in a folder.","instructions":["Create a listing as a digital item and upload your files (Etsy allows up to 5 files, 20 MB each).","Write a title that starts with the buyer's search phrase, and use all 13 tags.","Explain in the description what's included, which sizes, and that nothing physical is shipped.","Price it in line with similar bestsellers, then publish."],"est_minutes":60,"resources":[],"tools":[{"name":"eRank","url":"https://erank.com","affiliate":false}],"xp":40,"metric_to_track":"Listings live"},{"id":"p2s2","title":"Build 14 more products","why":"Digital shops grow with catalog size. 15 related products help buyers find you and buy more than one.","instructions":["Create variations of your first product: new colors, styles, audiences or sizes.","Add complementary products the same buyer needs (e.g. a meal planner next to a budget planner).","Reuse your templates so each new product takes under an hour.","Publish each one with its own search phrase in the title."],"est_minutes":480,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":60,"metric_to_track":"Listings live"},{"id":"p2s3","title":"Create a bundle","why":"Bundles raise your average order value without new design work. Many buyers pick the bigger package.","instructions":["Group 3–5 related products into one listing.","Price it lower than buying them separately and say so in the first image.","Link the bundle from each single product's description."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Bundle sales"},{"id":"p2s4","title":"Set up simple money tracking","why":"Fees add up. Tracking real profit each week keeps your pricing honest.","instructions":["Create a sheet with: date, product, price, Etsy fees, profit.","Update it weekly before your check-in.","Check how side income is taxed where you live, and set aside part of your profit."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Weekly profit"}]},{"id":"p3","title":"Traction","goal":"Improve what gets views and grow to 30 listings.","weeks":"6-8","steps":[{"id":"p3s1","title":"Improve your weakest listings","why":"Your stats show which listings get seen but not bought. Better images and titles often fix that fast.","instructions":["In Etsy Stats, sort listings by views and find ones with no favorites or sales.","Replace the main image with a clearer one showing the benefit.","Rewrite the title around a more specific search phrase.","Change one thing at a time and wait a week."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Listings improved"},{"id":"p3s2","title":"Grow to 30 listings","why":"Around 30 listings, most shops start seeing sales every week instead of once in a while.","instructions":["Make more of whatever got the most favorites so far.","Target long, specific search phrases with less competition.","Keep a steady pace: 3–5 new listings per week."],"est_minutes":480,"resources":[],"tools":[],"xp":60,"metric_to_track":"Listings live"},{"id":"p3s3","title":"Ask buyers for reviews","why":"Reviews build trust and help your ranking. Many happy buyers simply forget to leave one.","instructions":["Add a friendly ‘thank you’ page inside your files with a short note asking for a review.","Reply to every message quickly and kindly.","Never offer discounts or freebies in exchange for reviews. Etsy doesn't allow it."],"est_minutes":30,"resources":[],"tools":[],"xp":30,"metric_to_track":"Reviews"}]},{"id":"p4","title":"Scale","goal":"Double down on winners and bring in traffic from outside Etsy.","weeks":"9-12","steps":[{"id":"p4s1","title":"Expand your best seller into a product line","why":"When one product sells, the same buyers want related versions. It's the fastest way to grow revenue.","instructions":["Find your top product by sales in the last 30 days.","Create 5 versions for new audiences, styles or occasions.","Bundle the whole line into one premium listing."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Sales from the product line"},{"id":"p4s2","title":"Bring in Pinterest traffic","why":"Planners, printables and wall art are some of Pinterest's most searched ideas. One good pin can send visitors for months.","instructions":["Create a free Pinterest business account and claim your Etsy shop.","Make 2–3 vertical pins per product with a benefit headline.","Pin 3–5 times a day, spread across your products."],"est_minutes":90,"resources":[{"title":"Pinterest Business","url":"https://business.pinterest.com"}],"tools":[],"xp":50,"metric_to_track":"Shop visits from Pinterest"},{"id":"p4s3","title":"Test Etsy Ads on proven products","why":"Digital products have no shipping costs, so ads can be profitable on listings that already convert.","instructions":["Advertise only listings that have sold at least twice.","Start with $1–3 per day.","After 2 weeks, keep ads only where ad cost per sale is below your price minus fees."],"est_minutes":45,"resources":[],"tools":[],"xp":40,"metric_to_track":"Ad cost per sale"}]}],"weekly_metrics":["listings","shop_visits","sales"],"earning_milestones":[{"label":"Months 1–3","range":"$0–$150 / month","note":"First sales usually come after 10–20 listings."},{"label":"Months 4–6","range":"$100–$400 / month","note":"Bundles and product lines lift your average order."},{"label":"Months 6–12","range":"$200–$1,000 / month","note":"Typical for catalogs of 30+ products with Pinterest traffic."}]}$roadmap$),
  ('etsy-digital-products', 'pl', $roadmap${"hustle_slug":"etsy-digital-products","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Pomysł na produkt i sklep","goal":"Znajdź produkt cyfrowy, który ludzie już kupują, i otwórz sklep na Etsy.","weeks":"1-2","steps":[{"id":"p1s1","title":"Sprawdź, co już się sprzedaje","why":"Produkty cyfrowe wygrywają, gdy rozwiązują jasną, konkretną potrzebę. Wzorowanie się na potrzebie (nie na projekcie) sprawdzonych bestsellerów eliminuje zgadywanie.","instructions":["Wyszukaj na Etsy kategorie typu „budget planner printable”, „wedding seating chart template” czy „nursery wall art”.","Otwórz 10 bestsellerów i zanotuj cenę, liczbę opinii oraz to, co kupujący chwalą i krytykują.","Szukaj zarzutów, które możesz naprawić (zbyt ogólne, trudne do edycji, brak rozmiarów).","Wybierz jeden typ produktu i jedną grupę odbiorców, np. „tygodniowy planer dla studentów z ADHD”."],"est_minutes":60,"resources":[{"title":"Etsy Seller Handbook (ang.)","url":"https://www.etsy.com/seller-handbook"}],"tools":[{"name":"eRank","url":"https://erank.com","affiliate":false}],"xp":30,"metric_to_track":"Wybrany typ produktu i grupa odbiorców"},{"id":"p1s2","title":"Otwórz sklep na Etsy","why":"Na Etsy miliony kupujących już szukają plików do druku i szablonów. Od pierwszego dnia korzystasz z tego ruchu.","instructions":["Załóż konto sprzedawcy na Etsy z dokumentem tożsamości i danymi bankowymi. W niektórych krajach obowiązuje niewielka jednorazowa opłata.","Wybierz nazwę sklepu dopasowaną do odbiorców, a nie tylko do pierwszego produktu.","Napisz krótką sekcję „O nas” i jasno zaznacz, że pliki cyfrowe po pobraniu nie podlegają zwrotowi."],"est_minutes":60,"resources":[{"title":"Opłaty na Etsy (ang.)","url":"https://www.etsy.com/legal/fees/"}],"tools":[{"name":"Etsy","url":"https://www.etsy.com/sell","affiliate":false}],"xp":30,"metric_to_track":"Sklep otwarty"},{"id":"p1s3","title":"Stwórz pierwszy produkt","why":"Jeden dopracowany produkt uczy całego procesu: projekt, eksport, oferta. Każdy kolejny powstaje szybciej.","instructions":["Zaprojektuj produkt w Canvie lub podobnym narzędziu, poprawiając wady znalezione w badaniu.","Wyeksportuj pliki PDF gotowe do druku w popularnych formatach (US Letter i A4) albo link do edytowalnego szablonu.","Wydrukuj jedną stronę, by sprawdzić marginesy i czytelność.","Używaj tylko czcionek i grafik, na które licencja pozwala w celach komercyjnych."],"est_minutes":180,"resources":[{"title":"Licencja na treści Canva","url":"https://www.canva.com/policies/content-license-agreement/"}],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Gotowe pliki produktu"},{"id":"p1s4","title":"Przygotuj zdjęcia oferty, które sprzedają","why":"Kupujący nie dotkną pliku cyfrowego. Zdjęcia muszą dokładnie pokazać, co dostają i jak to wygląda w realnym życiu.","instructions":["Przygotuj główne zdjęcie z produktem na czystym tle i 3–5 słowami o korzyści.","Dodaj zdjęcia wnętrza, dostępnych rozmiarów i podsumowanie „co dostajesz”.","Dodaj jeden mockup produktu w użyciu (na biurku, ścianie lub tablecie)."],"est_minutes":60,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":30,"metric_to_track":"Zdjęcia na ofertę"}]},{"id":"p2","title":"Start katalogu","goal":"Opublikuj 15 ofert z jasnymi tytułami, tagami i plikami do pobrania.","weeks":"3-5","steps":[{"id":"p2s1","title":"Opublikuj pierwszą ofertę","why":"Aktywna oferta zaczyna zbierać dane o wyświetleniach i kliknięciach. Produkt w folderze niczego Cię nie nauczy.","instructions":["Utwórz ofertę jako produkt cyfrowy i wgraj pliki (Etsy pozwala na 5 plików po 20 MB).","Napisz tytuł zaczynający się od frazy, którą wpisuje kupujący, i wykorzystaj wszystkie 13 tagów.","W opisie wyjaśnij, co zawiera plik, jakie są rozmiary i że nic nie jest wysyłane fizycznie.","Ustal cenę podobną do bestsellerów i opublikuj."],"est_minutes":60,"resources":[],"tools":[{"name":"eRank","url":"https://erank.com","affiliate":false}],"xp":40,"metric_to_track":"Aktywne oferty"},{"id":"p2s2","title":"Stwórz 14 kolejnych produktów","why":"Sklepy cyfrowe rosną razem z katalogiem. 15 powiązanych produktów pomaga Cię znaleźć i kupić więcej niż jeden.","instructions":["Twórz warianty pierwszego produktu: nowe kolory, style, grupy odbiorców lub rozmiary.","Dodaj produkty uzupełniające, których potrzebuje ten sam kupujący (np. planer posiłków obok planera budżetu).","Korzystaj z własnych szablonów, by każdy nowy produkt zajmował mniej niż godzinę.","Każdy publikuj z inną frazą w tytule."],"est_minutes":480,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":60,"metric_to_track":"Aktywne oferty"},{"id":"p2s3","title":"Stwórz pakiet","why":"Pakiety podnoszą średnią wartość zamówienia bez nowej pracy projektowej. Wielu kupujących wybiera większy zestaw.","instructions":["Połącz 3–5 powiązanych produktów w jedną ofertę.","Ustal cenę niższą niż suma pojedynczych produktów i napisz o tym na pierwszym zdjęciu.","Podlinkuj pakiet w opisie każdego pojedynczego produktu."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Sprzedaż pakietów"},{"id":"p2s4","title":"Ustaw proste śledzenie pieniędzy","why":"Opłaty się sumują. Cotygodniowe śledzenie zysku pilnuje, by ceny miały sens.","instructions":["Utwórz arkusz: data, produkt, cena, opłaty Etsy, zysk.","Aktualizuj go co tydzień przed podsumowaniem.","Sprawdź, jak rozlicza się dodatkowe dochody w Twoim kraju (w Polsce np. działalność nierejestrowana), i odkładaj część zysku."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Zysk tygodniowy"}]},{"id":"p3","title":"Pierwsze efekty","goal":"Popraw to, co zbiera wyświetlenia, i dojdź do 30 ofert.","weeks":"6-8","steps":[{"id":"p3s1","title":"Popraw najsłabsze oferty","why":"Statystyki pokazują, które oferty są oglądane, ale nie kupowane. Lepsze zdjęcia i tytuły często szybko to naprawiają.","instructions":["W statystykach Etsy posortuj oferty według wyświetleń i znajdź te bez polubień i sprzedaży.","Wymień główne zdjęcie na czytelniejsze, pokazujące korzyść.","Przepisz tytuł wokół bardziej konkretnej frazy.","Zmieniaj jedną rzecz naraz i odczekaj tydzień."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Poprawione oferty"},{"id":"p3s2","title":"Dojdź do 30 ofert","why":"Przy około 30 ofertach większość sklepów zaczyna sprzedawać co tydzień, a nie od czasu do czasu.","instructions":["Rób więcej tego, co zebrało dotąd najwięcej polubień.","Celuj w długie, konkretne frazy z mniejszą konkurencją.","Trzymaj stałe tempo: 3–5 nowych ofert tygodniowo."],"est_minutes":480,"resources":[],"tools":[],"xp":60,"metric_to_track":"Aktywne oferty"},{"id":"p3s3","title":"Poproś kupujących o opinie","why":"Opinie budują zaufanie i pomagają w pozycjonowaniu. Wielu zadowolonych kupujących po prostu o nich zapomina.","instructions":["Dodaj w plikach stronę z podziękowaniem i krótką prośbą o opinię.","Odpowiadaj na każdą wiadomość szybko i uprzejmie.","Nigdy nie oferuj rabatów ani gratisów w zamian za opinie. Etsy na to nie pozwala."],"est_minutes":30,"resources":[],"tools":[],"xp":30,"metric_to_track":"Opinie"}]},{"id":"p4","title":"Skalowanie","goal":"Postaw na bestsellery i sprowadź ruch spoza Etsy.","weeks":"9-12","steps":[{"id":"p4s1","title":"Rozbuduj bestseller w linię produktów","why":"Gdy jeden produkt się sprzedaje, ci sami kupujący chcą podobnych wersji. To najszybszy sposób na wzrost przychodu.","instructions":["Znajdź produkt z największą sprzedażą w ostatnich 30 dniach.","Stwórz 5 wersji dla nowych grup, stylów lub okazji.","Połącz całą linię w jedną ofertę premium."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Sprzedaż z linii produktów"},{"id":"p4s2","title":"Sprowadź ruch z Pinteresta","why":"Planery, pliki do druku i grafiki na ścianę to jedne z najczęściej wyszukiwanych pomysłów na Pintereście. Jeden dobry pin może przyciągać ruch miesiącami.","instructions":["Załóż darmowe konto firmowe na Pintereście i połącz je ze sklepem Etsy.","Przygotuj 2–3 pionowe piny na produkt z nagłówkiem o korzyści.","Przypinaj 3–5 razy dziennie, rozkładając piny na różne produkty."],"est_minutes":90,"resources":[{"title":"Pinterest Business (ang.)","url":"https://business.pinterest.com"}],"tools":[],"xp":50,"metric_to_track":"Odwiedziny sklepu z Pinteresta"},{"id":"p4s3","title":"Przetestuj Etsy Ads na sprawdzonych produktach","why":"Produkty cyfrowe nie mają kosztów wysyłki, więc reklamy mogą się opłacać przy ofertach, które już sprzedają.","instructions":["Reklamuj tylko oferty, które sprzedały się co najmniej dwa razy.","Zacznij od 1–3 $ dziennie.","Po 2 tygodniach zostaw reklamy tylko tam, gdzie koszt reklamy na sprzedaż jest niższy niż cena minus opłaty."],"est_minutes":45,"resources":[],"tools":[],"xp":40,"metric_to_track":"Koszt reklamy na sprzedaż"}]}],"weekly_metrics":["listings","shop_visits","sales"],"earning_milestones":[{"label":"Miesiące 1–3","range":"0–150 $ / mies.","note":"Pierwsze sprzedaże pojawiają się zwykle po 10–20 ofertach."},{"label":"Miesiące 4–6","range":"100–400 $ / mies.","note":"Pakiety i linie produktów podnoszą średnią wartość zamówienia."},{"label":"Miesiące 6–12","range":"200–1000 $ / mies.","note":"Typowe dla katalogów z 30+ produktami i ruchem z Pinteresta."}]}$roadmap$),
  ('faceless-short-video', 'en', $roadmap${"hustle_slug":"faceless-short-video","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Account & format","goal":"Pick a niche, set up your accounts and find a video format you can repeat daily.","weeks":"1-2","steps":[{"id":"p1s1","title":"Pick a niche that sells","why":"Short videos pay mostly through affiliate links and brand deals. Niches with products to recommend (tech, beauty, home, fitness, books) make that easier.","instructions":["List 5 niches where people buy products after watching videos.","Search each on TikTok and Instagram and find faceless accounts growing fast.","Choose one niche you can make 5 videos a week about."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Niche chosen"},{"id":"p1s2","title":"Save 30 videos and find the pattern","why":"Viral short videos follow patterns: a hook in the first second, one idea, a payoff. Studying them saves months of guessing.","instructions":["Save 30 top-performing faceless videos from your niche.","Write down the first sentence (hook) of each.","Group them into 3 formats you could produce without showing your face (screen recordings, hands-only, text + stock footage, voice-over).","Pick your main format."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"30 videos analyzed"},{"id":"p1s3","title":"Set up your accounts","why":"Posting the same video to TikTok and Instagram Reels doubles your reach for almost no extra work.","instructions":["Create a TikTok account and an Instagram professional (creator) account with the same name.","Write a bio that says what people get from following you.","Use one profile image across both platforms."],"est_minutes":45,"resources":[{"title":"Instagram for creators","url":"https://creators.instagram.com"}],"tools":[],"xp":30,"metric_to_track":"Accounts ready"},{"id":"p1s4","title":"Create your video template","why":"A reusable template (fonts, caption style, intro, length) lets you make a video in 20 minutes instead of 2 hours.","instructions":["Build a CapCut project with your caption style, colors and end card.","Save a list of footage sources that allow commercial use.","Make a test video and time how long it takes."],"est_minutes":60,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false},{"name":"Pexels","url":"https://www.pexels.com","affiliate":false}],"xp":30,"metric_to_track":"Minutes per video"}]},{"id":"p2","title":"Daily posting","goal":"Post one video a day for 3 weeks and learn which hooks work.","weeks":"3-5","steps":[{"id":"p2s1","title":"Batch-create your first 10 videos","why":"Batching keeps you posting even on busy days, and the algorithm rewards consistency.","instructions":["Write 10 hooks using the patterns you found.","Produce all 10 videos in one or two sessions.","Keep each video between 15 and 45 seconds, with captions on screen.","Schedule or save them as drafts."],"est_minutes":300,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false}],"xp":50,"metric_to_track":"Videos ready"},{"id":"p2s2","title":"Post daily for 3 weeks","why":"Each post is a test. Twenty tests show you far more than one ‘perfect’ video.","instructions":["Post one video per day on TikTok and the same video on Reels.","Reply to comments in the first hour after posting.","Keep making new videos while posting the batch."],"est_minutes":420,"resources":[],"tools":[],"xp":60,"metric_to_track":"Videos published"},{"id":"p2s3","title":"Find your winning hooks","why":"Retention in the first 3 seconds decides reach. Your analytics show which openings keep people watching.","instructions":["Rank your videos by views and average watch time.","Copy the hooks of your top 3 into a ‘winners’ list.","Make your next 5 videos using those hooks with new topics."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Average watch time"},{"id":"p2s4","title":"Set up a link in bio","why":"When a video takes off, you want viewers to land somewhere that can earn money right away.","instructions":["Create a simple link page listing the products you mention most.","Put it in both bios.","Update it whenever you feature a new product."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Link clicks"}]},{"id":"p3","title":"Monetize","goal":"Add affiliate links and start earning from the attention you've built.","weeks":"6-8","steps":[{"id":"p3s1","title":"Join affiliate programs","why":"Affiliate commissions are the fastest income for faceless accounts. You earn without follower minimums.","instructions":["Join Amazon Associates or brand programs that fit your niche.","Add your social profiles to your affiliate account settings where required.","Add your top 5 product links to your link page."],"est_minutes":60,"resources":[{"title":"FTC: disclosures for influencers","url":"https://www.ftc.gov/business-guidance/resources/disclosures-101-social-media-influencers"}],"tools":[{"name":"Amazon Associates","url":"https://affiliate-program.amazon.com","affiliate":false}],"xp":40,"metric_to_track":"Affiliate programs joined"},{"id":"p3s2","title":"Make 10 product-focused videos","why":"Videos that show a product solving a problem convert far better than generic tips.","instructions":["Pick 10 products your audience already asks about.","Use a winning hook, show the problem, then the product as the fix.","Mention ‘link in bio’ and label the video as containing affiliate links."],"est_minutes":300,"resources":[],"tools":[],"xp":50,"metric_to_track":"Affiliate sales"},{"id":"p3s3","title":"Track money and taxes","why":"Affiliate income arrives with delays. A simple tracker shows what's really working.","instructions":["Create a sheet with: week, clicks, sales, commission, costs.","Update it before each weekly check-in.","Check how side income is taxed where you live, and set aside part of it."],"est_minutes":30,"resources":[],"tools":[],"xp":30,"metric_to_track":"Weekly commissions"}]},{"id":"p4","title":"Scale","goal":"Land your first brand deal and turn your best formats into a series.","weeks":"9-12","steps":[{"id":"p4s1","title":"Create a one-page media kit","why":"Brands pay for access to your audience. A clear media kit makes it easy for them to say yes.","instructions":["Show followers, average views, audience countries and your best 3 videos.","Add example packages (e.g. 1 video, 3 videos) with prices.","Save it as a PDF."],"est_minutes":90,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Media kit ready"},{"id":"p4s2","title":"Pitch 15 brands","why":"Most first brand deals come from creators reaching out, not brands finding them.","instructions":["List 15 brands whose products you already feature or would recommend.","Send a short email: who you are, your audience, one idea for their product, your media kit.","Follow up once after 5 days."],"est_minutes":120,"resources":[],"tools":[],"xp":60,"metric_to_track":"Pitches sent"},{"id":"p4s3","title":"Turn your best format into a series","why":"Series (‘Part 1, 2, 3…’) bring viewers back and turn one-time viewers into followers.","instructions":["Pick your best-performing video idea.","Plan 10 episodes that follow the same structure.","Pin the first episode to your profile."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Followers"}]}],"weekly_metrics":["videos_published","followers","views"],"earning_milestones":[{"label":"Months 1–3","range":"$0–$200 / month","note":"First affiliate commissions once videos start getting views."},{"label":"Months 4–6","range":"$100–$800 / month","note":"Steady views plus the first small brand deals."},{"label":"Months 6–12","range":"$300–$2,000 / month","note":"Typical for accounts posting daily with affiliates and brand deals."}]}$roadmap$),
  ('faceless-short-video', 'pl', $roadmap${"hustle_slug":"faceless-short-video","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Konto i format","goal":"Wybierz niszę, załóż konta i znajdź format filmów, który powtórzysz codziennie.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz niszę, która sprzedaje","why":"Krótkie filmy zarabiają głównie przez linki afiliacyjne i współprace. Nisze z produktami do polecania (technologia, uroda, dom, fitness, książki) to ułatwiają.","instructions":["Wypisz 5 nisz, w których ludzie kupują produkty po obejrzeniu filmów.","Wyszukaj je na TikToku i Instagramie i znajdź szybko rosnące konta bez twarzy.","Wybierz jedną niszę, o której zrobisz 5 filmów tygodniowo."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Wybrana nisza"},{"id":"p1s2","title":"Zapisz 30 filmów i znajdź schemat","why":"Viralowe krótkie filmy mają schematy: haczyk w pierwszej sekundzie, jedna myśl, puenta. Ich analiza oszczędza miesiące zgadywania.","instructions":["Zapisz 30 najlepszych filmów bez twarzy z Twojej niszy.","Zapisz pierwsze zdanie (haczyk) każdego z nich.","Pogrupuj je w 3 formaty, które zrobisz bez pokazywania twarzy (nagranie ekranu, same dłonie, tekst + stock, lektor).","Wybierz swój główny format."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"30 przeanalizowanych filmów"},{"id":"p1s3","title":"Załóż konta","why":"Publikacja tego samego filmu na TikToku i Instagram Reels podwaja zasięg niemal bez dodatkowej pracy.","instructions":["Załóż konto na TikToku i profesjonalne konto twórcy na Instagramie z tą samą nazwą.","Napisz bio, które mówi, co ludzie zyskują, obserwując Cię.","Używaj jednego zdjęcia profilowego na obu platformach."],"est_minutes":45,"resources":[{"title":"Instagram dla twórców (ang.)","url":"https://creators.instagram.com"}],"tools":[],"xp":30,"metric_to_track":"Gotowe konta"},{"id":"p1s4","title":"Przygotuj szablon filmu","why":"Szablon wielokrotnego użytku (czcionki, styl napisów, początek, długość) pozwala zrobić film w 20 minut zamiast 2 godzin.","instructions":["Zbuduj projekt w CapCut ze swoim stylem napisów, kolorami i planszą końcową.","Zapisz listę źródeł materiałów, które pozwalają na użytek komercyjny.","Zrób film testowy i zmierz, ile czasu zajmuje."],"est_minutes":60,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false},{"name":"Pexels","url":"https://www.pexels.com","affiliate":false}],"xp":30,"metric_to_track":"Minuty na film"}]},{"id":"p2","title":"Codzienne publikacje","goal":"Publikuj jeden film dziennie przez 3 tygodnie i sprawdź, które haczyki działają.","weeks":"3-5","steps":[{"id":"p2s1","title":"Nagraj hurtowo pierwsze 10 filmów","why":"Praca hurtowa pozwala publikować nawet w zabiegane dni, a algorytm nagradza regularność.","instructions":["Napisz 10 haczyków na bazie znalezionych schematów.","Zrób wszystkie 10 filmów w jednej lub dwóch sesjach.","Każdy film niech trwa 15–45 sekund i ma napisy na ekranie.","Zaplanuj je lub zapisz jako wersje robocze."],"est_minutes":300,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false}],"xp":50,"metric_to_track":"Gotowe filmy"},{"id":"p2s2","title":"Publikuj codziennie przez 3 tygodnie","why":"Każdy post to test. Dwadzieścia testów pokaże Ci więcej niż jeden „idealny” film.","instructions":["Publikuj jeden film dziennie na TikToku i ten sam na Reels.","Odpowiadaj na komentarze w pierwszej godzinie po publikacji.","Nagrywaj nowe filmy, publikując przygotowaną porcję."],"est_minutes":420,"resources":[],"tools":[],"xp":60,"metric_to_track":"Opublikowane filmy"},{"id":"p2s3","title":"Znajdź zwycięskie haczyki","why":"Utrzymanie widza w pierwszych 3 sekundach decyduje o zasięgu. Statystyki pokazują, które otwarcia zatrzymują ludzi.","instructions":["Uszereguj filmy według wyświetleń i średniego czasu oglądania.","Przepisz haczyki 3 najlepszych na listę „zwycięzców”.","Zrób 5 kolejnych filmów z tymi haczykami, ale na nowe tematy."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Średni czas oglądania"},{"id":"p2s4","title":"Ustaw link w bio","why":"Gdy film wystrzeli, widzowie powinni trafić tam, gdzie od razu możesz zarobić.","instructions":["Utwórz prostą stronę z linkami do produktów, o których najczęściej mówisz.","Dodaj ją do obu bio.","Aktualizuj ją za każdym razem, gdy pokazujesz nowy produkt."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Kliknięcia w linki"}]},{"id":"p3","title":"Zarabianie","goal":"Dodaj linki afiliacyjne i zacznij zarabiać na zbudowanej uwadze.","weeks":"6-8","steps":[{"id":"p3s1","title":"Dołącz do programów afiliacyjnych","why":"Prowizje afiliacyjne to najszybszy dochód dla kont bez twarzy. Zarabiasz bez minimalnej liczby obserwujących.","instructions":["Dołącz do Amazon Associates lub programów marek pasujących do niszy.","Tam, gdzie jest to wymagane, dodaj swoje profile społecznościowe w ustawieniach konta afiliacyjnego.","Dodaj 5 najlepszych linków produktowych na swoją stronę z linkami."],"est_minutes":60,"resources":[{"title":"FTC: oznaczanie współprac (ang.)","url":"https://www.ftc.gov/business-guidance/resources/disclosures-101-social-media-influencers"}],"tools":[{"name":"Amazon Associates","url":"https://affiliate-program.amazon.com","affiliate":false}],"xp":40,"metric_to_track":"Programy afiliacyjne"},{"id":"p3s2","title":"Zrób 10 filmów wokół produktów","why":"Filmy pokazujące, jak produkt rozwiązuje problem, sprzedają znacznie lepiej niż ogólne porady.","instructions":["Wybierz 10 produktów, o które odbiorcy już pytają.","Użyj zwycięskiego haczyka, pokaż problem, a potem produkt jako rozwiązanie.","Wspomnij o „linku w bio” i oznacz, że film zawiera linki afiliacyjne."],"est_minutes":300,"resources":[],"tools":[],"xp":50,"metric_to_track":"Sprzedaż afiliacyjna"},{"id":"p3s3","title":"Śledź pieniądze i podatki","why":"Dochód z afiliacji wpływa z opóźnieniem. Prosty arkusz pokazuje, co naprawdę działa.","instructions":["Utwórz arkusz: tydzień, kliknięcia, sprzedaż, prowizja, koszty.","Aktualizuj go przed każdym cotygodniowym podsumowaniem.","Sprawdź, jak rozlicza się dodatkowe dochody w Twoim kraju (w Polsce np. działalność nierejestrowana), i odkładaj część."],"est_minutes":30,"resources":[],"tools":[],"xp":30,"metric_to_track":"Prowizje tygodniowe"}]},{"id":"p4","title":"Skalowanie","goal":"Zdobądź pierwszą współpracę z marką i zamień najlepsze formaty w serię.","weeks":"9-12","steps":[{"id":"p4s1","title":"Przygotuj jednostronicowy media kit","why":"Marki płacą za dostęp do Twoich odbiorców. Czytelny media kit ułatwia im zgodę.","instructions":["Pokaż liczbę obserwujących, średnie wyświetlenia, kraje odbiorców i 3 najlepsze filmy.","Dodaj przykładowe pakiety (np. 1 film, 3 filmy) z cenami.","Zapisz go jako PDF."],"est_minutes":90,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Gotowy media kit"},{"id":"p4s2","title":"Wyślij propozycje do 15 marek","why":"Większość pierwszych współprac bierze się z inicjatywy twórców, a nie marek.","instructions":["Wypisz 15 marek, których produkty już pokazujesz lub chętnie polecisz odbiorcom.","Wyślij krótki e-mail: kim jesteś, kim są Twoi odbiorcy, jeden pomysł na ich produkt, media kit.","Przypomnij się raz po 5 dniach."],"est_minutes":120,"resources":[],"tools":[],"xp":60,"metric_to_track":"Wysłane propozycje"},{"id":"p4s3","title":"Zamień najlepszy format w serię","why":"Serie („Część 1, 2, 3…”) sprowadzają widzów z powrotem i zamieniają jednorazowych widzów w obserwujących.","instructions":["Wybierz pomysł z najlepszego filmu.","Zaplanuj 10 odcinków o tej samej strukturze.","Przypnij pierwszy odcinek na profilu."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Obserwujący"}]}],"weekly_metrics":["videos_published","followers","views"],"earning_milestones":[{"label":"Miesiące 1–3","range":"0–200 $ / mies.","note":"Pierwsze prowizje afiliacyjne, gdy filmy zaczynają zbierać wyświetlenia."},{"label":"Miesiące 4–6","range":"100–800 $ / mies.","note":"Stabilne wyświetlenia i pierwsze małe współprace."},{"label":"Miesiące 6–12","range":"300–2000 $ / mies.","note":"Typowe dla kont publikujących codziennie z afiliacją i współpracami."}]}$roadmap$),
  ('faceless-youtube', 'en', $roadmap${"hustle_slug":"faceless-youtube","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Channel foundation","goal":"Choose an evergreen niche and a repeatable video format, and set up your channel.","weeks":"1-2","steps":[{"id":"p1s1","title":"Choose an evergreen niche","why":"Evergreen topics (history, personal finance, science, how-things-work) keep getting views for years, so every video keeps working for you.","instructions":["List 5 topics you could research every week without getting bored.","Search each on YouTube and find faceless channels under 100k subscribers that still get strong views.","Prefer topics advertisers pay well for (money, tech, education) over pure entertainment.","Pick one niche."],"est_minutes":60,"resources":[{"title":"YouTube Creators","url":"https://www.youtube.com/creators/"}],"tools":[],"xp":30,"metric_to_track":"Niche chosen"},{"id":"p1s2","title":"Study 10 channels and pick your format","why":"A repeatable format (e.g. ‘explained in 8 minutes’, ‘top 10’, ‘story of…’) makes production faster and tells viewers what to expect.","instructions":["Sort 10 channels in your niche by ‘Popular’ and note their most viewed titles and thumbnails.","Write down the video length, structure and style that repeat across the best videos.","Choose one format you can produce in 4–6 hours per video.","List 20 video ideas in that format."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"20 video ideas"},{"id":"p1s3","title":"Create and brand your channel","why":"A clear name, banner and description tell new viewers in two seconds what they'll get if they subscribe.","instructions":["Create a channel with a Brand Account so you can add helpers later.","Pick a short, searchable name that fits your niche.","Design a profile image and banner in Canva, and write a one-line promise in the description.","Verify your account in YouTube Studio so you can upload longer videos and custom thumbnails."],"est_minutes":60,"resources":[],"tools":[{"name":"YouTube Studio","url":"https://studio.youtube.com","affiliate":false},{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":30,"metric_to_track":"Channel set up"},{"id":"p1s4","title":"Set up your production tools","why":"Picking your voice, editor and footage sources once saves hours on every video and keeps you safe on copyright.","instructions":["Choose a voice: your own (a decent USB mic is enough) or an AI voice you have commercial rights to.","Install a video editor such as CapCut.","Use footage and music only from sources that allow commercial use, and keep a list of what you used.","Create a folder template: script, voice, footage, thumbnail."],"est_minutes":60,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false},{"name":"Pexels","url":"https://www.pexels.com","affiliate":false}],"xp":30,"metric_to_track":"Workflow ready"}]},{"id":"p2","title":"First videos","goal":"Publish your first 4 videos with strong titles and thumbnails.","weeks":"3-5","steps":[{"id":"p2s1","title":"Write your first script","why":"The first 30 seconds decide whether people keep watching. A tight script is the biggest lever you control.","instructions":["Open with a hook that promises the payoff in one sentence.","Structure the body in 3–5 clear sections, each ending with a reason to keep watching.","Research facts from reliable sources and add your own opinion or explanation. Original value is required for monetization.","Read it aloud and cut anything that sounds like filler."],"est_minutes":120,"resources":[{"title":"YouTube channel monetization policies","url":"https://support.google.com/youtube/answer/1311392"}],"tools":[],"xp":40,"metric_to_track":"Script finished"},{"id":"p2s2","title":"Produce and publish video #1","why":"Your first video won't be perfect, and that's fine. Publishing teaches you more than planning ever will.","instructions":["Record the voice-over, then edit footage to match it, changing visuals every 3–5 seconds.","Design a thumbnail with 3 words or fewer and one clear focal point.","Write a title that makes a specific promise, and a description with 2–3 keywords.","Publish, then add it to a playlist for your format."],"est_minutes":240,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false},{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Videos published"},{"id":"p2s3","title":"Publish videos #2–#4 on a fixed schedule","why":"Consistency teaches the algorithm and your viewers what to expect. One video a week is a strong, sustainable pace.","instructions":["Pick a fixed publishing day and time.","Write the next script while the current video renders.","Reuse your thumbnail layout so your channel looks consistent."],"est_minutes":480,"resources":[],"tools":[],"xp":60,"metric_to_track":"Videos published"},{"id":"p2s4","title":"Learn the 3 numbers that matter","why":"Click-through rate, average view duration and returning viewers tell you exactly what to fix.","instructions":["In YouTube Studio, open Analytics for each video.","Note impressions click-through rate (thumbnail + title) and average view duration (script + editing).","Write one improvement for your next video based on the weakest number."],"est_minutes":30,"resources":[],"tools":[{"name":"YouTube Studio","url":"https://studio.youtube.com","affiliate":false}],"xp":20,"metric_to_track":"Click-through rate"}]},{"id":"p3","title":"Consistency & growth","goal":"Keep publishing weekly, improve click-through rate and use Shorts to find new viewers.","weeks":"6-8","steps":[{"id":"p3s1","title":"Publish 3 more long videos","why":"Most channels need 10–20 videos before one takes off. Each video is another lottery ticket with better odds.","instructions":["Double down on the topic or style of your best-performing video so far.","Apply one analytics lesson in every new video.","Keep the same publishing day."],"est_minutes":600,"resources":[],"tools":[],"xp":60,"metric_to_track":"Videos published"},{"id":"p3s2","title":"Test new thumbnails and titles","why":"A better thumbnail can revive a video that's already published. It's the fastest win on YouTube.","instructions":["Find videos with a click-through rate below your channel average.","Design a new thumbnail with a bigger subject and fewer words.","Use YouTube's thumbnail test feature if available, or swap and compare after a week."],"est_minutes":60,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Click-through rate"},{"id":"p3s3","title":"Cut 5 Shorts from your long videos","why":"Shorts reach people who don't know your channel yet and can send them to your long videos.","instructions":["Pick the most surprising 30–50 seconds of each long video.","Reformat to vertical with big captions.","Link the full video from each Short."],"est_minutes":120,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false}],"xp":40,"metric_to_track":"Subscribers from Shorts"}]},{"id":"p4","title":"First income","goal":"Start earning before ad revenue unlocks and plan your next 12 videos.","weeks":"9-12","steps":[{"id":"p4s1","title":"Add affiliate links","why":"Ad revenue needs 1,000 subscribers and 4,000 watch hours. Affiliate links can pay from your first views.","instructions":["Join an affiliate program for books, tools or products your niche mentions (e.g. Amazon Associates).","Add 1–3 relevant links to the descriptions of your best videos.","Always disclose that they are affiliate links."],"est_minutes":60,"resources":[],"tools":[{"name":"Amazon Associates","url":"https://affiliate-program.amazon.com","affiliate":false}],"xp":40,"metric_to_track":"Affiliate clicks"},{"id":"p4s2","title":"Check your Partner Program progress","why":"Knowing how far you are from monetization keeps you motivated and shows whether Shorts or long videos move you faster.","instructions":["Open the Earn section in YouTube Studio and check your subscribers and watch hours.","Read the current eligibility rules and channel monetization policies.","Set a realistic target date and write it in your plan."],"est_minutes":30,"resources":[{"title":"YouTube Partner Program eligibility","url":"https://support.google.com/youtube/answer/72851"}],"tools":[],"xp":30,"metric_to_track":"Watch hours"},{"id":"p4s3","title":"Plan your next 12 videos","why":"A ready plan removes the ‘what do I make next?’ block and keeps the weekly rhythm going.","instructions":["List your 3 best videos by views and watch time.","Write 4 follow-up ideas for each.","Put all 12 in a calendar, one per week.","Check how side income is taxed where you live before money starts coming in."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Videos planned"}]}],"weekly_metrics":["videos_published","subscribers","watch_hours"],"earning_milestones":[{"label":"Months 1–3","range":"$0–$50 / month","note":"Usually only affiliate income. Focus on publishing every week."},{"label":"Months 4–8","range":"$0–$300 / month","note":"Ad revenue starts once you join the Partner Program."},{"label":"Months 9–18","range":"$100–$2,000 / month","note":"Growing channels add sponsors on top of ads and affiliates."}]}$roadmap$),
  ('faceless-youtube', 'pl', $roadmap${"hustle_slug":"faceless-youtube","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Fundamenty kanału","goal":"Wybierz ponadczasową niszę i powtarzalny format filmów oraz załóż kanał.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz ponadczasową niszę","why":"Ponadczasowe tematy (historia, finanse osobiste, nauka, jak działają rzeczy) zbierają wyświetlenia latami, więc każdy film dalej na Ciebie pracuje.","instructions":["Wypisz 5 tematów, które możesz badać co tydzień bez znudzenia.","Wyszukaj je na YouTube i znajdź kanały bez twarzy poniżej 100 tys. subskrypcji, które wciąż mają dobre wyświetlenia.","Wybieraj tematy, za które reklamodawcy dobrze płacą (pieniądze, technologia, edukacja), zamiast czystej rozrywki.","Wybierz jedną niszę."],"est_minutes":60,"resources":[{"title":"YouTube dla twórców","url":"https://www.youtube.com/creators/"}],"tools":[],"xp":30,"metric_to_track":"Wybrana nisza"},{"id":"p1s2","title":"Przeanalizuj 10 kanałów i wybierz format","why":"Powtarzalny format (np. „wyjaśnione w 8 minut”, „top 10”, „historia…”) przyspiesza produkcję i mówi widzom, czego się spodziewać.","instructions":["Posortuj 10 kanałów z niszy według „Popularne” i zanotuj najpopularniejsze tytuły oraz miniatury.","Zapisz długość, strukturę i styl, które powtarzają się w najlepszych filmach.","Wybierz jeden format, który zrobisz w 4–6 godzin na film.","Wypisz 20 pomysłów na filmy w tym formacie."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"20 pomysłów na filmy"},{"id":"p1s3","title":"Załóż i oznacz kanał","why":"Czytelna nazwa, baner i opis w dwie sekundy mówią nowym widzom, co dostaną po subskrypcji.","instructions":["Załóż kanał jako konto marki, aby móc później dodać pomocników.","Wybierz krótką, łatwą do wyszukania nazwę pasującą do niszy.","Zaprojektuj zdjęcie profilowe i baner w Canvie, a w opisie napisz jednozdaniową obietnicę.","Zweryfikuj konto w YouTube Studio, by móc wgrywać dłuższe filmy i własne miniatury."],"est_minutes":60,"resources":[],"tools":[{"name":"YouTube Studio","url":"https://studio.youtube.com","affiliate":false},{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":30,"metric_to_track":"Kanał gotowy"},{"id":"p1s4","title":"Przygotuj narzędzia produkcji","why":"Jednorazowy wybór głosu, edytora i źródeł materiałów oszczędza godziny przy każdym filmie i chroni przed problemami z prawami autorskimi.","instructions":["Wybierz głos: własny (wystarczy przyzwoity mikrofon USB) albo głos AI z prawami do użytku komercyjnego.","Zainstaluj edytor wideo, np. CapCut.","Korzystaj tylko z materiałów i muzyki, które pozwalają na użytek komercyjny, i zapisuj, czego używasz.","Utwórz szablon folderów: scenariusz, głos, materiały, miniatura."],"est_minutes":60,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false},{"name":"Pexels","url":"https://www.pexels.com","affiliate":false}],"xp":30,"metric_to_track":"Gotowy proces"}]},{"id":"p2","title":"Pierwsze filmy","goal":"Opublikuj pierwsze 4 filmy z mocnymi tytułami i miniaturami.","weeks":"3-5","steps":[{"id":"p2s1","title":"Napisz pierwszy scenariusz","why":"Pierwsze 30 sekund decyduje, czy ludzie oglądają dalej. Zwarty scenariusz to największa dźwignia, jaką masz.","instructions":["Zacznij od haczyka, który w jednym zdaniu obiecuje efekt końcowy.","Podziel treść na 3–5 jasnych części, z których każda kończy się powodem, by oglądać dalej.","Sprawdzaj fakty w wiarygodnych źródłach i dodawaj własne wyjaśnienia. Oryginalna wartość jest wymagana do monetyzacji.","Przeczytaj na głos i wytnij wszystko, co brzmi jak wypełniacz."],"est_minutes":120,"resources":[{"title":"Zasady zarabiania na kanale YouTube","url":"https://support.google.com/youtube/answer/1311392"}],"tools":[],"xp":40,"metric_to_track":"Gotowy scenariusz"},{"id":"p2s2","title":"Zrób i opublikuj film nr 1","why":"Pierwszy film nie będzie idealny i to w porządku. Publikacja nauczy Cię więcej niż planowanie.","instructions":["Nagraj lektora, a potem dopasuj do niego materiał, zmieniając obraz co 3–5 sekund.","Zaprojektuj miniaturę z maksymalnie 3 słowami i jednym wyraźnym punktem uwagi.","Napisz tytuł z konkretną obietnicą i opis z 2–3 słowami kluczowymi.","Opublikuj i dodaj film do playlisty dla swojego formatu."],"est_minutes":240,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false},{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Opublikowane filmy"},{"id":"p2s3","title":"Opublikuj filmy nr 2–4 według stałego planu","why":"Regularność uczy algorytm i widzów, czego się spodziewać. Jeden film tygodniowo to mocne i realne tempo.","instructions":["Wybierz stały dzień i godzinę publikacji.","Pisz kolejny scenariusz, gdy obecny film się renderuje.","Korzystaj z tego samego układu miniatur, by kanał wyglądał spójnie."],"est_minutes":480,"resources":[],"tools":[],"xp":60,"metric_to_track":"Opublikowane filmy"},{"id":"p2s4","title":"Poznaj 3 liczby, które mają znaczenie","why":"Współczynnik klikalności, średni czas oglądania i powracający widzowie mówią dokładnie, co poprawić.","instructions":["W YouTube Studio otwórz Statystyki każdego filmu.","Zanotuj CTR wyświetleń (miniatura + tytuł) i średni czas oglądania (scenariusz + montaż).","Zapisz jedną poprawkę do następnego filmu, bazując na najsłabszej liczbie."],"est_minutes":30,"resources":[],"tools":[{"name":"YouTube Studio","url":"https://studio.youtube.com","affiliate":false}],"xp":20,"metric_to_track":"Współczynnik klikalności"}]},{"id":"p3","title":"Regularność i wzrost","goal":"Publikuj co tydzień, popraw klikalność i wykorzystaj Shorts, by docierać do nowych widzów.","weeks":"6-8","steps":[{"id":"p3s1","title":"Opublikuj 3 kolejne długie filmy","why":"Większość kanałów potrzebuje 10–20 filmów, zanim któryś wystrzeli. Każdy film to kolejny los z lepszymi szansami.","instructions":["Postaw na temat lub styl najlepszego dotąd filmu.","W każdym nowym filmie zastosuj jedną lekcję ze statystyk.","Trzymaj się tego samego dnia publikacji."],"est_minutes":600,"resources":[],"tools":[],"xp":60,"metric_to_track":"Opublikowane filmy"},{"id":"p3s2","title":"Przetestuj nowe miniatury i tytuły","why":"Lepsza miniatura potrafi ożywić już opublikowany film. To najszybsza wygrana na YouTube.","instructions":["Znajdź filmy z CTR poniżej średniej kanału.","Zaprojektuj nową miniaturę z większym motywem i mniejszą liczbą słów.","Skorzystaj z testu miniatur w YouTube, jeśli jest dostępny, albo podmień i porównaj po tygodniu."],"est_minutes":60,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Współczynnik klikalności"},{"id":"p3s3","title":"Wytnij 5 Shorts z długich filmów","why":"Shorts docierają do osób, które jeszcze nie znają kanału, i mogą kierować je do długich filmów.","instructions":["Wybierz najbardziej zaskakujące 30–50 sekund każdego długiego filmu.","Przerób je na pion z dużymi napisami.","Podlinkuj pełny film w każdym Shorcie."],"est_minutes":120,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false}],"xp":40,"metric_to_track":"Subskrypcje z Shorts"}]},{"id":"p4","title":"Pierwsze zarobki","goal":"Zacznij zarabiać, zanim odblokujesz reklamy, i zaplanuj kolejne 12 filmów.","weeks":"9-12","steps":[{"id":"p4s1","title":"Dodaj linki afiliacyjne","why":"Przychody z reklam wymagają 1000 subskrypcji i 4000 godzin oglądania. Linki afiliacyjne mogą zarabiać od pierwszych wyświetleń.","instructions":["Dołącz do programu afiliacyjnego dla książek, narzędzi lub produktów z Twojej niszy (np. Amazon Associates).","Dodaj 1–3 trafne linki w opisach najlepszych filmów.","Zawsze zaznaczaj, że to linki afiliacyjne."],"est_minutes":60,"resources":[],"tools":[{"name":"Amazon Associates","url":"https://affiliate-program.amazon.com","affiliate":false}],"xp":40,"metric_to_track":"Kliknięcia w linki afiliacyjne"},{"id":"p4s2","title":"Sprawdź postęp w Programie partnerskim","why":"Wiedza, ile brakuje do monetyzacji, motywuje i pokazuje, czy szybciej rosną Shorts, czy długie filmy.","instructions":["Otwórz sekcję Zarabianie w YouTube Studio i sprawdź subskrypcje oraz godziny oglądania.","Przeczytaj aktualne warunki udziału i zasady zarabiania na kanale.","Ustal realną datę celu i zapisz ją w planie."],"est_minutes":30,"resources":[{"title":"Warunki Programu partnerskiego YouTube","url":"https://support.google.com/youtube/answer/72851"}],"tools":[],"xp":30,"metric_to_track":"Godziny oglądania"},{"id":"p4s3","title":"Zaplanuj kolejne 12 filmów","why":"Gotowy plan usuwa blokadę „co teraz nagrać?” i podtrzymuje cotygodniowy rytm.","instructions":["Wypisz 3 najlepsze filmy według wyświetleń i czasu oglądania.","Do każdego zapisz 4 pomysły na kontynuację.","Wpisz wszystkie 12 do kalendarza, po jednym na tydzień.","Zanim pojawią się pieniądze, sprawdź, jak rozlicza się dodatkowe dochody w Twoim kraju."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Zaplanowane filmy"}]}],"weekly_metrics":["videos_published","subscribers","watch_hours"],"earning_milestones":[{"label":"Miesiące 1–3","range":"0–50 $ / mies.","note":"Zwykle tylko dochód z afiliacji. Skup się na cotygodniowej publikacji."},{"label":"Miesiące 4–8","range":"0–300 $ / mies.","note":"Przychody z reklam zaczynają się po dołączeniu do Programu partnerskiego."},{"label":"Miesiące 9–18","range":"100–2000 $ / mies.","note":"Rosnące kanały dokładają sponsorów do reklam i afiliacji."}]}$roadmap$),
  ('mini-course', 'en', $roadmap${"hustle_slug":"mini-course","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Validate the idea","goal":"Choose a skill people will pay to learn and prove it before building anything.","weeks":"1-2","steps":[{"id":"p1s1","title":"Pick a skill and the person one step behind you","why":"You don't need to be the world's best expert. People pay to learn from someone who solved their exact problem recently.","instructions":["List 10 things friends or colleagues ask you for help with.","Mark the ones that lead to money, time saved or a clear result (e.g. ‘build a portfolio in Figma’, ‘pass a job interview’).","Pick one skill and describe the student: who they are and what result they want."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Skill and student defined"},{"id":"p1s2","title":"Talk to 5 potential students","why":"Five real conversations tell you what to teach, what to skip, and the words your students use.","instructions":["Find 5 people who match your student profile (friends of friends, online communities).","Ask: what have you tried, where did you get stuck, what would a solution be worth to you?","Write down their exact phrases. You'll use them in your sales page."],"est_minutes":120,"resources":[],"tools":[],"xp":40,"metric_to_track":"Conversations held"},{"id":"p1s3","title":"Outline your mini course","why":"A short course with one clear result sells better and gets finished more often than a long one.","instructions":["Write the promise: ‘After this course you will…’.","Split the path into 5–7 short lessons, each with one action.","Cut anything that doesn't move the student toward the promise."],"est_minutes":90,"resources":[],"tools":[],"xp":30,"metric_to_track":"Outline ready"},{"id":"p1s4","title":"Open a waitlist or pre-sale","why":"If people join a waitlist or pre-order, you know the course will sell before you spend weeks recording.","instructions":["Create a simple page with the promise, the lesson list and a sign-up form.","Offer an early-bird price for the first students.","Share it with the 5 people you interviewed and in 2 communities where your students are."],"est_minutes":90,"resources":[],"tools":[{"name":"Tally","url":"https://tally.so","affiliate":false},{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":40,"metric_to_track":"Sign-ups"}]},{"id":"p2","title":"Build & beta","goal":"Record the course, put it on Gumroad and run a small beta for feedback.","weeks":"3-5","steps":[{"id":"p2s1","title":"Record your lessons","why":"Short, clear screen recordings are enough. Students care about results, not studio quality.","instructions":["Record each lesson in 5–12 minutes with Loom or OBS.","Use a decent microphone and a quiet room. Audio matters more than video.","Don't chase perfection. Re-record only if something is unclear."],"est_minutes":480,"resources":[],"tools":[{"name":"Loom","url":"https://www.loom.com","affiliate":false},{"name":"OBS Studio","url":"https://obsproject.com","affiliate":false}],"xp":60,"metric_to_track":"Lessons recorded"},{"id":"p2s2","title":"Create a workbook","why":"A worksheet or template for each lesson turns watching into doing, which makes students succeed and recommend you.","instructions":["Write one exercise or checklist per lesson.","Design it as a simple PDF in Canva.","Add a final checklist that confirms the promise was reached."],"est_minutes":120,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":30,"metric_to_track":"Workbook ready"},{"id":"p2s3","title":"Set up the course on Gumroad","why":"Gumroad hosts your videos, handles payments and emails students, with no monthly fee.","instructions":["Create a course product and upload lessons in order.","Write the sales page using your students' own words from the interviews.","Set your price and do a test purchase with a discount code."],"est_minutes":90,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":40,"metric_to_track":"Course live"},{"id":"p2s4","title":"Run a beta with 5–10 students","why":"Beta students show you what's confusing, and their results become your best marketing.","instructions":["Offer the course at a beta price to your waitlist.","Ask each student to share where they got stuck.","Collect short testimonials with their results (with permission to use them)."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Beta students"}]},{"id":"p3","title":"Launch","goal":"Improve the course from beta feedback and run your first public launch.","weeks":"6-8","steps":[{"id":"p3s1","title":"Fix what beta students struggled with","why":"Every fix now means fewer refunds and better reviews later.","instructions":["List every point where beta students got stuck.","Re-record or add a short extra video for each.","Add testimonials to your sales page."],"est_minutes":120,"resources":[],"tools":[],"xp":40,"metric_to_track":"Fixes made"},{"id":"p3s2","title":"Run a one-week launch","why":"A launch with a clear start and end date creates urgency. Most first sales happen in the last 48 hours.","instructions":["Announce a launch week with a launch price.","Share one useful lesson snippet per day on social media and to your email list.","Send a final reminder 24 hours before the price goes up."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Sales"},{"id":"p3s3","title":"Track sales and taxes","why":"Knowing your real profit and conversion rate tells you what to improve before the next launch.","instructions":["Log visitors, sign-ups, sales, fees and profit in a sheet.","Update it before each weekly check-in.","Check how side income is taxed where you live."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Visitor to buyer rate"}]},{"id":"p4","title":"Evergreen sales","goal":"Keep the course selling every week without a launch.","weeks":"9-12","steps":[{"id":"p4s1","title":"Publish free lessons every week","why":"Teaching small pieces for free builds trust and sends people to the full course.","instructions":["Turn each lesson into 3 short posts or videos.","Post 3 times a week on one platform where your students are.","Link to a free mini-lesson that collects emails."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"New leads"},{"id":"p4s2","title":"Add an upsell","why":"Some students want more help. A higher-priced option (a 1:1 call, a review, a template pack) raises income per student.","instructions":["Ask students what extra help they'd pay for.","Create one upsell product on Gumroad.","Offer it right after purchase and at the end of the course."],"est_minutes":90,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":40,"metric_to_track":"Upsell sales"},{"id":"p4s3","title":"Recruit 3 partners","why":"Creators and newsletters with your audience can sell the course for a commission, reaching people you can't.","instructions":["Turn on affiliates for your Gumroad product and set a commission.","List 10 creators who serve your students.","Offer them free access and a commission in a short, personal message."],"est_minutes":90,"resources":[],"tools":[],"xp":40,"metric_to_track":"Sales from partners"}]}],"weekly_metrics":["leads","sales","reviews"],"earning_milestones":[{"label":"First launch","range":"$0–$500","note":"Depends mostly on your waitlist size."},{"label":"Months 4–6","range":"$100–$800 / month","note":"Evergreen sales from weekly content and partners."},{"label":"Months 6–12","range":"$200–$2,000 / month","note":"Typical with a small audience, an upsell and good testimonials."}]}$roadmap$),
  ('mini-course', 'pl', $roadmap${"hustle_slug":"mini-course","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Weryfikacja pomysłu","goal":"Wybierz umiejętność, za której naukę ludzie zapłacą, i sprawdź to, zanim cokolwiek zbudujesz.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz umiejętność i osobę, która jest krok za Tobą","why":"Nie musisz być najlepszym ekspertem na świecie. Ludzie płacą, by uczyć się od kogoś, kto niedawno rozwiązał dokładnie ich problem.","instructions":["Wypisz 10 rzeczy, w których znajomi lub współpracownicy proszą Cię o pomoc.","Zaznacz te, które prowadzą do pieniędzy, oszczędności czasu lub jasnego efektu (np. „portfolio w Figmie”, „zdana rozmowa o pracę”).","Wybierz jedną umiejętność i opisz kursanta: kim jest i jakiego efektu chce."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Określona umiejętność i kursant"},{"id":"p1s2","title":"Porozmawiaj z 5 potencjalnymi kursantami","why":"Pięć prawdziwych rozmów mówi, czego uczyć, co pominąć i jakich słów używają kursanci.","instructions":["Znajdź 5 osób pasujących do profilu kursanta (znajomi znajomych, społeczności online).","Zapytaj: co już próbowali, gdzie utknęli, ile byłoby dla nich warte rozwiązanie?","Zapisz ich dokładne sformułowania. Przydadzą się na stronie sprzedażowej."],"est_minutes":120,"resources":[],"tools":[],"xp":40,"metric_to_track":"Odbyte rozmowy"},{"id":"p1s3","title":"Rozpisz mini kurs","why":"Krótki kurs z jednym jasnym efektem sprzedaje się lepiej i częściej jest kończony niż długi.","instructions":["Zapisz obietnicę: „Po tym kursie będziesz…”.","Podziel drogę na 5–7 krótkich lekcji, każda z jednym działaniem.","Wytnij wszystko, co nie przybliża kursanta do obietnicy."],"est_minutes":90,"resources":[],"tools":[],"xp":30,"metric_to_track":"Gotowy plan kursu"},{"id":"p1s4","title":"Otwórz listę oczekujących lub przedsprzedaż","why":"Jeśli ludzie zapisują się na listę lub kupują w przedsprzedaży, wiesz, że kurs się sprzeda, zanim spędzisz tygodnie na nagrywaniu.","instructions":["Stwórz prostą stronę z obietnicą, listą lekcji i formularzem zapisu.","Zaproponuj cenę dla pierwszych kursantów.","Wyślij ją 5 rozmówcom i udostępnij w 2 społecznościach, w których są kursanci."],"est_minutes":90,"resources":[],"tools":[{"name":"Tally","url":"https://tally.so","affiliate":false},{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":40,"metric_to_track":"Zapisy"}]},{"id":"p2","title":"Budowa i wersja beta","goal":"Nagraj kurs, umieść go na Gumroad i przeprowadź małą betę dla opinii.","weeks":"3-5","steps":[{"id":"p2s1","title":"Nagraj lekcje","why":"Wystarczą krótkie, czytelne nagrania ekranu. Kursantom zależy na efektach, nie na studyjnej jakości.","instructions":["Nagrywaj każdą lekcję w 5–12 minut w Loomie lub OBS.","Użyj przyzwoitego mikrofonu i cichego pokoju. Dźwięk jest ważniejszy niż obraz.","Nie goń za perfekcją. Nagrywaj ponownie tylko to, co niejasne."],"est_minutes":480,"resources":[],"tools":[{"name":"Loom","url":"https://www.loom.com","affiliate":false},{"name":"OBS Studio","url":"https://obsproject.com","affiliate":false}],"xp":60,"metric_to_track":"Nagrane lekcje"},{"id":"p2s2","title":"Przygotuj zeszyt ćwiczeń","why":"Ćwiczenie lub szablon do każdej lekcji zamienia oglądanie w działanie, dzięki czemu kursanci osiągają efekt i Cię polecają.","instructions":["Napisz jedno ćwiczenie lub checklistę do każdej lekcji.","Zaprojektuj to jako prosty PDF w Canvie.","Dodaj końcową checklistę potwierdzającą osiągnięcie obietnicy."],"est_minutes":120,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":30,"metric_to_track":"Gotowy zeszyt ćwiczeń"},{"id":"p2s3","title":"Umieść kurs na Gumroad","why":"Gumroad hostuje filmy, obsługuje płatności i maile do kursantów, bez abonamentu.","instructions":["Utwórz produkt typu kurs i wgraj lekcje po kolei.","Napisz stronę sprzedażową, używając słów kursantów z rozmów.","Ustal cenę i zrób zakup testowy z kodem rabatowym."],"est_minutes":90,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":40,"metric_to_track":"Kurs online"},{"id":"p2s4","title":"Przeprowadź betę z 5–10 kursantami","why":"Kursanci z bety pokażą, co jest niejasne, a ich efekty staną się najlepszym marketingiem.","instructions":["Zaproponuj kurs w cenie beta osobom z listy oczekujących.","Poproś każdego kursanta o wskazanie miejsc, w których pojawiły się trudności.","Zbierz krótkie opinie z efektami (za zgodą na ich wykorzystanie)."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Kursanci bety"}]},{"id":"p3","title":"Premiera","goal":"Popraw kurs na podstawie opinii z bety i przeprowadź pierwszą publiczną premierę.","weeks":"6-8","steps":[{"id":"p3s1","title":"Popraw to, z czym mieli problem kursanci bety","why":"Każda poprawka teraz to mniej zwrotów i lepsze opinie później.","instructions":["Wypisz każde miejsce, w którym kursanci bety utknęli.","Nagraj ponownie lub dodaj krótki dodatkowy film do każdego.","Dodaj opinie na stronę sprzedażową."],"est_minutes":120,"resources":[],"tools":[],"xp":40,"metric_to_track":"Wprowadzone poprawki"},{"id":"p3s2","title":"Przeprowadź tygodniową premierę","why":"Premiera z jasnym początkiem i końcem tworzy poczucie pilności. Większość sprzedaży dzieje się w ostatnich 48 godzinach.","instructions":["Ogłoś tydzień premiery z ceną premierową.","Codziennie udostępniaj fragment przydatnej lekcji w social mediach i na liście mailowej.","Wyślij ostatnie przypomnienie 24 godziny przed podwyżką ceny."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Sprzedaż"},{"id":"p3s3","title":"Śledź sprzedaż i podatki","why":"Znajomość realnego zysku i konwersji mówi, co poprawić przed kolejną premierą.","instructions":["Zapisuj w arkuszu odwiedziny, zapisy, sprzedaż, opłaty i zysk.","Aktualizuj go przed każdym cotygodniowym podsumowaniem.","Sprawdź, jak rozlicza się dodatkowe dochody w Twoim kraju (w Polsce np. działalność nierejestrowana)."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Konwersja odwiedzających na kupujących"}]},{"id":"p4","title":"Stała sprzedaż","goal":"Spraw, by kurs sprzedawał się co tydzień bez premiery.","weeks":"9-12","steps":[{"id":"p4s1","title":"Publikuj darmowe lekcje co tydzień","why":"Uczenie małych fragmentów za darmo buduje zaufanie i kieruje ludzi do pełnego kursu.","instructions":["Zamień każdą lekcję w 3 krótkie posty lub filmy.","Publikuj 3 razy w tygodniu na jednej platformie, na której są kursanci.","Linkuj do darmowej mini lekcji, która zbiera adresy e-mail."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Nowe kontakty"},{"id":"p4s2","title":"Dodaj ofertę dodatkową","why":"Część kursantów chce więcej pomocy. Droższa opcja (rozmowa 1:1, recenzja, pakiet szablonów) zwiększa dochód na kursanta.","instructions":["Zapytaj kursantów, za jaką dodatkową pomoc by zapłacili.","Stwórz jeden produkt dodatkowy na Gumroad.","Proponuj go od razu po zakupie i na końcu kursu."],"est_minutes":90,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":40,"metric_to_track":"Sprzedaż ofert dodatkowych"},{"id":"p4s3","title":"Zdobądź 3 partnerów","why":"Twórcy i newslettery z Twoją grupą odbiorców mogą sprzedawać kurs za prowizję, docierając tam, gdzie Ty nie dotrzesz.","instructions":["Włącz program partnerski dla produktu na Gumroad i ustal prowizję.","Wypisz 10 twórców, którzy obsługują Twoich kursantów.","Zaproponuj im darmowy dostęp i prowizję w krótkiej, osobistej wiadomości."],"est_minutes":90,"resources":[],"tools":[],"xp":40,"metric_to_track":"Sprzedaż od partnerów"}]}],"weekly_metrics":["leads","sales","reviews"],"earning_milestones":[{"label":"Pierwsza premiera","range":"0–500 $","note":"Zależy głównie od wielkości listy oczekujących."},{"label":"Miesiące 4–6","range":"100–800 $ / mies.","note":"Stała sprzedaż dzięki cotygodniowym treściom i partnerom."},{"label":"Miesiące 6–12","range":"200–2000 $ / mies.","note":"Typowe przy niewielkiej publiczności, ofercie dodatkowej i dobrych opiniach."}]}$roadmap$),
  ('newsletter', 'en', $roadmap${"hustle_slug":"newsletter","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Niche & setup","goal":"Define who you write for and set up your newsletter with a clear promise.","weeks":"1-2","steps":[{"id":"p1s1","title":"Pick your niche and ideal reader","why":"Sponsors pay for specific audiences. ‘AI tools for real estate agents’ is worth more than ‘AI news’.","instructions":["Choose one industry or hobby you know and can write about every week.","Describe your ideal reader: job, goals, what they struggle with.","Write your promise in one sentence: what readers get, how often, and why it's worth their time."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"One-sentence promise written"},{"id":"p1s2","title":"Study 10 newsletters in your niche","why":"Seeing what already works (and what's missing) helps you stand out from issue #1.","instructions":["Subscribe to 10 newsletters your reader might read.","Read two issues of each and note format, length and how they make money.","Write down 3 things none of them do well. That's your angle."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Newsletters analyzed"},{"id":"p1s3","title":"Set up your newsletter","why":"beehiiv and Substack handle sign-ups, sending and payments, so you can focus on writing.","instructions":["Choose beehiiv (built for growth and ads) or Substack (simple, built-in paid subscriptions).","Create your publication with a clear name and simple logo.","Connect a custom domain if you have one.","Send yourself a test email and check it on your phone."],"est_minutes":90,"resources":[{"title":"Substack help center","url":"https://support.substack.com"}],"tools":[{"name":"beehiiv","url":"https://www.beehiiv.com","affiliate":false},{"name":"Substack","url":"https://substack.com","affiliate":false}],"xp":40,"metric_to_track":"Newsletter set up"},{"id":"p1s4","title":"Write your welcome email and sign-up page","why":"Your sign-up page converts visitors into readers. Your welcome email sets expectations and gets you into the main inbox.","instructions":["Use your one-sentence promise as the headline of your sign-up page.","Add 3 bullet points on what readers get.","Write a short welcome email that asks readers to reply with one question. Replies improve deliverability."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Sign-up page live"}]},{"id":"p2","title":"Launch","goal":"Publish your first 3 issues on schedule and reach your first 100 subscribers.","weeks":"3-5","steps":[{"id":"p2s1","title":"Publish issue #1 and share it with 20 people","why":"Your first readers come from people you personally ask. It's awkward, and it works.","instructions":["Write issue #1 using your format: an intro, 3–5 useful items, one takeaway.","Publish it on your chosen day.","Personally message 20 people who fit your reader profile with the link and why you think they'd like it."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Subscribers"},{"id":"p2s2","title":"Publish issues #2 and #3","why":"Readers and sponsors trust newsletters that show up on the same day, every week.","instructions":["Keep the same day and time as issue #1.","Collect ideas during the week in one note so writing takes under 2 hours.","End each issue with a question and reply to every answer."],"est_minutes":240,"resources":[],"tools":[],"xp":50,"metric_to_track":"Issues sent"},{"id":"p2s3","title":"Share in 3 online communities","why":"Communities where your readers already hang out are the cheapest source of your first 100 subscribers.","instructions":["Find 3 communities (Reddit, LinkedIn, Facebook groups, Discord) where your readers are active.","Read each group's rules about self-promotion.","Share one genuinely useful insight from your latest issue, with the link only where allowed."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"New subscribers from communities"},{"id":"p2s4","title":"Set your growth target","why":"Sponsors usually start paying around 1,000 engaged subscribers. A weekly target makes that concrete.","instructions":["Write down your subscriber count and open rate today.","Set a weekly target (e.g. +50 subscribers).","Log both numbers in every weekly check-in."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Subscribers"}]},{"id":"p3","title":"Growth","goal":"Grow through partners, referrals and social posts.","weeks":"6-8","steps":[{"id":"p3s1","title":"Swap recommendations with 3 newsletters","why":"Cross-promotions bring readers who already love newsletters, at no cost.","instructions":["Find newsletters of a similar size with an overlapping but not identical audience.","Send a short, friendly proposal to recommend each other.","Write a genuine 2–3 sentence recommendation for their newsletter."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Subscribers from partners"},{"id":"p3s2","title":"Launch a referral program","why":"Readers who share with friends are your best growth channel. Small rewards make it happen.","instructions":["Turn on your platform's referral feature or use a tool like SparkLoop.","Offer simple digital rewards (a guide, a template, a shout-out).","Mention the program at the end of every issue."],"est_minutes":60,"resources":[],"tools":[{"name":"SparkLoop","url":"https://sparkloop.app","affiliate":false}],"xp":40,"metric_to_track":"Referrals"},{"id":"p3s3","title":"Turn each issue into 3 social posts","why":"You've already done the research. Posting pieces of it on LinkedIn or X brings new readers for free.","instructions":["Pick the 3 most useful points from each issue.","Rewrite each as a short standalone post.","End with a soft invite to subscribe."],"est_minutes":90,"resources":[],"tools":[],"xp":40,"metric_to_track":"Subscribers from social"}]},{"id":"p4","title":"First revenue","goal":"Prepare a sponsor offer, pitch your first sponsors and pick your monetization mix.","weeks":"9-12","steps":[{"id":"p4s1","title":"Create a media kit and a payment link","why":"Sponsors want numbers and an easy way to pay. Having both ready lets you close a deal the moment someone says yes.","instructions":["Make a one-page media kit: audience, subscribers, open rate, placements, prices.","Start simple, e.g. one sponsor slot per issue.","Create a Stripe Payment Link for one slot."],"est_minutes":60,"resources":[{"title":"Stripe Payment Links","url":"https://docs.stripe.com/payment-links"}],"tools":[{"name":"Stripe","url":"https://stripe.com","affiliate":false},{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Media kit ready"},{"id":"p4s2","title":"Pitch 10 potential sponsors","why":"Small, niche sponsors often say yes to newsletters with a few hundred engaged readers.","instructions":["List 10 businesses or tools your readers would genuinely care about.","Send a short, personal pitch with your media kit and payment link.","Offer a discounted first slot so they can test you.","Follow up once after 5 days."],"est_minutes":120,"resources":[],"tools":[],"xp":60,"metric_to_track":"Pitches sent"},{"id":"p4s3","title":"Pick your money mix","why":"Sponsors, an ad network, paid subscriptions and affiliate links each fit different audiences. Picking two keeps you focused.","instructions":["Check whether your platform's ad network or paid subscriptions are available on your plan.","Choose two income streams to focus on for the next 3 months.","Check how side income is taxed where you live, and set aside part of every payment."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Revenue per 1,000 subscribers"}]}],"weekly_metrics":["subscribers","issues_published","pitches_sent"],"earning_milestones":[{"label":"Months 1–3","range":"$0 / month","note":"Usually nothing until about 1,000 subscribers. Growth is the goal."},{"label":"Months 4–8","range":"$50–$500 / month","note":"First small sponsors and affiliate income."},{"label":"Months 9–18","range":"$100–$1,500 / month","note":"Regular sponsors, ad network or paid tier on top."}]}$roadmap$),
  ('newsletter', 'pl', $roadmap${"hustle_slug":"newsletter","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Nisza i konfiguracja","goal":"Określ, dla kogo piszesz, i skonfiguruj newsletter z jasną obietnicą.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz niszę i idealnego czytelnika","why":"Sponsorzy płacą za konkretne grupy odbiorców. „Narzędzia AI dla agentów nieruchomości” są warte więcej niż „nowości o AI”.","instructions":["Wybierz jedną branżę lub hobby, które znasz i o których możesz pisać co tydzień.","Opisz idealnego czytelnika: zawód, cele, z czym ma problem.","Zapisz obietnicę w jednym zdaniu: co czytelnik dostaje, jak często i dlaczego warto."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Obietnica w jednym zdaniu"},{"id":"p1s2","title":"Przeanalizuj 10 newsletterów w niszy","why":"Obserwacja tego, co już działa (i czego brakuje), pozwala wyróżnić się od pierwszego wydania.","instructions":["Zasubskrybuj 10 newsletterów, które może czytać Twój odbiorca.","Przeczytaj po dwa wydania i zanotuj format, długość i sposób zarabiania.","Zapisz 3 rzeczy, których żaden z nich nie robi dobrze. To Twój wyróżnik."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Przeanalizowane newslettery"},{"id":"p1s3","title":"Załóż newsletter","why":"beehiiv i Substack obsługują zapisy, wysyłkę i płatności, więc możesz skupić się na pisaniu.","instructions":["Wybierz beehiiv (nastawiony na wzrost i reklamy) lub Substack (prosty, z płatnymi subskrypcjami).","Utwórz publikację z czytelną nazwą i prostym logo.","Podłącz własną domenę, jeśli ją masz.","Wyślij sobie e-mail testowy i sprawdź go na telefonie."],"est_minutes":90,"resources":[{"title":"Centrum pomocy Substack (ang.)","url":"https://support.substack.com"}],"tools":[{"name":"beehiiv","url":"https://www.beehiiv.com","affiliate":false},{"name":"Substack","url":"https://substack.com","affiliate":false}],"xp":40,"metric_to_track":"Newsletter gotowy"},{"id":"p1s4","title":"Napisz e-mail powitalny i stronę zapisu","why":"Strona zapisu zamienia odwiedzających w czytelników. E-mail powitalny ustawia oczekiwania i pomaga trafić do głównej skrzynki.","instructions":["Użyj obietnicy z jednego zdania jako nagłówka strony zapisu.","Dodaj 3 punkty o tym, co dostaje czytelnik.","Napisz krótki e-mail powitalny z prośbą o odpowiedź na jedno pytanie. Odpowiedzi poprawiają dostarczalność."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Strona zapisu online"}]},{"id":"p2","title":"Start","goal":"Opublikuj pierwsze 3 wydania zgodnie z planem i zdobądź pierwszych 100 subskrybentów.","weeks":"3-5","steps":[{"id":"p2s1","title":"Opublikuj wydanie nr 1 i wyślij je 20 osobom","why":"Pierwsi czytelnicy to osoby, które osobiście poprosisz. Bywa niezręcznie, ale to działa.","instructions":["Napisz wydanie nr 1 w swoim formacie: wstęp, 3–5 przydatnych punktów, jeden wniosek.","Opublikuj je w wybranym dniu.","Wyślij osobistą wiadomość do 20 osób pasujących do profilu z linkiem i powodem, dla którego może im się spodobać."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Subskrybenci"},{"id":"p2s2","title":"Opublikuj wydania nr 2 i 3","why":"Czytelnicy i sponsorzy ufają newsletterom, które pojawiają się w ten sam dzień co tydzień.","instructions":["Zachowaj ten sam dzień i godzinę co przy wydaniu nr 1.","Zbieraj pomysły w ciągu tygodnia w jednej notatce, by pisanie zajmowało mniej niż 2 godziny.","Kończ każde wydanie pytaniem i odpowiadaj na każdą odpowiedź."],"est_minutes":240,"resources":[],"tools":[],"xp":50,"metric_to_track":"Wysłane wydania"},{"id":"p2s3","title":"Udostępnij w 3 społecznościach online","why":"Społeczności, w których już są Twoi czytelnicy, to najtańsze źródło pierwszych 100 subskrybentów.","instructions":["Znajdź 3 społeczności (Reddit, LinkedIn, grupy na Facebooku, Discord), w których są Twoi czytelnicy.","Przeczytaj zasady autopromocji w każdej grupie.","Podziel się jedną naprawdę przydatną myślą z ostatniego wydania, z linkiem tylko tam, gdzie wolno."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Nowi subskrybenci ze społeczności"},{"id":"p2s4","title":"Ustal cel wzrostu","why":"Sponsorzy zaczynają zwykle płacić przy około 1000 zaangażowanych subskrybentach. Cel tygodniowy czyni to konkretnym.","instructions":["Zapisz dzisiejszą liczbę subskrybentów i współczynnik otwarć.","Ustal cel tygodniowy (np. +50 subskrybentów).","Wpisuj obie liczby w każdym cotygodniowym podsumowaniu."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Subskrybenci"}]},{"id":"p3","title":"Wzrost","goal":"Rośnij dzięki partnerom, poleceniom i postom w social mediach.","weeks":"6-8","steps":[{"id":"p3s1","title":"Wymień się poleceniami z 3 newsletterami","why":"Wzajemne polecenia przyciągają czytelników, którzy już lubią newslettery, bez żadnych kosztów.","instructions":["Znajdź newslettery podobnej wielkości z pokrewną, ale nie identyczną grupą odbiorców.","Wyślij krótką, przyjazną propozycję wzajemnego polecenia.","Napisz szczere, 2–3-zdaniowe polecenie ich newslettera."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Subskrybenci od partnerów"},{"id":"p3s2","title":"Uruchom program poleceń","why":"Czytelnicy dzielący się ze znajomymi to najlepszy kanał wzrostu. Małe nagrody to napędzają.","instructions":["Włącz funkcję poleceń na swojej platformie albo użyj narzędzia typu SparkLoop.","Zaproponuj proste cyfrowe nagrody (poradnik, szablon, wzmiankę).","Wspominaj o programie na końcu każdego wydania."],"est_minutes":60,"resources":[],"tools":[{"name":"SparkLoop","url":"https://sparkloop.app","affiliate":false}],"xp":40,"metric_to_track":"Polecenia"},{"id":"p3s3","title":"Zamień każde wydanie w 3 posty","why":"Research jest już zrobiony. Publikacja jego fragmentów na LinkedIn czy X przyciąga nowych czytelników za darmo.","instructions":["Wybierz 3 najbardziej przydatne punkty z każdego wydania.","Przepisz każdy jako krótki, samodzielny post.","Zakończ delikatnym zaproszeniem do subskrypcji."],"est_minutes":90,"resources":[],"tools":[],"xp":40,"metric_to_track":"Subskrybenci z social mediów"}]},{"id":"p4","title":"Pierwsze przychody","goal":"Przygotuj ofertę dla sponsorów, zaproponuj współpracę pierwszym z nich i wybierz sposoby zarabiania.","weeks":"9-12","steps":[{"id":"p4s1","title":"Przygotuj media kit i link do płatności","why":"Sponsorzy chcą liczb i łatwego sposobu płatności. Gdy masz oba, zamkniesz współpracę w chwili, gdy ktoś powie „tak”.","instructions":["Przygotuj jednostronicowy media kit: odbiorcy, subskrybenci, współczynnik otwarć, miejsca reklamowe, ceny.","Zacznij prosto, np. jedno miejsce sponsorskie na wydanie.","Utwórz Payment Link w Stripe na jedno miejsce."],"est_minutes":60,"resources":[{"title":"Stripe Payment Links (ang.)","url":"https://docs.stripe.com/payment-links"}],"tools":[{"name":"Stripe","url":"https://stripe.com","affiliate":false},{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Gotowy media kit"},{"id":"p4s2","title":"Zaproponuj sponsoring 10 firmom","why":"Mali, niszowi sponsorzy często zgadzają się na newslettery z kilkuset zaangażowanymi czytelnikami.","instructions":["Wypisz 10 firm lub narzędzi, które naprawdę zainteresują czytelników.","Wyślij krótką, osobistą propozycję z media kitem i linkiem do płatności.","Zaproponuj zniżkę na pierwsze miejsce, by mogli Cię przetestować.","Przypomnij się raz po 5 dniach."],"est_minutes":120,"resources":[],"tools":[],"xp":60,"metric_to_track":"Wysłane propozycje"},{"id":"p4s3","title":"Wybierz sposoby zarabiania","why":"Sponsorzy, sieć reklamowa, płatne subskrypcje i linki afiliacyjne pasują do różnych grup. Wybór dwóch pozwala się skupić.","instructions":["Sprawdź, czy sieć reklamowa lub płatne subskrypcje są dostępne w Twoim planie.","Wybierz dwa źródła dochodu na najbliższe 3 miesiące.","Sprawdź, jak rozlicza się dodatkowe dochody w Twoim kraju (w Polsce np. działalność nierejestrowana), i odkładaj część każdej wpłaty."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Przychód na 1000 subskrybentów"}]}],"weekly_metrics":["subscribers","issues_published","pitches_sent"],"earning_milestones":[{"label":"Miesiące 1–3","range":"0 $ / mies.","note":"Zwykle nic do około 1000 subskrybentów. Celem jest wzrost."},{"label":"Miesiące 4–8","range":"50–500 $ / mies.","note":"Pierwsi mali sponsorzy i dochód z afiliacji."},{"label":"Miesiące 9–18","range":"100–1500 $ / mies.","note":"Stali sponsorzy, sieć reklamowa lub płatna subskrypcja."}]}$roadmap$),
  ('niche-affiliate-blog', 'en', $roadmap${"hustle_slug":"niche-affiliate-blog","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Niche & site setup","goal":"Choose a niche you can win in, launch your site and plan your first 30 articles.","weeks":"1-2","steps":[{"id":"p1s1","title":"Pick a niche you can write 100 articles about","why":"Blogs win through depth. A narrow niche with products to recommend (e.g. ‘home espresso for beginners’) beats a general lifestyle blog.","instructions":["List 5 topics you know, like, and where people buy things online.","Google 10 questions per topic and check if small blogs or forums rank on page one. That means competition is beatable.","Pick the topic where you have real experience or can test products yourself."],"est_minutes":60,"resources":[{"title":"Google Trends","url":"https://trends.google.com"}],"tools":[],"xp":30,"metric_to_track":"Niche chosen"},{"id":"p1s2","title":"Launch your WordPress site","why":"Your own site gives you full control over content and affiliate links, and builds an asset that can grow in value.","instructions":["Buy a short, brandable domain related to your niche.","Get basic hosting with one-click WordPress install.","Install a lightweight, fast theme and set up your logo and menu.","Check that the site loads quickly on your phone."],"est_minutes":120,"resources":[],"tools":[{"name":"WordPress","url":"https://wordpress.org","affiliate":false},{"name":"Hostinger","url":"https://www.hostinger.com","affiliate":false}],"xp":40,"metric_to_track":"Site live"},{"id":"p1s3","title":"Build a list of 30 article topics","why":"Specific questions (‘how to descale a Breville espresso machine’) have less competition and attract readers ready to act.","instructions":["Collect questions from Google's ‘People also ask’, forums and AnswerThePublic.","Mix 20 helpful ‘how to’ articles with 10 product-focused ones (‘best X for Y’, ‘X vs Y’).","Put them in a sheet with a status column."],"est_minutes":90,"resources":[],"tools":[{"name":"AnswerThePublic","url":"https://answerthepublic.com","affiliate":false}],"xp":40,"metric_to_track":"Topics planned"},{"id":"p1s4","title":"Add essential pages and Search Console","why":"About, contact, privacy and affiliate disclosure pages build trust and are required by most affiliate programs. Search Console shows how Google sees you.","instructions":["Write an About page explaining your real experience with the topic.","Add contact, privacy policy and affiliate disclosure pages.","Verify your site in Google Search Console and submit your sitemap."],"est_minutes":60,"resources":[{"title":"Google Search Console","url":"https://search.google.com/search-console"}],"tools":[],"xp":30,"metric_to_track":"Site verified"}]},{"id":"p2","title":"First articles","goal":"Publish your first 8 genuinely helpful articles and join affiliate programs.","weeks":"3-5","steps":[{"id":"p2s1","title":"Write your first 3 articles","why":"Google rewards content written from real experience that fully answers the question. Quality here sets the bar for your whole site.","instructions":["Answer the question in the first paragraph, then go deeper.","Add your own photos, examples or test results wherever possible.","Use clear headings, short paragraphs and a summary.","Read Google's guide to helpful content and check your article against it."],"est_minutes":480,"resources":[{"title":"Google: creating helpful content","url":"https://developers.google.com/search/docs/fundamentals/creating-helpful-content"},{"title":"Google SEO starter guide","url":"https://developers.google.com/search/docs/fundamentals/seo-starter-guide"}],"tools":[],"xp":60,"metric_to_track":"Articles published"},{"id":"p2s2","title":"Join affiliate programs","why":"Programs usually approve sites that already have some content. Now you have enough to apply.","instructions":["Apply to Amazon Associates (you need 3 qualifying sales within 180 days to stay approved).","Apply to an affiliate network like Awin for brands in your niche.","Add a short disclosure at the top of every article with affiliate links."],"est_minutes":45,"resources":[],"tools":[{"name":"Amazon Associates","url":"https://affiliate-program.amazon.com","affiliate":false},{"name":"Awin","url":"https://www.awin.com","affiliate":false}],"xp":30,"metric_to_track":"Programs approved"},{"id":"p2s3","title":"Publish 5 more articles","why":"Topical depth tells Google you're an authority. Around 20–30 connected articles is when many sites start ranking.","instructions":["Aim for two articles a week from your topic list.","Link each new article to 2–3 related ones on your site.","Add affiliate links only where a product genuinely solves the reader's problem."],"est_minutes":600,"resources":[],"tools":[],"xp":60,"metric_to_track":"Articles published"},{"id":"p2s4","title":"Track costs and income","why":"Blogs have running costs (domain, hosting). Tracking them keeps the project honest.","instructions":["Create a sheet with: month, costs, affiliate income, profit.","Update it before each weekly check-in.","Check how side income is taxed where you live."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Monthly costs"}]},{"id":"p3","title":"Build authority","goal":"Publish your first buying guide and improve articles based on Search Console data.","weeks":"6-8","steps":[{"id":"p3s1","title":"Write an honest buying guide","why":"‘Best X for Y’ articles earn most affiliate income. Readers and Google trust guides that show real comparison and experience.","instructions":["Pick a product category your readers ask about.","Compare 3–7 options with clear criteria, pros and cons, and who each is best for.","Include your own photos or experience where possible, and be honest about downsides."],"est_minutes":240,"resources":[],"tools":[],"xp":50,"metric_to_track":"Affiliate clicks"},{"id":"p3s2","title":"Strengthen internal links","why":"Internal links help Google understand your site and pass authority to the pages that earn money.","instructions":["Link every ‘how to’ article to your most relevant buying guide.","Create a category page that links to all articles on one sub-topic.","Fix any broken links."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Internal links added"},{"id":"p3s3","title":"Improve pages Google already shows","why":"Articles with impressions but few clicks are close to winning. Small title fixes can multiply traffic.","instructions":["In Search Console, open Performance and sort pages by impressions.","For pages with low click-through rate, rewrite titles to match the exact search query.","Add a section answering related queries you see in the report."],"est_minutes":60,"resources":[],"tools":[{"name":"Google Search Console","url":"https://search.google.com/search-console","affiliate":false}],"xp":40,"metric_to_track":"Google clicks"}]},{"id":"p4","title":"Keep compounding","goal":"Reach 25+ articles and add a second traffic source while Google builds trust.","weeks":"9-12","steps":[{"id":"p4s1","title":"Publish 8 more articles","why":"New blogs often take 6–12 months to rank. Every article you add now pays off later.","instructions":["Keep your two-articles-a-week rhythm.","Prioritize topics related to your best-performing pages.","Update older articles with anything new you've learned."],"est_minutes":600,"resources":[],"tools":[],"xp":60,"metric_to_track":"Articles published"},{"id":"p4s2","title":"Add Pinterest as a second traffic source","why":"Pinterest can send readers to a new blog long before Google does.","instructions":["Create a Pinterest business account for your blog.","Make 2–3 vertical pins for each article.","Pin a few times a week and track clicks in Pinterest Analytics."],"est_minutes":120,"resources":[{"title":"Pinterest Business","url":"https://business.pinterest.com"}],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Visitors from Pinterest"},{"id":"p4s3","title":"Plan your next 3 months of content","why":"A clear plan keeps you publishing through the quiet months before search traffic arrives.","instructions":["Review which topics get impressions in Search Console.","Plan 24 new articles around those topics.","Schedule them in a calendar, two per week."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Articles planned"}]}],"weekly_metrics":["articles_published","search_clicks","sales"],"earning_milestones":[{"label":"Months 1–6","range":"$0–$50 / month","note":"Google needs time to trust a new site. Keep publishing."},{"label":"Months 6–12","range":"$50–$500 / month","note":"First pages rank and buying guides start converting."},{"label":"Months 12–18","range":"$200–$2,000 / month","note":"Typical for well-run blogs with 60+ helpful articles."}]}$roadmap$),
  ('niche-affiliate-blog', 'pl', $roadmap${"hustle_slug":"niche-affiliate-blog","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Nisza i strona","goal":"Wybierz niszę, w której możesz wygrać, uruchom stronę i zaplanuj pierwsze 30 artykułów.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz niszę na 100 artykułów","why":"Blogi wygrywają głębią. Wąska nisza z produktami do polecania (np. „domowe espresso dla początkujących”) wygrywa z ogólnym blogiem lifestyle'owym.","instructions":["Wypisz 5 tematów, które znasz, lubisz i w których ludzie kupują online.","Wyszukaj w Google po 10 pytań do każdego tematu i sprawdź, czy na pierwszej stronie są małe blogi lub fora. To znak, że konkurencję da się pokonać.","Wybierz temat, w którym masz prawdziwe doświadczenie lub możesz samodzielnie testować produkty."],"est_minutes":60,"resources":[{"title":"Google Trends","url":"https://trends.google.com"}],"tools":[],"xp":30,"metric_to_track":"Wybrana nisza"},{"id":"p1s2","title":"Uruchom stronę na WordPressie","why":"Własna strona daje pełną kontrolę nad treścią i linkami afiliacyjnymi oraz buduje aktywo, którego wartość rośnie.","instructions":["Kup krótką, łatwą do zapamiętania domenę związaną z niszą.","Wykup podstawowy hosting z instalacją WordPressa jednym kliknięciem.","Zainstaluj lekki, szybki motyw i ustaw logo oraz menu.","Sprawdź, czy strona szybko ładuje się na telefonie."],"est_minutes":120,"resources":[],"tools":[{"name":"WordPress","url":"https://wordpress.org","affiliate":false},{"name":"Hostinger","url":"https://www.hostinger.com","affiliate":false}],"xp":40,"metric_to_track":"Strona online"},{"id":"p1s3","title":"Zbuduj listę 30 tematów artykułów","why":"Konkretne pytania („jak odkamienić ekspres Breville”) mają mniejszą konkurencję i przyciągają czytelników gotowych do działania.","instructions":["Zbieraj pytania z sekcji „Podobne pytania” w Google, z forów i z AnswerThePublic.","Połącz 20 pomocnych artykułów „jak to zrobić” z 10 produktowymi („najlepszy X do Y”, „X czy Y”).","Wpisz je do arkusza z kolumną statusu."],"est_minutes":90,"resources":[],"tools":[{"name":"AnswerThePublic","url":"https://answerthepublic.com","affiliate":false}],"xp":40,"metric_to_track":"Zaplanowane tematy"},{"id":"p1s4","title":"Dodaj podstawowe strony i Search Console","why":"Strony „O mnie”, kontakt, polityka prywatności i informacja o afiliacji budują zaufanie i są wymagane przez większość programów. Search Console pokazuje, jak widzi Cię Google.","instructions":["Napisz stronę „O mnie” z Twoim prawdziwym doświadczeniem w temacie.","Dodaj strony: kontakt, polityka prywatności i informacja o linkach afiliacyjnych.","Zweryfikuj stronę w Google Search Console i prześlij mapę witryny."],"est_minutes":60,"resources":[{"title":"Google Search Console","url":"https://search.google.com/search-console"}],"tools":[],"xp":30,"metric_to_track":"Strona zweryfikowana"}]},{"id":"p2","title":"Pierwsze artykuły","goal":"Opublikuj pierwsze 8 naprawdę pomocnych artykułów i dołącz do programów afiliacyjnych.","weeks":"3-5","steps":[{"id":"p2s1","title":"Napisz pierwsze 3 artykuły","why":"Google nagradza treści pisane z prawdziwego doświadczenia, które w pełni odpowiadają na pytanie. Tu ustawiasz poziom całej strony.","instructions":["Odpowiedz na pytanie w pierwszym akapicie, a potem wejdź głębiej.","Dodawaj własne zdjęcia, przykłady lub wyniki testów, gdzie się da.","Używaj czytelnych nagłówków, krótkich akapitów i podsumowania.","Przeczytaj poradnik Google o pomocnych treściach i porównaj z nim artykuł."],"est_minutes":480,"resources":[{"title":"Google: tworzenie pomocnych treści","url":"https://developers.google.com/search/docs/fundamentals/creating-helpful-content"},{"title":"Podstawy SEO od Google","url":"https://developers.google.com/search/docs/fundamentals/seo-starter-guide"}],"tools":[],"xp":60,"metric_to_track":"Opublikowane artykuły"},{"id":"p2s2","title":"Dołącz do programów afiliacyjnych","why":"Programy zwykle akceptują strony, które mają już trochę treści. Teraz masz wystarczająco, by się zgłosić.","instructions":["Zgłoś się do Amazon Associates (by zostać w programie, potrzebujesz 3 kwalifikujących się sprzedaży w 180 dni).","Zgłoś się do sieci afiliacyjnej, np. Awin, dla marek z niszy.","Dodaj krótką informację o afiliacji na początku każdego artykułu z linkami."],"est_minutes":45,"resources":[],"tools":[{"name":"Amazon Associates","url":"https://affiliate-program.amazon.com","affiliate":false},{"name":"Awin","url":"https://www.awin.com","affiliate":false}],"xp":30,"metric_to_track":"Zatwierdzone programy"},{"id":"p2s3","title":"Opublikuj 5 kolejnych artykułów","why":"Głębia tematyczna pokazuje Google, że jesteś ekspertem. Przy 20–30 powiązanych artykułach wiele stron zaczyna się pozycjonować.","instructions":["Celuj w dwa artykuły tygodniowo z listy tematów.","Linkuj każdy nowy artykuł do 2–3 powiązanych na stronie.","Dodawaj linki afiliacyjne tylko tam, gdzie produkt naprawdę rozwiązuje problem czytelnika."],"est_minutes":600,"resources":[],"tools":[],"xp":60,"metric_to_track":"Opublikowane artykuły"},{"id":"p2s4","title":"Śledź koszty i przychody","why":"Blog ma stałe koszty (domena, hosting). Ich śledzenie pozwala uczciwie ocenić projekt.","instructions":["Utwórz arkusz: miesiąc, koszty, dochód z afiliacji, zysk.","Aktualizuj go przed każdym cotygodniowym podsumowaniem.","Sprawdź, jak rozlicza się dodatkowe dochody w Twoim kraju (w Polsce np. działalność nierejestrowana)."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Koszty miesięczne"}]},{"id":"p3","title":"Budowa autorytetu","goal":"Opublikuj pierwszy poradnik zakupowy i popraw artykuły na podstawie danych z Search Console.","weeks":"6-8","steps":[{"id":"p3s1","title":"Napisz uczciwy poradnik zakupowy","why":"Artykuły „najlepszy X do Y” przynoszą najwięcej z afiliacji. Czytelnicy i Google ufają poradnikom z prawdziwym porównaniem i doświadczeniem.","instructions":["Wybierz kategorię produktów, o którą pytają czytelnicy.","Porównaj 3–7 opcji według jasnych kryteriów, z plusami, minusami i informacją, dla kogo każda jest najlepsza.","Dodaj własne zdjęcia lub doświadczenia, gdzie się da, i uczciwie pisz o wadach."],"est_minutes":240,"resources":[],"tools":[],"xp":50,"metric_to_track":"Kliknięcia afiliacyjne"},{"id":"p3s2","title":"Wzmocnij linkowanie wewnętrzne","why":"Linki wewnętrzne pomagają Google zrozumieć stronę i przekazują autorytet stronom, które zarabiają.","instructions":["Linkuj każdy artykuł „jak to zrobić” do najbardziej pasującego poradnika zakupowego.","Utwórz stronę kategorii linkującą do wszystkich artykułów z jednego podtematu.","Napraw niedziałające linki."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Dodane linki wewnętrzne"},{"id":"p3s3","title":"Popraw strony, które Google już pokazuje","why":"Artykuły z wyświetleniami, ale z małą liczbą kliknięć, są blisko sukcesu. Drobne poprawki tytułu potrafią zwielokrotnić ruch.","instructions":["W Search Console otwórz Skuteczność i posortuj strony według wyświetleń.","Przy stronach z niskim CTR przepisz tytuły, by pasowały do dokładnych zapytań.","Dodaj sekcję odpowiadającą na pokrewne zapytania widoczne w raporcie."],"est_minutes":60,"resources":[],"tools":[{"name":"Google Search Console","url":"https://search.google.com/search-console","affiliate":false}],"xp":40,"metric_to_track":"Kliknięcia z Google"}]},{"id":"p4","title":"Efekt kuli śnieżnej","goal":"Dojdź do 25+ artykułów i dodaj drugie źródło ruchu, zanim Google nabierze zaufania.","weeks":"9-12","steps":[{"id":"p4s1","title":"Opublikuj 8 kolejnych artykułów","why":"Nowe blogi często potrzebują 6–12 miesięcy, by się wypozycjonować. Każdy dodany teraz artykuł zwróci się później.","instructions":["Utrzymuj rytm dwóch artykułów tygodniowo.","Stawiaj na tematy powiązane z najlepszymi stronami.","Aktualizuj starsze artykuły o nowe informacje."],"est_minutes":600,"resources":[],"tools":[],"xp":60,"metric_to_track":"Opublikowane artykuły"},{"id":"p4s2","title":"Dodaj Pinterest jako drugie źródło ruchu","why":"Pinterest może kierować czytelników na nowy blog na długo przed Google.","instructions":["Załóż konto firmowe na Pintereście dla bloga.","Przygotuj 2–3 pionowe piny do każdego artykułu.","Przypinaj kilka razy w tygodniu i śledź kliknięcia w statystykach Pinteresta."],"est_minutes":120,"resources":[{"title":"Pinterest Business (ang.)","url":"https://business.pinterest.com"}],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Odwiedzający z Pinteresta"},{"id":"p4s3","title":"Zaplanuj treści na 3 miesiące","why":"Jasny plan pomaga publikować w cichych miesiącach, zanim pojawi się ruch z wyszukiwarki.","instructions":["Sprawdź w Search Console, które tematy zbierają wyświetlenia.","Zaplanuj 24 nowe artykuły wokół tych tematów.","Rozpisz je w kalendarzu, po dwa tygodniowo."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Zaplanowane artykuły"}]}],"weekly_metrics":["articles_published","search_clicks","sales"],"earning_milestones":[{"label":"Miesiące 1–6","range":"0–50 $ / mies.","note":"Google potrzebuje czasu, by zaufać nowej stronie. Publikuj dalej."},{"label":"Miesiące 6–12","range":"50–500 $ / mies.","note":"Pierwsze strony się pozycjonują, a poradniki zakupowe zaczynają sprzedawać."},{"label":"Miesiące 12–18","range":"200–2000 $ / mies.","note":"Typowe dla dobrze prowadzonych blogów z 60+ pomocnymi artykułami."}]}$roadmap$),
  ('notion-canva-templates', 'en', $roadmap${"hustle_slug":"notion-canva-templates","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"First template","goal":"Choose an audience with a clear problem and build one template that solves it.","weeks":"1-2","steps":[{"id":"p1s1","title":"Pick an audience and one problem","why":"‘Productivity template’ is too broad to sell. ‘Client tracker for freelance designers’ tells buyers instantly it's for them.","instructions":["List 5 groups you understand (students, freelancers, small shops, content creators, job seekers).","For each, write the most annoying thing they organize by hand.","Browse the Notion template gallery and Gumroad to see what already sells for them.","Pick one audience and one problem."],"est_minutes":45,"resources":[{"title":"Notion template gallery","url":"https://www.notion.com/templates"}],"tools":[],"xp":30,"metric_to_track":"Audience and problem chosen"},{"id":"p1s2","title":"Build your first template","why":"A template people love is simple, clearly labeled and ready to use in 5 minutes. That's what earns reviews and repeat buyers.","instructions":["Build it in Notion (databases, views, buttons) or Canva (editable designs), depending on your audience.","Add a ‘Start here’ page with 3–5 short setup instructions.","Fill it with realistic sample data so buyers see how it works.","Ask one person from your audience to try it and note where they get stuck."],"est_minutes":240,"resources":[{"title":"Canva content license","url":"https://www.canva.com/policies/content-license-agreement/"}],"tools":[{"name":"Notion","url":"https://www.notion.com","affiliate":false},{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Template finished and tested"},{"id":"p1s3","title":"Set up your Gumroad store","why":"Gumroad lets you sell digital products with no monthly fee and delivers files automatically after payment.","instructions":["Create a Gumroad account and connect a payout method.","Add a profile photo, short bio and a link to your social account.","Check which fees apply per sale so you can price correctly."],"est_minutes":60,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":30,"metric_to_track":"Store ready"},{"id":"p1s4","title":"Create preview images and a demo","why":"Buyers decide in seconds. Clean previews and a 30-second demo show the value better than any description.","instructions":["Take screenshots of the key views and place them on clean branded backgrounds in Canva.","Record a short screen video walking through the template.","Make a cover image with the result the buyer gets, e.g. ‘Never lose track of a client again’."],"est_minutes":60,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":30,"metric_to_track":"Preview images ready"}]},{"id":"p2","title":"Launch","goal":"Publish your template, give away a free version and start posting about it.","weeks":"3-5","steps":[{"id":"p2s1","title":"Publish your template for sale","why":"A live product page lets you test price and message with real people.","instructions":["Create a Gumroad product with your cover, previews and demo video.","Write the description as: problem, what's inside, who it's for, how to start.","Deliver a Notion ‘duplicate’ link or Canva template link inside a short PDF.","Start with a simple launch price and publish."],"est_minutes":60,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":40,"metric_to_track":"Products listed"},{"id":"p2s2","title":"Make a free mini version","why":"A free template collects emails and builds trust. Many buyers try the free one before paying for the full one.","instructions":["Strip your template down to its single most useful part.","Publish it on Gumroad at $0+ (pay what you want) so you collect emails.","Inside it, add a clear link to the full version."],"est_minutes":120,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":40,"metric_to_track":"Free downloads"},{"id":"p2s3","title":"Post 5 pieces of content about it","why":"Template sellers who show their templates in action on TikTok, Instagram or YouTube get most of their sales from there.","instructions":["Record 5 short screen videos: a before/after, a quick tour, a tip, a setup, a ‘how I organize…’.","Post them on one platform where your audience already is.","Put your free template link in your bio."],"est_minutes":90,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false}],"xp":40,"metric_to_track":"Views"},{"id":"p2s4","title":"Set up simple money tracking","why":"Knowing your weekly revenue, fees and costs keeps you honest about what works.","instructions":["Create a sheet with: date, product, price, fees, profit.","Update it before each weekly check-in.","Check how side income is taxed where you live, and set aside part of your profit."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Weekly profit"}]},{"id":"p3","title":"Traction","goal":"Grow to 3 paid templates and improve your product pages with real feedback.","weeks":"6-8","steps":[{"id":"p3s1","title":"Build 2 more templates","why":"Each new template for the same audience makes every visitor more likely to buy something.","instructions":["Ask buyers and free users what they wish your template also did.","Build the 2 most requested ideas.","Publish them with the same page structure as your first product."],"est_minutes":360,"resources":[],"tools":[],"xp":60,"metric_to_track":"Products listed"},{"id":"p3s2","title":"Improve your product page","why":"If people visit but don't buy, the page isn't answering their questions yet.","instructions":["Check views vs sales in Gumroad for each product.","Add an FAQ answering the questions people message you about.","Test a new cover image or headline for 2 weeks."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Views to sales rate"},{"id":"p3s3","title":"Email your free users","why":"People who downloaded your free template already trust you. A short, useful email often brings the first sales.","instructions":["Write one email with a practical tip for using the free template.","Mention the full version and what extra it solves.","Send it through Gumroad's email feature to your followers."],"est_minutes":45,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":30,"metric_to_track":"Sales from email"}]},{"id":"p4","title":"Scale","goal":"Bundle your templates, add another sales channel and post on a steady schedule.","weeks":"9-12","steps":[{"id":"p4s1","title":"Create a bundle","why":"A bundle raises your average order and gives buyers an easy ‘get everything’ choice.","instructions":["Combine all your templates into one product.","Price it below the total of the individual products.","Offer it as an upgrade on each single product page."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Bundle sales"},{"id":"p4s2","title":"List your templates on a second marketplace","why":"Etsy and the Notion marketplace have buyers who never visit Gumroad. Same product, new audience.","instructions":["Choose Etsy or the Notion template gallery as your second channel.","Reuse your images and adapt titles to how people search there.","Track which channel brings more sales per hour spent."],"est_minutes":90,"resources":[{"title":"Notion template gallery","url":"https://www.notion.com/templates"}],"tools":[{"name":"Etsy","url":"https://www.etsy.com/sell","affiliate":false}],"xp":40,"metric_to_track":"Sales per channel"},{"id":"p4s3","title":"Build a weekly content routine","why":"Template sales follow attention. A steady 3-posts-a-week routine beats occasional viral hits.","instructions":["Pick 3 fixed posting days.","Batch-record a week of short videos in one session.","Repost your best-performing video on a second platform."],"est_minutes":90,"resources":[],"tools":[],"xp":50,"metric_to_track":"Posts published"}]}],"weekly_metrics":["listings","views","sales"],"earning_milestones":[{"label":"Months 1–3","range":"$0–$200 / month","note":"Sales follow content. Expect a slow start while you build an audience."},{"label":"Months 4–6","range":"$100–$600 / month","note":"Several templates plus a bundle for one audience."},{"label":"Months 6–12","range":"$200–$1,500 / month","note":"Typical for sellers who post consistently and sell on 2+ channels."}]}$roadmap$),
  ('notion-canva-templates', 'pl', $roadmap${"hustle_slug":"notion-canva-templates","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Pierwszy szablon","goal":"Wybierz grupę z konkretnym problemem i zbuduj jeden szablon, który go rozwiązuje.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz grupę odbiorców i jeden problem","why":"„Szablon produktywności” jest zbyt ogólny, by się sprzedać. „Tracker klientów dla freelance'owych grafików” od razu mówi kupującym, że to dla nich.","instructions":["Wypisz 5 grup, które rozumiesz (studenci, freelancerzy, małe sklepy, twórcy treści, osoby szukające pracy).","Przy każdej zapisz najbardziej uciążliwą rzecz, którą organizują ręcznie.","Przejrzyj galerię szablonów Notion i Gumroad, żeby zobaczyć, co już się dla nich sprzedaje.","Wybierz jedną grupę i jeden problem."],"est_minutes":45,"resources":[{"title":"Galeria szablonów Notion","url":"https://www.notion.com/templates"}],"tools":[],"xp":30,"metric_to_track":"Wybrana grupa i problem"},{"id":"p1s2","title":"Zbuduj pierwszy szablon","why":"Szablon, który ludzie kochają, jest prosty, czytelnie opisany i gotowy do użycia w 5 minut. To on zbiera opinie i powracających klientów.","instructions":["Zbuduj go w Notion (bazy danych, widoki, przyciski) albo w Canvie (edytowalne projekty), zależnie od odbiorców.","Dodaj stronę „Zacznij tutaj” z 3–5 krótkimi instrukcjami.","Wypełnij go realistycznymi przykładowymi danymi, by kupujący widzieli, jak działa.","Poproś jedną osobę z grupy docelowej o test i zanotuj, gdzie się zacina."],"est_minutes":240,"resources":[{"title":"Licencja na treści Canva","url":"https://www.canva.com/policies/content-license-agreement/"}],"tools":[{"name":"Notion","url":"https://www.notion.com","affiliate":false},{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":40,"metric_to_track":"Szablon gotowy i przetestowany"},{"id":"p1s3","title":"Załóż sklep na Gumroad","why":"Gumroad pozwala sprzedawać produkty cyfrowe bez abonamentu i automatycznie dostarcza pliki po płatności.","instructions":["Załóż konto na Gumroad i podłącz metodę wypłat.","Dodaj zdjęcie profilowe, krótkie bio i link do swojego konta w social mediach.","Sprawdź, jakie opłaty obowiązują przy sprzedaży, żeby dobrze ustalić cenę."],"est_minutes":60,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":30,"metric_to_track":"Sklep gotowy"},{"id":"p1s4","title":"Przygotuj grafiki podglądu i demo","why":"Kupujący decydują w kilka sekund. Czytelne podglądy i 30-sekundowe demo pokazują wartość lepiej niż opis.","instructions":["Zrób zrzuty kluczowych widoków i umieść je na czystych tłach w Canvie.","Nagraj krótki film z ekranu, pokazujący szablon.","Przygotuj okładkę z efektem dla kupującego, np. „Już nigdy nie zgubisz klienta”."],"est_minutes":60,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":30,"metric_to_track":"Gotowe grafiki podglądu"}]},{"id":"p2","title":"Start sprzedaży","goal":"Opublikuj szablon, rozdaj darmową wersję i zacznij o nim publikować.","weeks":"3-5","steps":[{"id":"p2s1","title":"Wystaw szablon na sprzedaż","why":"Aktywna strona produktu pozwala testować cenę i przekaz na prawdziwych ludziach.","instructions":["Utwórz produkt na Gumroad z okładką, podglądami i filmem demo.","Napisz opis w kolejności: problem, zawartość, dla kogo, jak zacząć.","Dostarcz link do duplikacji w Notion lub link do szablonu Canva w krótkim PDF-ie.","Zacznij od prostej ceny premierowej i opublikuj."],"est_minutes":60,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":40,"metric_to_track":"Produkty w ofercie"},{"id":"p2s2","title":"Zrób darmową mini wersję","why":"Darmowy szablon zbiera adresy e-mail i buduje zaufanie. Wielu kupujących najpierw testuje darmową wersję.","instructions":["Zostaw z szablonu tylko jego najbardziej przydatną część.","Opublikuj ją na Gumroad za 0+ $ (płać, ile chcesz), by zbierać e-maile.","W środku dodaj wyraźny link do pełnej wersji."],"est_minutes":120,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":40,"metric_to_track":"Darmowe pobrania"},{"id":"p2s3","title":"Opublikuj 5 treści o szablonie","why":"Sprzedawcy, którzy pokazują szablony w akcji na TikToku, Instagramie czy YouTube, stamtąd mają większość sprzedaży.","instructions":["Nagraj 5 krótkich filmów z ekranu: przed/po, szybki przegląd, wskazówka, konfiguracja, „jak organizuję…”.","Opublikuj je na jednej platformie, na której są Twoi odbiorcy.","Umieść link do darmowego szablonu w bio."],"est_minutes":90,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false}],"xp":40,"metric_to_track":"Wyświetlenia"},{"id":"p2s4","title":"Ustaw proste śledzenie pieniędzy","why":"Znajomość tygodniowych przychodów, opłat i kosztów pokazuje uczciwie, co działa.","instructions":["Utwórz arkusz: data, produkt, cena, opłaty, zysk.","Aktualizuj go przed każdym cotygodniowym podsumowaniem.","Sprawdź, jak rozlicza się dodatkowe dochody w Twoim kraju (w Polsce np. działalność nierejestrowana), i odkładaj część zysku."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Zysk tygodniowy"}]},{"id":"p3","title":"Pierwsze efekty","goal":"Dojdź do 3 płatnych szablonów i popraw strony produktów na podstawie opinii.","weeks":"6-8","steps":[{"id":"p3s1","title":"Zbuduj 2 kolejne szablony","why":"Każdy nowy szablon dla tej samej grupy zwiększa szansę, że odwiedzający coś kupi.","instructions":["Zapytaj kupujących i użytkowników darmowej wersji, czego jeszcze brakuje w szablonie.","Zbuduj 2 najczęściej zgłaszane pomysły.","Opublikuj je z taką samą strukturą strony jak pierwszy produkt."],"est_minutes":360,"resources":[],"tools":[],"xp":60,"metric_to_track":"Produkty w ofercie"},{"id":"p3s2","title":"Popraw stronę produktu","why":"Jeśli ludzie odwiedzają, ale nie kupują, strona jeszcze nie odpowiada na ich pytania.","instructions":["Sprawdź w Gumroad stosunek wyświetleń do sprzedaży każdego produktu.","Dodaj FAQ z odpowiedziami na pytania, które dostajesz w wiadomościach.","Przez 2 tygodnie testuj nową okładkę lub nagłówek."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Konwersja wyświetleń na sprzedaż"},{"id":"p3s3","title":"Napisz do użytkowników darmowej wersji","why":"Osoby, które pobrały darmowy szablon, już Ci ufają. Krótki, przydatny e-mail często przynosi pierwsze sprzedaże.","instructions":["Napisz jeden e-mail z praktyczną wskazówką dotyczącą darmowego szablonu.","Wspomnij o pełnej wersji i o tym, co dodatkowo rozwiązuje.","Wyślij go obserwującym przez funkcję e-mail w Gumroad."],"est_minutes":45,"resources":[],"tools":[{"name":"Gumroad","url":"https://gumroad.com","affiliate":false}],"xp":30,"metric_to_track":"Sprzedaż z e-maili"}]},{"id":"p4","title":"Skalowanie","goal":"Połącz szablony w pakiet, dodaj kolejny kanał sprzedaży i publikuj regularnie.","weeks":"9-12","steps":[{"id":"p4s1","title":"Stwórz pakiet","why":"Pakiet podnosi średnią wartość zamówienia i daje kupującym łatwy wybór „biorę wszystko”.","instructions":["Połącz wszystkie szablony w jeden produkt.","Ustal cenę niższą niż suma pojedynczych produktów.","Proponuj go jako ulepszenie na stronie każdego produktu."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Sprzedaż pakietów"},{"id":"p4s2","title":"Wystaw szablony na drugim marketplace","why":"Na Etsy i w marketplace Notion są kupujący, którzy nie zaglądają na Gumroad. Ten sam produkt, nowi odbiorcy.","instructions":["Wybierz Etsy lub galerię szablonów Notion jako drugi kanał.","Wykorzystaj te same grafiki i dopasuj tytuły do tego, jak tam się wyszukuje.","Sprawdzaj, który kanał daje więcej sprzedaży na godzinę pracy."],"est_minutes":90,"resources":[{"title":"Galeria szablonów Notion","url":"https://www.notion.com/templates"}],"tools":[{"name":"Etsy","url":"https://www.etsy.com/sell","affiliate":false}],"xp":40,"metric_to_track":"Sprzedaż w kanale"},{"id":"p4s3","title":"Ustal cotygodniowy rytm publikacji","why":"Sprzedaż szablonów idzie za uwagą. Stały rytm 3 postów tygodniowo wygrywa z okazjonalnymi viralami.","instructions":["Wybierz 3 stałe dni publikacji.","Nagrywaj tygodniową porcję krótkich filmów podczas jednej sesji.","Najlepszy film opublikuj też na drugiej platformie."],"est_minutes":90,"resources":[],"tools":[],"xp":50,"metric_to_track":"Opublikowane posty"}]}],"weekly_metrics":["listings","views","sales"],"earning_milestones":[{"label":"Miesiące 1–3","range":"0–200 $ / mies.","note":"Sprzedaż idzie za treściami. Spodziewaj się powolnego startu, zanim zbudujesz publiczność."},{"label":"Miesiące 4–6","range":"100–600 $ / mies.","note":"Kilka szablonów i pakiet dla jednej grupy odbiorców."},{"label":"Miesiące 6–12","range":"200–1500 $ / mies.","note":"Typowe dla sprzedawców publikujących regularnie w 2+ kanałach."}]}$roadmap$),
  ('pinterest-affiliate', 'en', $roadmap${"hustle_slug":"pinterest-affiliate","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Niche & accounts","goal":"Pick a product niche, set up your Pinterest business account and join an affiliate program.","weeks":"1-2","steps":[{"id":"p1s1","title":"Pick a niche people shop for on Pinterest","why":"People use Pinterest to plan purchases: home decor, kitchen, fashion, crafts, travel gear, baby products. Those niches convert best.","instructions":["List 5 niches where people save product ideas.","Check each in Pinterest Trends to see if interest is steady or growing.","Pick one niche with many products under $100 that people buy online."],"est_minutes":45,"resources":[{"title":"Pinterest Trends","url":"https://trends.pinterest.com"}],"tools":[],"xp":30,"metric_to_track":"Niche chosen"},{"id":"p1s2","title":"Set up a Pinterest business account","why":"A business account is free and unlocks analytics, so you can see which pins bring clicks.","instructions":["Create a free business account with a name that includes your niche keyword.","Write a profile description with 2–3 search phrases.","Create 5 boards named after what people search for (e.g. ‘Small Kitchen Organization Ideas’)."],"est_minutes":60,"resources":[{"title":"Pinterest Business","url":"https://business.pinterest.com"}],"tools":[],"xp":30,"metric_to_track":"Boards created"},{"id":"p1s3","title":"Join an affiliate program","why":"Affiliate programs give you trackable links that pay a commission when someone buys.","instructions":["Apply to Amazon Associates or a program from brands in your niche.","Add your Pinterest profile to your affiliate account where required.","Read the program's rules about where links may be posted.","Plan how you'll disclose affiliate links in every pin description."],"est_minutes":45,"resources":[{"title":"FTC: disclosures for influencers","url":"https://www.ftc.gov/business-guidance/resources/disclosures-101-social-media-influencers"}],"tools":[{"name":"Amazon Associates","url":"https://affiliate-program.amazon.com","affiliate":false}],"xp":30,"metric_to_track":"Program approved"},{"id":"p1s4","title":"Create 3 pin templates","why":"Templates let you make a fresh pin in 5 minutes. Pinterest favors new images over repins.","instructions":["Design 3 vertical templates (2:3 ratio, e.g. 1000×1500 px) in Canva.","Include a large, readable headline and space for 1–4 product photos.","Use consistent fonts and colors so people recognize your pins."],"est_minutes":60,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":30,"metric_to_track":"Templates ready"}]},{"id":"p2","title":"Start pinning","goal":"Publish fresh pins every day and get your first clicks.","weeks":"3-5","steps":[{"id":"p2s1","title":"Build your keyword list","why":"Pinterest is a search engine. Pins with the right words in the title and description keep appearing for months.","instructions":["Type your niche into Pinterest search and write down the suggested phrases.","Check Pinterest Trends for seasonal peaks.","Collect 30 phrases in a sheet."],"est_minutes":45,"resources":[{"title":"Pinterest Trends","url":"https://trends.pinterest.com"}],"tools":[],"xp":30,"metric_to_track":"Keywords collected"},{"id":"p2s2","title":"Create your first 30 pins","why":"Volume matters on Pinterest. 30 pins give you enough data to see what people click.","instructions":["Make each pin around one keyword and one clear benefit.","Link each pin to a product (or a page listing several products) with your affiliate link.","Write a title and description with the keyword and a clear ‘affiliate link’ note."],"est_minutes":240,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Pins published"},{"id":"p2s3","title":"Pin 3–5 fresh pins a day for 3 weeks","why":"Daily consistency tells Pinterest your account is active. Accounts that pin steadily get more distribution.","instructions":["Schedule pins in advance using Pinterest's built-in scheduler.","Spread pins across different boards and products.","Avoid pinning the exact same image repeatedly. Change the photo or headline instead."],"est_minutes":300,"resources":[],"tools":[],"xp":50,"metric_to_track":"Pins published"},{"id":"p2s4","title":"Track clicks and commissions","why":"Commissions arrive with delays. A weekly log shows which boards and products really earn.","instructions":["Create a sheet with: week, pins, outbound clicks, orders, commission.","Fill it before every weekly check-in.","Check how side income is taxed where you live."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Outbound clicks"}]},{"id":"p3","title":"Double down","goal":"Find your best pins and make more like them.","weeks":"6-8","steps":[{"id":"p3s1","title":"Find your top 5 pins","why":"A few pins usually drive most clicks. Knowing which ones tells you what to make next.","instructions":["Open Pinterest Analytics and sort pins by outbound clicks.","Note what the top 5 share: topic, image style, headline type.","Compare with the products that earned commissions."],"est_minutes":45,"resources":[],"tools":[],"xp":40,"metric_to_track":"Top pins identified"},{"id":"p3s2","title":"Make 10 variations of your top pins","why":"New images of a winning idea reach new people while keeping what already works.","instructions":["For each top pin, create 2 new versions with different photos or headlines.","Target a related keyword in each version.","Schedule them over the next 2 weeks."],"est_minutes":180,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Outbound clicks"},{"id":"p3s3","title":"Plan seasonal pins early","why":"Pinterest users plan weeks or months ahead. Seasonal pins need time to rank before the peak.","instructions":["List the next 3 seasonal moments in your niche (holidays, back to school, summer).","Create boards for them now.","Start pinning seasonal content 6–8 weeks before each one."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Seasonal pins scheduled"}]},{"id":"p4","title":"Scale","goal":"Add higher-paying offers and build a system you can run in a few hours a week.","weeks":"9-12","steps":[{"id":"p4s1","title":"Add a higher-commission program","why":"Commission rates vary a lot. Brands with their own programs often pay more than large marketplaces.","instructions":["Search for ‘[brand] affiliate program’ for the brands you pin most.","Compare commission rates and cookie length.","Swap links on your top pins to the better-paying program where allowed."],"est_minutes":60,"resources":[],"tools":[{"name":"Awin","url":"https://www.awin.com","affiliate":false}],"xp":40,"metric_to_track":"Commission per click"},{"id":"p4s2","title":"Create a roundup page for your best topic","why":"A simple ‘best products for…’ page lets one pin earn from several products and works with programs that don't allow direct links.","instructions":["Build a free one-page site (e.g. with Notion or a simple website builder).","List 5–10 products with a photo, one honest sentence each and your affiliate link.","Point your best pins to this page."],"est_minutes":180,"resources":[],"tools":[{"name":"Notion","url":"https://www.notion.com","affiliate":false}],"xp":50,"metric_to_track":"Clicks from the roundup page"},{"id":"p4s3","title":"Batch a full month of pins","why":"Batching turns Pinterest into a few focused sessions a month, which you can keep up for a long time.","instructions":["Create around 90 pins in 2–3 sessions using your templates.","Schedule them evenly over the next 30 days.","Block one hour a week to check analytics and adjust."],"est_minutes":240,"resources":[],"tools":[],"xp":50,"metric_to_track":"Pins scheduled"}]}],"weekly_metrics":["pins_published","clicks","sales"],"earning_milestones":[{"label":"Months 1–3","range":"$0–$100 / month","note":"Pins take weeks to gain traction. Early commissions are small."},{"label":"Months 4–6","range":"$50–$400 / month","note":"Winning pins keep bringing clicks while you add new ones."},{"label":"Months 6–12","range":"$200–$1,000 / month","note":"Typical for consistent pinners with several affiliate programs."}]}$roadmap$),
  ('pinterest-affiliate', 'pl', $roadmap${"hustle_slug":"pinterest-affiliate","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Nisza i konta","goal":"Wybierz niszę produktową, załóż konto firmowe na Pintereście i dołącz do programu afiliacyjnego.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz niszę, w której ludzie kupują na Pintereście","why":"Ludzie używają Pinteresta do planowania zakupów: wystrój wnętrz, kuchnia, moda, rękodzieło, sprzęt podróżny, produkty dla dzieci. Te nisze sprzedają najlepiej.","instructions":["Wypisz 5 nisz, w których ludzie zapisują pomysły na produkty.","Sprawdź każdą w Pinterest Trends, czy zainteresowanie jest stałe lub rośnie.","Wybierz jedną niszę z wieloma produktami poniżej 100 $, kupowanymi online."],"est_minutes":45,"resources":[{"title":"Pinterest Trends","url":"https://trends.pinterest.com"}],"tools":[],"xp":30,"metric_to_track":"Wybrana nisza"},{"id":"p1s2","title":"Załóż konto firmowe na Pintereście","why":"Konto firmowe jest darmowe i odblokowuje statystyki, dzięki którym widzisz, które piny przynoszą kliknięcia.","instructions":["Załóż darmowe konto firmowe z nazwą zawierającą słowo kluczowe niszy.","Napisz opis profilu z 2–3 frazami wyszukiwania.","Utwórz 5 tablic nazwanych tak, jak ludzie szukają (np. „Small Kitchen Organization Ideas”)."],"est_minutes":60,"resources":[{"title":"Pinterest Business (ang.)","url":"https://business.pinterest.com"}],"tools":[],"xp":30,"metric_to_track":"Utworzone tablice"},{"id":"p1s3","title":"Dołącz do programu afiliacyjnego","why":"Programy afiliacyjne dają linki, które naliczają prowizję, gdy ktoś kupi.","instructions":["Zgłoś się do Amazon Associates lub programu marek z Twojej niszy.","Tam, gdzie jest to wymagane, dodaj profil Pinterest w ustawieniach konta afiliacyjnego.","Przeczytaj zasady programu dotyczące miejsc publikacji linków.","Zaplanuj, jak oznaczysz linki afiliacyjne w opisie każdego pinu."],"est_minutes":45,"resources":[{"title":"FTC: oznaczanie współprac (ang.)","url":"https://www.ftc.gov/business-guidance/resources/disclosures-101-social-media-influencers"}],"tools":[{"name":"Amazon Associates","url":"https://affiliate-program.amazon.com","affiliate":false}],"xp":30,"metric_to_track":"Zatwierdzony program"},{"id":"p1s4","title":"Przygotuj 3 szablony pinów","why":"Szablony pozwalają zrobić nowy pin w 5 minut. Pinterest faworyzuje nowe grafiki zamiast ponownych przypięć.","instructions":["Zaprojektuj w Canvie 3 pionowe szablony (proporcje 2:3, np. 1000×1500 px).","Dodaj duży, czytelny nagłówek i miejsce na 1–4 zdjęcia produktów.","Używaj spójnych czcionek i kolorów, by ludzie rozpoznawali Twoje piny."],"est_minutes":60,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":30,"metric_to_track":"Gotowe szablony"}]},{"id":"p2","title":"Start przypinania","goal":"Codziennie publikuj nowe piny i zdobądź pierwsze kliknięcia.","weeks":"3-5","steps":[{"id":"p2s1","title":"Zbuduj listę słów kluczowych","why":"Pinterest to wyszukiwarka. Piny z właściwymi słowami w tytule i opisie pojawiają się miesiącami.","instructions":["Wpisz niszę w wyszukiwarkę Pinteresta i zapisz podpowiadane frazy.","Sprawdź w Pinterest Trends sezonowe szczyty.","Zbierz 30 fraz w arkuszu."],"est_minutes":45,"resources":[{"title":"Pinterest Trends","url":"https://trends.pinterest.com"}],"tools":[],"xp":30,"metric_to_track":"Zebrane słowa kluczowe"},{"id":"p2s2","title":"Stwórz pierwsze 30 pinów","why":"Na Pintereście liczy się liczba. 30 pinów daje dość danych, by zobaczyć, co ludzie klikają.","instructions":["Każdy pin buduj wokół jednego słowa kluczowego i jednej korzyści.","Podlinkuj każdy pin do produktu (lub strony z kilkoma produktami) linkiem afiliacyjnym.","Napisz tytuł i opis ze słowem kluczowym i wyraźną informacją o linku afiliacyjnym."],"est_minutes":240,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Opublikowane piny"},{"id":"p2s3","title":"Przypinaj 3–5 nowych pinów dziennie przez 3 tygodnie","why":"Codzienna regularność pokazuje Pinterestowi, że konto jest aktywne. Konta publikujące stale dostają większe zasięgi.","instructions":["Planuj piny z wyprzedzeniem we wbudowanym harmonogramie Pinteresta.","Rozkładaj piny na różne tablice i produkty.","Nie przypinaj wielokrotnie tej samej grafiki. Zmieniaj zdjęcie lub nagłówek."],"est_minutes":300,"resources":[],"tools":[],"xp":50,"metric_to_track":"Opublikowane piny"},{"id":"p2s4","title":"Śledź kliknięcia i prowizje","why":"Prowizje wpływają z opóźnieniem. Cotygodniowy zapis pokazuje, które tablice i produkty naprawdę zarabiają.","instructions":["Utwórz arkusz: tydzień, piny, kliknięcia wychodzące, zamówienia, prowizja.","Uzupełniaj go przed każdym cotygodniowym podsumowaniem.","Sprawdź, jak rozlicza się dodatkowe dochody w Twoim kraju (w Polsce np. działalność nierejestrowana)."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Kliknięcia wychodzące"}]},{"id":"p3","title":"Postaw na to, co działa","goal":"Znajdź najlepsze piny i rób więcej podobnych.","weeks":"6-8","steps":[{"id":"p3s1","title":"Znajdź 5 najlepszych pinów","why":"Kilka pinów zwykle generuje większość kliknięć. Wiedza, które to są, mówi, co robić dalej.","instructions":["Otwórz statystyki Pinteresta i posortuj piny według kliknięć wychodzących.","Zanotuj, co łączy 5 najlepszych: temat, styl grafiki, rodzaj nagłówka.","Porównaj to z produktami, które przyniosły prowizję."],"est_minutes":45,"resources":[],"tools":[],"xp":40,"metric_to_track":"Wskazane najlepsze piny"},{"id":"p3s2","title":"Zrób 10 wariantów najlepszych pinów","why":"Nowe grafiki zwycięskiego pomysłu docierają do nowych osób, zachowując to, co działa.","instructions":["Do każdego najlepszego pinu zrób 2 nowe wersje z innymi zdjęciami lub nagłówkami.","W każdej wersji celuj w pokrewne słowo kluczowe.","Zaplanuj je na najbliższe 2 tygodnie."],"est_minutes":180,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Kliknięcia wychodzące"},{"id":"p3s3","title":"Zaplanuj sezonowe piny z wyprzedzeniem","why":"Użytkownicy Pinteresta planują z tygodniowym lub miesięcznym wyprzedzeniem. Sezonowe piny potrzebują czasu, by się wypozycjonować.","instructions":["Wypisz 3 najbliższe sezonowe okazje w niszy (święta, powrót do szkoły, lato).","Utwórz dla nich tablice już teraz.","Zacznij przypinać treści sezonowe 6–8 tygodni wcześniej."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Zaplanowane piny sezonowe"}]},{"id":"p4","title":"Skalowanie","goal":"Dodaj lepiej płatne oferty i zbuduj system, który obsłużysz w kilka godzin tygodniowo.","weeks":"9-12","steps":[{"id":"p4s1","title":"Dodaj program z wyższą prowizją","why":"Stawki prowizji bardzo się różnią. Marki z własnymi programami często płacą więcej niż duże marketplace'y.","instructions":["Wyszukaj „[marka] affiliate program” dla marek, które przypinasz najczęściej.","Porównaj stawki prowizji i czas ważności plików cookie.","Tam, gdzie to dozwolone, podmień linki w najlepszych pinach na lepiej płatny program."],"est_minutes":60,"resources":[],"tools":[{"name":"Awin","url":"https://www.awin.com","affiliate":false}],"xp":40,"metric_to_track":"Prowizja na kliknięcie"},{"id":"p4s2","title":"Stwórz stronę zestawienia dla najlepszego tematu","why":"Prosta strona „najlepsze produkty do…” pozwala jednemu pinowi zarabiać na kilku produktach i działa z programami, które nie pozwalają na bezpośrednie linki.","instructions":["Zbuduj darmową jednostronicową witrynę (np. w Notion lub prostym kreatorze stron).","Wypisz 5–10 produktów ze zdjęciem, jednym szczerym zdaniem i linkiem afiliacyjnym.","Kieruj najlepsze piny na tę stronę."],"est_minutes":180,"resources":[],"tools":[{"name":"Notion","url":"https://www.notion.com","affiliate":false}],"xp":50,"metric_to_track":"Kliknięcia ze strony zestawienia"},{"id":"p4s3","title":"Przygotuj hurtowo piny na cały miesiąc","why":"Praca hurtowa zamienia Pinterest w kilka skupionych sesji w miesiącu, które da się utrzymać na długo.","instructions":["Stwórz około 90 pinów w 2–3 sesjach, korzystając z szablonów.","Rozplanuj je równomiernie na 30 dni.","Zarezerwuj godzinę tygodniowo na statystyki i poprawki."],"est_minutes":240,"resources":[],"tools":[],"xp":50,"metric_to_track":"Zaplanowane piny"}]}],"weekly_metrics":["pins_published","clicks","sales"],"earning_milestones":[{"label":"Miesiące 1–3","range":"0–100 $ / mies.","note":"Piny potrzebują tygodni, by się rozkręcić. Pierwsze prowizje są niewielkie."},{"label":"Miesiące 4–6","range":"50–400 $ / mies.","note":"Zwycięskie piny przynoszą kliknięcia, a Ty dodajesz nowe."},{"label":"Miesiące 6–12","range":"200–1000 $ / mies.","note":"Typowe dla osób regularnie przypinających z kilkoma programami afiliacyjnymi."}]}$roadmap$),
  ('print-on-demand', 'en', $roadmap${"hustle_slug":"print-on-demand","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Niche & shop setup","goal":"Pick a niche you can design for and open an Etsy shop connected to Printful.","weeks":"1-2","steps":[{"id":"p1s1","title":"Pick one specific niche","why":"Broad shops get lost in search. A narrow audience (like night-shift nurses or retro camper owners) tells you exactly what to design and which words buyers type.","instructions":["List 10 hobbies, jobs or identities people are proud of or joke about (e.g. ‘night-shift nurses’, ‘sourdough bakers’).","Search each one on Etsy and note whether the top listings have many reviews (proof that people buy).","Pick one niche with real demand where you can still stand out.","Write down 20 phrases, inside jokes or references your niche uses."],"est_minutes":45,"resources":[{"title":"Etsy Seller Handbook","url":"https://www.etsy.com/seller-handbook"}],"tools":[{"name":"eRank","url":"https://erank.com","affiliate":false}],"xp":30,"metric_to_track":"1 niche chosen, 20 design ideas listed"},{"id":"p1s2","title":"Check trademarks before you design","why":"Trademarked phrases, brands and characters get listings removed and can close your shop. A 30-minute check protects everything you build.","instructions":["Search every phrase from your list in a trademark database.","Drop anything with brand names, sports teams, movie or game characters, or celebrity names.","Keep only phrases that are free to use, and note where you checked them."],"est_minutes":30,"resources":[{"title":"Etsy intellectual property policy","url":"https://www.etsy.com/legal/ip"},{"title":"TMview trademark search","url":"https://www.tmdn.org/tmview/"}],"tools":[],"xp":20,"metric_to_track":"Phrases checked"},{"id":"p1s3","title":"Open your Etsy shop and connect Printful","why":"Once Printful is connected, every order is printed and shipped automatically. You focus on designs, not packages.","instructions":["Create an Etsy seller account. Have your ID and bank details ready; some countries pay a small one-time setup fee.","Add a shop name, banner and a short ‘About’ section that speaks to your niche.","Create a free Printful account and connect it to Etsy under Stores.","In your Etsy listings, add Printful as a production partner. Etsy requires this for print-on-demand."],"est_minutes":90,"resources":[{"title":"Printful + Etsy integration","url":"https://www.printful.com/integrations/etsy"},{"title":"Etsy fees explained","url":"https://www.etsy.com/legal/fees/"}],"tools":[{"name":"Etsy","url":"https://www.etsy.com/sell","affiliate":false},{"name":"Printful","url":"https://www.printful.com","affiliate":false}],"xp":40,"metric_to_track":"Shop open and connected"},{"id":"p1s4","title":"Order one sample","why":"Seeing and touching the product shows you real print quality and colors, and gives you your own photos, which convert better than mockups.","instructions":["Pick the product type most sellers in your niche use (usually a T-shirt or a mug).","Order one sample through Printful's sample order option to pay less.","Check colors, print size and fabric, then photograph it in daylight for your listings."],"est_minutes":30,"resources":[],"tools":[{"name":"Printful","url":"https://www.printful.com","affiliate":false}],"xp":30,"metric_to_track":"Sample ordered"}]},{"id":"p2","title":"Designs & first listings","goal":"Publish your first 20 listings with strong titles, tags and mockups.","weeks":"3-5","steps":[{"id":"p2s1","title":"Create your first 10 designs","why":"Etsy rewards shops with many relevant listings. More designs mean more chances to be found.","instructions":["Start with text-based designs using your phrase list. They're fast to make and often sell well.","Export at the size Printful asks for in the product's print file guidelines, with a transparent background.","Make a light and a dark version of each design so it works on more product colors.","Save files in folders named by niche and phrase."],"est_minutes":240,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Designs finished"},{"id":"p2s2","title":"Write search-friendly titles and 13 tags","why":"Buyers find you through the words they type. Titles and tags decide whether your listing shows up at all.","instructions":["Start each title with what a buyer would type, e.g. ‘Night Shift Nurse Shirt, Funny Nurse Gift’.","Use all 13 tags. Each tag can be up to 20 characters.","Use phrases instead of single words (e.g. ‘nurse gift for her’).","Check how often phrases are searched in eRank before you finalize them."],"est_minutes":60,"resources":[{"title":"Etsy Seller Handbook","url":"https://www.etsy.com/seller-handbook"}],"tools":[{"name":"eRank","url":"https://erank.com","affiliate":false}],"xp":30,"metric_to_track":"Listings with full titles and tags"},{"id":"p2s3","title":"Publish your first 20 listings","why":"Your listings are your storefront. Around 20 is when a new shop starts to get steady views.","instructions":["Create each product in Printful and push it to Etsy.","Use at least 5 images per listing, including one lifestyle photo or your sample photo.","Set prices so you keep a profit after Printful costs, shipping and Etsy fees. Aim for at least $5–8 per item.","Publish, then open every listing on your phone to check it looks right."],"est_minutes":300,"resources":[{"title":"Etsy fees explained","url":"https://www.etsy.com/legal/fees/"}],"tools":[{"name":"Printful","url":"https://www.printful.com","affiliate":false}],"xp":60,"metric_to_track":"Listings live"},{"id":"p2s4","title":"Set up simple profit tracking","why":"Print-on-demand margins are thin. You need to know your real profit per sale, not just revenue.","instructions":["Create a spreadsheet with columns: date, product, sale price, Printful cost, Etsy fees, profit.","Add every sale once a week, before your check-in.","Check how side income is taxed where you live, and set aside part of your profit."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Profit per sale"}]},{"id":"p3","title":"Traction","goal":"Get steady views and your first sales, then double down on what works.","weeks":"6-8","steps":[{"id":"p3s1","title":"Publish 20 more listings","why":"Most shops only see regular sales after 40–50 listings. Each new listing is another door into your shop.","instructions":["Put designs that got views or favorites on new products (mugs, hoodies, stickers).","Add 10 new designs in the same niche.","Reuse your best-performing tags as a starting point."],"est_minutes":300,"resources":[],"tools":[],"xp":60,"metric_to_track":"Listings live"},{"id":"p3s2","title":"Fix listings with views but no sales","why":"Small changes to your main photo and title can double clicks. Fixing a listing is faster than making a new one.","instructions":["In Etsy Stats, find listings with views but no favorites or sales.","Test a new main photo first. It drives most clicks.","Rewrite the title with a more specific phrase.","Change one thing at a time, and wait a week before judging."],"est_minutes":60,"resources":[],"tools":[{"name":"eRank","url":"https://erank.com","affiliate":false}],"xp":40,"metric_to_track":"Listings improved"},{"id":"p3s3","title":"Share your designs on Pinterest","why":"Pinterest works like a search engine for ideas and gifts. Pins keep bringing visitors for months.","instructions":["Create a free Pinterest business account.","Make a board for your niche and pin 3 mockups of different listings each day for a week.","Write pin titles with the same search phrases as your Etsy titles."],"est_minutes":60,"resources":[{"title":"Pinterest Business","url":"https://business.pinterest.com"}],"tools":[],"xp":40,"metric_to_track":"Shop visits from Pinterest"}]},{"id":"p4","title":"Scale","goal":"Turn your best sellers into a system and reach steady monthly profit.","weeks":"9-12","steps":[{"id":"p4s1","title":"Make 5 variations of each best seller","why":"A design that sells once will usually sell again in a new color, phrase or product. Winners are your cheapest growth.","instructions":["Sort listings by sales and favorites for the last 30 days.","For your top 3, create 5 variations each: new colors, new phrases, new product types.","Publish them with titles that target slightly different search phrases."],"est_minutes":45,"resources":[],"tools":[],"xp":40,"metric_to_track":"Sales from variations"},{"id":"p4s2","title":"Test Etsy Ads on proven listings only","why":"Ads amplify what already works. On unproven listings they mostly burn money.","instructions":["Turn on Etsy Ads with a small daily budget ($1–3).","Advertise only listings that have already sold.","After 2 weeks, compare ad cost per sale with your profit per sale, and stop ads that lose money."],"est_minutes":45,"resources":[],"tools":[],"xp":50,"metric_to_track":"Ad cost per sale"},{"id":"p4s3","title":"Plan your seasonal calendar","why":"Holidays drive most print-on-demand sales. Listings need 6–8 weeks to get found before the rush.","instructions":["List the holidays and events your niche cares about for the next 6 months.","Put each one in your calendar 8 weeks early as a ‘publish designs’ reminder.","Prepare 5 designs for the next upcoming event now."],"est_minutes":60,"resources":[],"tools":[],"xp":50,"metric_to_track":"Seasonal listings ready"}]}],"weekly_metrics":["listings","shop_visits","sales"],"earning_milestones":[{"label":"Months 1–3","range":"$0–$200 / month","note":"Most shops need 30–50 listings before sales become regular."},{"label":"Months 4–6","range":"$100–$500 / month","note":"Winners appear. Expanding them to new products drives growth."},{"label":"Months 6–12","range":"$300–$1,500 / month","note":"Typical for shops with 100+ focused listings and seasonal designs."}]}$roadmap$),
  ('print-on-demand', 'pl', $roadmap${"hustle_slug":"print-on-demand","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Nisza i sklep","goal":"Wybierz niszę, dla której umiesz projektować, i otwórz sklep na Etsy połączony z Printful.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz jedną konkretną niszę","why":"Ogólne sklepy giną w wyszukiwarce. Wąska grupa (np. pielęgniarki na nocnych zmianach albo fani starych kamperów) podpowiada, co projektować i jakie słowa wpisują kupujący.","instructions":["Wypisz 10 hobby, zawodów lub tożsamości, z których ludzie są dumni albo żartują (np. „pielęgniarki na nocce”, „piekarze chleba na zakwasie”).","Wyszukaj każdą na Etsy i sprawdź, czy najwyższe oferty mają dużo opinii (to dowód, że ludzie kupują).","Wybierz jedną niszę z realnym popytem, w której wciąż możesz się wyróżnić.","Zapisz 20 haseł, żartów lub nawiązań, których używa Twoja nisza."],"est_minutes":45,"resources":[{"title":"Etsy Seller Handbook (ang.)","url":"https://www.etsy.com/seller-handbook"}],"tools":[{"name":"eRank","url":"https://erank.com","affiliate":false}],"xp":30,"metric_to_track":"1 wybrana nisza, 20 pomysłów na projekty"},{"id":"p1s2","title":"Sprawdź znaki towarowe przed projektowaniem","why":"Zastrzeżone hasła, marki i postacie kończą się usunięciem ofert, a nawet zamknięciem sklepu. 30 minut sprawdzania chroni wszystko, co zbudujesz.","instructions":["Wyszukaj każde hasło z listy w bazie znaków towarowych.","Odrzuć wszystko z nazwami marek, drużyn sportowych, postaci z filmów lub gier albo nazwiskami celebrytów.","Zostaw tylko hasła, których możesz swobodnie używać, i zanotuj, gdzie je sprawdzono."],"est_minutes":30,"resources":[{"title":"Zasady Etsy dot. własności intelektualnej (ang.)","url":"https://www.etsy.com/legal/ip"},{"title":"Wyszukiwarka znaków towarowych TMview","url":"https://www.tmdn.org/tmview/"}],"tools":[],"xp":20,"metric_to_track":"Sprawdzone hasła"},{"id":"p1s3","title":"Otwórz sklep na Etsy i połącz Printful","why":"Po połączeniu z Printful każde zamówienie jest drukowane i wysyłane automatycznie. Ty skupiasz się na projektach, nie na paczkach.","instructions":["Załóż konto sprzedawcy na Etsy. Przygotuj dokument tożsamości i dane konta bankowego; w niektórych krajach obowiązuje niewielka jednorazowa opłata.","Dodaj nazwę sklepu, baner i krótką sekcję „O nas” skierowaną do Twojej niszy.","Załóż darmowe konto w Printful i połącz je z Etsy w sekcji Stores.","W ofertach na Etsy dodaj Printful jako partnera produkcyjnego. Etsy wymaga tego przy print on demand."],"est_minutes":90,"resources":[{"title":"Integracja Printful z Etsy (ang.)","url":"https://www.printful.com/integrations/etsy"},{"title":"Opłaty na Etsy (ang.)","url":"https://www.etsy.com/legal/fees/"}],"tools":[{"name":"Etsy","url":"https://www.etsy.com/sell","affiliate":false},{"name":"Printful","url":"https://www.printful.com","affiliate":false}],"xp":40,"metric_to_track":"Sklep otwarty i połączony"},{"id":"p1s4","title":"Zamów jedną próbkę","why":"Produkt w ręku pokazuje prawdziwą jakość i kolory nadruku, a do tego dostajesz własne zdjęcia, które sprzedają lepiej niż mockupy.","instructions":["Wybierz typ produktu, który najczęściej sprzedaje się w Twojej niszy (zwykle koszulka lub kubek).","Zamów jedną próbkę przez opcję zamówienia próbek w Printful, żeby zapłacić mniej.","Sprawdź kolory, rozmiar nadruku i materiał, a potem zrób zdjęcia w dziennym świetle do ofert."],"est_minutes":30,"resources":[],"tools":[{"name":"Printful","url":"https://www.printful.com","affiliate":false}],"xp":30,"metric_to_track":"Zamówiona próbka"}]},{"id":"p2","title":"Projekty i pierwsze oferty","goal":"Opublikuj pierwsze 20 ofert z mocnymi tytułami, tagami i mockupami.","weeks":"3-5","steps":[{"id":"p2s1","title":"Stwórz pierwsze 10 projektów","why":"Etsy nagradza sklepy z wieloma trafnymi ofertami. Więcej projektów to więcej szans, że ktoś Cię znajdzie.","instructions":["Zacznij od projektów tekstowych z listy haseł. Powstają szybko i często dobrze się sprzedają.","Eksportuj w rozmiarze z wytycznych Printful dla danego produktu, z przezroczystym tłem.","Przygotuj jasną i ciemną wersję każdego projektu, żeby pasowała do większej liczby kolorów.","Zapisuj pliki w folderach nazwanych według niszy i hasła."],"est_minutes":240,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Gotowe projekty"},{"id":"p2s2","title":"Napisz tytuły pod wyszukiwarkę i 13 tagów","why":"Kupujący znajdują Cię po słowach, które wpisują. Tytuły i tagi decydują, czy oferta w ogóle się pokaże.","instructions":["Zaczynaj tytuł od tego, co wpisałby kupujący, np. „Night Shift Nurse Shirt, Funny Nurse Gift”.","Wykorzystaj wszystkie 13 tagów. Każdy może mieć do 20 znaków.","Używaj fraz zamiast pojedynczych słów (np. „nurse gift for her”).","Zanim zatwierdzisz frazy, sprawdź w eRank, jak często są wyszukiwane."],"est_minutes":60,"resources":[{"title":"Etsy Seller Handbook (ang.)","url":"https://www.etsy.com/seller-handbook"}],"tools":[{"name":"eRank","url":"https://erank.com","affiliate":false}],"xp":30,"metric_to_track":"Oferty z pełnymi tytułami i tagami"},{"id":"p2s3","title":"Opublikuj pierwsze 20 ofert","why":"Oferty to Twoja witryna. Przy około 20 nowy sklep zaczyna dostawać regularne wyświetlenia.","instructions":["Utwórz każdy produkt w Printful i wyślij go na Etsy.","Dodaj co najmniej 5 zdjęć do oferty, w tym jedno lifestyle'owe lub zdjęcie próbki.","Ustal ceny tak, by po kosztach Printful, wysyłce i opłatach Etsy został zysk. Celuj w co najmniej 5–8 $ na sztuce.","Opublikuj, a potem otwórz każdą ofertę na telefonie i sprawdź, czy dobrze wygląda."],"est_minutes":300,"resources":[{"title":"Opłaty na Etsy (ang.)","url":"https://www.etsy.com/legal/fees/"}],"tools":[{"name":"Printful","url":"https://www.printful.com","affiliate":false}],"xp":60,"metric_to_track":"Aktywne oferty"},{"id":"p2s4","title":"Ustaw proste śledzenie zysku","why":"Marże w print on demand są niewielkie. Musisz znać realny zysk z każdej sprzedaży, nie tylko przychód.","instructions":["Utwórz arkusz z kolumnami: data, produkt, cena, koszt Printful, opłaty Etsy, zysk.","Raz w tygodniu, przed podsumowaniem, dopisuj każdą sprzedaż.","Sprawdź, jak rozlicza się dodatkowe dochody w Twoim kraju (w Polsce np. zasady działalności nierejestrowanej), i odkładaj część zysku."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Zysk na sprzedaży"}]},{"id":"p3","title":"Pierwsze efekty","goal":"Zdobądź regularne wyświetlenia i pierwsze sprzedaże, a potem postaw na to, co działa.","weeks":"6-8","steps":[{"id":"p3s1","title":"Opublikuj 20 kolejnych ofert","why":"Większość sklepów notuje regularną sprzedaż dopiero po 40–50 ofertach. Każda nowa oferta to kolejne drzwi do sklepu.","instructions":["Projekty, które zebrały wyświetlenia lub polubienia, przenieś na nowe produkty (kubki, bluzy, naklejki).","Dodaj 10 nowych projektów w tej samej niszy.","Zacznij od tagów, które najlepiej działały dotąd."],"est_minutes":300,"resources":[],"tools":[],"xp":60,"metric_to_track":"Aktywne oferty"},{"id":"p3s2","title":"Popraw oferty z wyświetleniami, ale bez sprzedaży","why":"Drobne zmiany głównego zdjęcia i tytułu potrafią podwoić liczbę kliknięć. Poprawa oferty jest szybsza niż tworzenie nowej.","instructions":["W statystykach Etsy znajdź oferty z wyświetleniami, ale bez polubień i sprzedaży.","Najpierw przetestuj nowe główne zdjęcie. To ono generuje najwięcej kliknięć.","Przepisz tytuł, używając bardziej konkretnej frazy.","Zmieniaj jedną rzecz naraz i oceniaj efekt po tygodniu."],"est_minutes":60,"resources":[],"tools":[{"name":"eRank","url":"https://erank.com","affiliate":false}],"xp":40,"metric_to_track":"Poprawione oferty"},{"id":"p3s3","title":"Pokaż projekty na Pintereście","why":"Pinterest działa jak wyszukiwarka pomysłów i prezentów. Piny przyprowadzają odwiedzających przez wiele miesięcy.","instructions":["Załóż darmowe konto firmowe na Pintereście.","Utwórz tablicę dla swojej niszy i przez tydzień przypinaj codziennie 3 mockupy różnych ofert.","W tytułach pinów używaj tych samych fraz co w tytułach na Etsy."],"est_minutes":60,"resources":[{"title":"Pinterest Business (ang.)","url":"https://business.pinterest.com"}],"tools":[],"xp":40,"metric_to_track":"Odwiedziny sklepu z Pinteresta"}]},{"id":"p4","title":"Skalowanie","goal":"Zamień bestsellery w system i osiągnij stały miesięczny zysk.","weeks":"9-12","steps":[{"id":"p4s1","title":"Zrób 5 wariantów każdego bestsellera","why":"Projekt, który raz się sprzedał, zwykle sprzeda się znowu w nowym kolorze, haśle lub na innym produkcie. Zwycięzcy to najtańszy wzrost.","instructions":["Posortuj oferty według sprzedaży i polubień z ostatnich 30 dni.","Dla 3 najlepszych stwórz po 5 wariantów: nowe kolory, nowe hasła, nowe typy produktów.","Opublikuj je z tytułami celującymi w nieco inne frazy."],"est_minutes":45,"resources":[],"tools":[],"xp":40,"metric_to_track":"Sprzedaż z wariantów"},{"id":"p4s2","title":"Przetestuj Etsy Ads tylko na sprawdzonych ofertach","why":"Reklamy wzmacniają to, co już działa. Na niesprawdzonych ofertach głównie przepalają pieniądze.","instructions":["Włącz Etsy Ads z małym dziennym budżetem (1–3 $).","Reklamuj tylko oferty, które już się sprzedały.","Po 2 tygodniach porównaj koszt reklamy na sprzedaż z zyskiem na sprzedaży i wyłącz reklamy, które przynoszą stratę."],"est_minutes":45,"resources":[],"tools":[],"xp":50,"metric_to_track":"Koszt reklamy na sprzedaż"},{"id":"p4s3","title":"Zaplanuj kalendarz sezonowy","why":"Święta napędzają większość sprzedaży w print on demand. Oferty potrzebują 6–8 tygodni, żeby zostać zauważone przed szczytem.","instructions":["Wypisz święta i wydarzenia ważne dla Twojej niszy w najbliższych 6 miesiącach.","Dodaj każde do kalendarza z 8-tygodniowym wyprzedzeniem jako przypomnienie „opublikuj projekty”.","Przygotuj już teraz 5 projektów na najbliższe wydarzenie."],"est_minutes":60,"resources":[],"tools":[],"xp":50,"metric_to_track":"Gotowe oferty sezonowe"}]}],"weekly_metrics":["listings","shop_visits","sales"],"earning_milestones":[{"label":"Miesiące 1–3","range":"0–200 $ / mies.","note":"Większość sklepów potrzebuje 30–50 ofert, zanim sprzedaż stanie się regularna."},{"label":"Miesiące 4–6","range":"100–500 $ / mies.","note":"Pojawiają się bestsellery. Przenoszenie ich na nowe produkty napędza wzrost."},{"label":"Miesiące 6–12","range":"300–1500 $ / mies.","note":"Typowe dla sklepów ze 100+ dopracowanymi ofertami i projektami sezonowymi."}]}$roadmap$),
  ('social-media-manager', 'en', $roadmap${"hustle_slug":"social-media-manager","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Offer & samples","goal":"Choose the businesses you'll serve, create sample content and define your packages.","weeks":"1-2","steps":[{"id":"p1s1","title":"Pick a type of business to serve","why":"Specializing (e.g. cafés, beauty salons, gyms) makes your pitch sharper and your content faster to create.","instructions":["List 5 local business types you like and understand.","Check 10 of their Instagram or Facebook profiles and note how active and professional they are.","Pick the type with the most neglected profiles. That's your opportunity."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Niche chosen"},{"id":"p1s2","title":"Create a sample content pack","why":"Showing a business what their feed could look like is far more convincing than describing your skills.","instructions":["Pick one real business from your niche as an example (don't publish anything for them).","Create a 2-week content plan and 9 post designs in Canva, including 2 short Reels ideas.","Write captions in the business's tone of voice."],"est_minutes":240,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Sample posts"},{"id":"p1s3","title":"Set up your tools","why":"Scheduling tools let you plan a month of posts in one sitting and manage several clients calmly.","instructions":["Learn Meta Business Suite for Facebook and Instagram scheduling.","Try a free plan of a scheduler like Buffer for other platforms.","Create a content calendar template in Notion or a spreadsheet."],"est_minutes":60,"resources":[{"title":"Meta Blueprint (free courses)","url":"https://www.facebook.com/business/learn"}],"tools":[{"name":"Meta Business Suite","url":"https://business.facebook.com","affiliate":false},{"name":"Buffer","url":"https://buffer.com","affiliate":false}],"xp":30,"metric_to_track":"Tools set up"},{"id":"p1s4","title":"Define your packages","why":"Clear monthly packages make it easy for business owners to say yes and easy for you to deliver.","instructions":["Create 2–3 packages (e.g. 8, 12 or 20 posts per month, with or without Reels).","Price them for your market; one client often pays $300–$800 per month.","List what's not included (ads budget, photo shoots) to avoid misunderstandings."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Packages defined"}]},{"id":"p2","title":"First client","goal":"Reach out to local businesses and sign your first monthly client.","weeks":"3-5","steps":[{"id":"p2s1","title":"Contact 30 businesses","why":"Most small businesses know they should post more but don't have time. A friendly, specific message opens the door.","instructions":["List 30 businesses in your niche with inactive or messy profiles.","Send a short message or email with 2 specific ideas for their profile and your sample pack.","Visit a few in person if they're local. It works surprisingly well."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Pitches sent"},{"id":"p2s2","title":"Run discovery calls with a mini audit","why":"A quick audit of their profile shows you understand their business and gives them a reason to hire you.","instructions":["Before each call, note 3 strengths and 3 quick wins for their profile.","Ask about their goals: more bookings, more foot traffic, more followers?","Recommend the package that fits and send it in writing the same day."],"est_minutes":120,"resources":[],"tools":[],"xp":40,"metric_to_track":"Calls booked"},{"id":"p2s3","title":"Onboard your first client","why":"A clear start (agreement, access, approval process) prevents most problems in client work.","instructions":["Sign a simple agreement: package, price, payment date, approval process, notice period.","Get access through Meta Business Suite roles, never by sharing passwords.","Collect brand assets and photos, then present the first month's calendar for approval."],"est_minutes":180,"resources":[],"tools":[],"xp":60,"metric_to_track":"Paying clients"},{"id":"p2s4","title":"Set up invoicing and taxes","why":"Monthly clients mean monthly invoices. Getting this right early keeps you professional and compliant.","instructions":["Choose how you'll invoice (e.g. Stripe invoices or a local invoicing tool).","Check how service income is taxed where you live.","Log every payment before your weekly check-in."],"est_minutes":30,"resources":[{"title":"Stripe Invoicing","url":"https://docs.stripe.com/invoicing"}],"tools":[],"xp":20,"metric_to_track":"Monthly recurring income"}]},{"id":"p3","title":"Deliver & prove","goal":"Build an efficient monthly workflow and show your client clear results.","weeks":"6-8","steps":[{"id":"p3s1","title":"Batch a month of content","why":"Batching a whole month in 1–2 sessions lets you serve more clients without working every day.","instructions":["Design all posts for the month using your templates.","Get client approval in one round.","Schedule everything and set a reminder to reply to comments."],"est_minutes":240,"resources":[],"tools":[{"name":"Meta Business Suite","url":"https://business.facebook.com","affiliate":false}],"xp":50,"metric_to_track":"Hours per client per month"},{"id":"p3s2","title":"Send a monthly results report","why":"Clients stay when they see progress. A one-page report makes your value visible.","instructions":["Track reach, followers, engagement and messages or bookings from social.","Compare with the previous month and explain what you'll do next.","Keep it to one page with 3 key numbers."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Reports sent"},{"id":"p3s3","title":"Collect a testimonial","why":"A quote from a real local business makes your next pitches much easier.","instructions":["Ask your client for 2–3 sentences about working with you.","Turn the results into a short before/after case study.","Add both to your portfolio."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Testimonials"}]},{"id":"p4","title":"Grow to 2–3 clients","goal":"Sign more clients, raise your prices and systemize your work.","weeks":"9-12","steps":[{"id":"p4s1","title":"Sign your second and third clients","why":"With 2–4 clients, social media management becomes a real monthly income.","instructions":["Pitch 30 new businesses using your case study.","Ask your current client for one referral.","Onboard each new client with the same process."],"est_minutes":180,"resources":[],"tools":[],"xp":60,"metric_to_track":"Paying clients"},{"id":"p4s2","title":"Raise prices and add an upsell","why":"With results and testimonials, you can charge more, and add services like short videos or ads management.","instructions":["Raise prices for new clients by 20–30%.","Offer one add-on (Reels production, ads management, monthly photo session).","Present it in your next monthly report."],"est_minutes":45,"resources":[],"tools":[],"xp":40,"metric_to_track":"Average income per client"},{"id":"p4s3","title":"Systemize your workflow","why":"Templates and checklists let you add clients without adding stress.","instructions":["Create reusable templates for posts, captions, reports and onboarding.","Write a monthly checklist per client.","Block fixed days in your calendar for each client."],"est_minutes":90,"resources":[],"tools":[{"name":"Notion","url":"https://www.notion.com","affiliate":false}],"xp":40,"metric_to_track":"Hours per client per month"}]}],"weekly_metrics":["pitches_sent","calls_booked","clients"],"earning_milestones":[{"label":"Weeks 3–8","range":"$300–$800 / month","note":"Your first monthly client."},{"label":"Months 3–6","range":"$600–$2,000 / month","note":"Two or three clients with clear results."},{"label":"Months 6–12","range":"$1,000–$3,000 / month","note":"Realistic with 2–4 clients and higher prices."}]}$roadmap$),
  ('social-media-manager', 'pl', $roadmap${"hustle_slug":"social-media-manager","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Oferta i próbki","goal":"Wybierz firmy, którym pomożesz, przygotuj próbne treści i określ pakiety.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz typ firm, którym pomożesz","why":"Specjalizacja (np. kawiarnie, salony beauty, siłownie) wyostrza ofertę i przyspiesza tworzenie treści.","instructions":["Wypisz 5 typów lokalnych firm, które lubisz i rozumiesz.","Sprawdź 10 ich profili na Instagramie lub Facebooku i zanotuj, jak są aktywne i profesjonalne.","Wybierz typ z najbardziej zaniedbanymi profilami. To Twoja szansa."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Wybrana nisza"},{"id":"p1s2","title":"Przygotuj próbny pakiet treści","why":"Pokazanie firmie, jak mógłby wyglądać jej profil, przekonuje dużo bardziej niż opis umiejętności.","instructions":["Wybierz jedną prawdziwą firmę z niszy jako przykład (niczego za nią nie publikuj).","Stwórz 2-tygodniowy plan treści i 9 projektów postów w Canvie, w tym 2 pomysły na Reels.","Napisz opisy w stylu komunikacji tej firmy."],"est_minutes":240,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false}],"xp":50,"metric_to_track":"Próbne posty"},{"id":"p1s3","title":"Przygotuj narzędzia","why":"Narzędzia do planowania pozwalają przygotować miesiąc postów za jednym razem i spokojnie obsługiwać kilku klientów.","instructions":["Poznaj Meta Business Suite do planowania postów na Facebooku i Instagramie.","Wypróbuj darmowy plan narzędzia typu Buffer dla innych platform.","Przygotuj szablon kalendarza treści w Notion lub arkuszu."],"est_minutes":60,"resources":[{"title":"Meta Blueprint (darmowe kursy)","url":"https://www.facebook.com/business/learn"}],"tools":[{"name":"Meta Business Suite","url":"https://business.facebook.com","affiliate":false},{"name":"Buffer","url":"https://buffer.com","affiliate":false}],"xp":30,"metric_to_track":"Gotowe narzędzia"},{"id":"p1s4","title":"Określ pakiety","why":"Jasne pakiety miesięczne ułatwiają właścicielom firm decyzję, a Tobie realizację.","instructions":["Stwórz 2–3 pakiety (np. 8, 12 lub 20 postów miesięcznie, z Reels lub bez).","Wyceń je dla swojego rynku; jeden klient płaci często 300–800 $ miesięcznie.","Wypisz, czego pakiet nie obejmuje (budżet reklamowy, sesje zdjęciowe), by uniknąć nieporozumień."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Określone pakiety"}]},{"id":"p2","title":"Pierwszy klient","goal":"Skontaktuj się z lokalnymi firmami i podpisz umowę z pierwszym stałym klientem.","weeks":"3-5","steps":[{"id":"p2s1","title":"Skontaktuj się z 30 firmami","why":"Większość małych firm wie, że powinna publikować więcej, ale nie ma czasu. Przyjazna, konkretna wiadomość otwiera drzwi.","instructions":["Wypisz 30 firm z niszy z nieaktywnymi lub chaotycznymi profilami.","Wyślij krótką wiadomość lub e-mail z 2 konkretnymi pomysłami na ich profil i próbnym pakietem.","Odwiedź kilka osobiście, jeśli są blisko. To działa zaskakująco dobrze."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Wysłane propozycje"},{"id":"p2s2","title":"Przeprowadź rozmowy z mini audytem","why":"Szybki audyt profilu pokazuje, że rozumiesz ich biznes, i daje powód, by Cię zatrudnić.","instructions":["Przed każdą rozmową zanotuj 3 mocne strony i 3 szybkie usprawnienia profilu.","Zapytaj o cele: więcej rezerwacji, więcej klientów w lokalu, więcej obserwujących?","Poleć pasujący pakiet i wyślij ofertę na piśmie tego samego dnia."],"est_minutes":120,"resources":[],"tools":[],"xp":40,"metric_to_track":"Umówione rozmowy"},{"id":"p2s3","title":"Wdróż pierwszego klienta","why":"Jasny start (umowa, dostępy, proces akceptacji) zapobiega większości problemów we współpracy.","instructions":["Podpisz prostą umowę: pakiet, cena, termin płatności, akceptacja treści, okres wypowiedzenia.","Uzyskaj dostęp przez role w Meta Business Suite, nigdy przez udostępnianie haseł.","Zbierz materiały marki i zdjęcia, a potem przedstaw kalendarz pierwszego miesiąca do akceptacji."],"est_minutes":180,"resources":[],"tools":[],"xp":60,"metric_to_track":"Płacący klienci"},{"id":"p2s4","title":"Ustaw rachunki i podatki","why":"Stali klienci to comiesięczne rachunki. Wczesne uporządkowanie tego zapewnia profesjonalizm i zgodność z przepisami.","instructions":["Wybierz sposób wystawiania rachunków (np. faktury w Stripe lub lokalne narzędzie).","Sprawdź, jak rozlicza się dochody z usług w Twoim kraju (w Polsce np. działalność nierejestrowana).","Zapisuj każdą wpłatę przed cotygodniowym podsumowaniem."],"est_minutes":30,"resources":[{"title":"Faktury w Stripe (ang.)","url":"https://docs.stripe.com/invoicing"}],"tools":[],"xp":20,"metric_to_track":"Stały dochód miesięczny"}]},{"id":"p3","title":"Realizacja i efekty","goal":"Zbuduj sprawny miesięczny proces i pokaż klientowi wyraźne efekty.","weeks":"6-8","steps":[{"id":"p3s1","title":"Przygotuj hurtowo miesiąc treści","why":"Przygotowanie całego miesiąca w 1–2 sesjach pozwala obsłużyć więcej klientów bez codziennej pracy.","instructions":["Zaprojektuj wszystkie posty na miesiąc, korzystając z szablonów.","Uzyskaj akceptację klienta w jednej rundzie.","Zaplanuj wszystko i ustaw przypomnienie o odpowiadaniu na komentarze."],"est_minutes":240,"resources":[],"tools":[{"name":"Meta Business Suite","url":"https://business.facebook.com","affiliate":false}],"xp":50,"metric_to_track":"Godziny na klienta miesięcznie"},{"id":"p3s2","title":"Wysyłaj miesięczny raport wyników","why":"Klienci zostają, gdy widzą postępy. Jednostronicowy raport pokazuje Twoją wartość.","instructions":["Śledź zasięg, obserwujących, zaangażowanie i wiadomości lub rezerwacje z social mediów.","Porównaj z poprzednim miesiącem i wyjaśnij, co zrobisz dalej.","Zmieść raport na jednej stronie z 3 kluczowymi liczbami."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Wysłane raporty"},{"id":"p3s3","title":"Zbierz rekomendację","why":"Cytat od prawdziwej lokalnej firmy bardzo ułatwia kolejne propozycje.","instructions":["Poproś klienta o 2–3 zdania o współpracy z Tobą.","Zamień wyniki w krótkie studium przypadku przed/po.","Dodaj oba do portfolio."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Rekomendacje"}]},{"id":"p4","title":"Rozwój do 2–3 klientów","goal":"Pozyskaj kolejnych klientów, podnieś ceny i usystematyzuj pracę.","weeks":"9-12","steps":[{"id":"p4s1","title":"Pozyskaj drugiego i trzeciego klienta","why":"Przy 2–4 klientach prowadzenie social mediów staje się realnym miesięcznym dochodem.","instructions":["Wyślij propozycje do 30 nowych firm, pokazując studium przypadku.","Poproś obecnego klienta o jedno polecenie.","Wdrażaj każdego nowego klienta tym samym procesem."],"est_minutes":180,"resources":[],"tools":[],"xp":60,"metric_to_track":"Płacący klienci"},{"id":"p4s2","title":"Podnieś ceny i dodaj usługę dodatkową","why":"Mając wyniki i rekomendacje, możesz liczyć więcej i dodać usługi, np. krótkie filmy lub obsługę reklam.","instructions":["Podnieś ceny dla nowych klientów o 20–30%.","Zaproponuj jeden dodatek (produkcja Reels, obsługa reklam, comiesięczna sesja zdjęciowa).","Przedstaw go w najbliższym raporcie miesięcznym."],"est_minutes":45,"resources":[],"tools":[],"xp":40,"metric_to_track":"Średni dochód na klienta"},{"id":"p4s3","title":"Usystematyzuj proces pracy","why":"Szablony i checklisty pozwalają dodawać klientów bez dodawania stresu.","instructions":["Przygotuj szablony postów, opisów, raportów i wdrożenia.","Napisz comiesięczną checklistę dla każdego klienta.","Zarezerwuj w kalendarzu stałe dni na każdego klienta."],"est_minutes":90,"resources":[],"tools":[{"name":"Notion","url":"https://www.notion.com","affiliate":false}],"xp":40,"metric_to_track":"Godziny na klienta miesięcznie"}]}],"weekly_metrics":["pitches_sent","calls_booked","clients"],"earning_milestones":[{"label":"Tygodnie 3–8","range":"300–800 $ / mies.","note":"Pierwszy stały klient."},{"label":"Miesiące 3–6","range":"600–2000 $ / mies.","note":"Dwóch lub trzech klientów z wyraźnymi efektami."},{"label":"Miesiące 6–12","range":"1000–3000 $ / mies.","note":"Realne przy 2–4 klientach i wyższych cenach."}]}$roadmap$),
  ('stock-media', 'en', $roadmap${"hustle_slug":"stock-media","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Accounts & first shoot","goal":"Learn what buyers need, open contributor accounts and shoot your first 30 photos.","weeks":"1-2","steps":[{"id":"p1s1","title":"Study what sells","why":"Stock buyers are businesses. They need clear, useful images of everyday concepts (work, food, health, money, home), not artistic landscapes.","instructions":["Browse the most popular results on Adobe Stock and Shutterstock for topics near you.","Note common concepts, compositions and space left for text.","List 20 shots you can take with what you have around you."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Shot list of 20"},{"id":"p1s2","title":"Open contributor accounts","why":"Uploading to several agencies multiplies the chances each file sells, for almost no extra work.","instructions":["Sign up as a contributor on Adobe Stock and Shutterstock.","Complete identity and tax information so payouts work.","Read each agency's submission guidelines."],"est_minutes":60,"resources":[{"title":"Adobe Stock contributor help","url":"https://helpx.adobe.com/stock/contributor.html"}],"tools":[{"name":"Adobe Stock Contributor","url":"https://contributor.stock.adobe.com","affiliate":false},{"name":"Shutterstock Contributor","url":"https://submit.shutterstock.com","affiliate":false}],"xp":30,"metric_to_track":"Accounts approved"},{"id":"p1s3","title":"Learn the legal rules","why":"Most rejections come from logos, trademarks or people without releases. Knowing the rules saves hours of wasted uploads.","instructions":["Avoid logos, brand names, artwork and recognizable buildings that need permission.","Get a signed model release for any recognizable person.","If you use AI tools, follow each agency's rules for labeling or submitting AI content."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Rules checklist ready"},{"id":"p1s4","title":"Shoot your first 30 photos","why":"A modern phone is enough to start. Good light, sharp focus and a clear subject matter more than the camera.","instructions":["Shoot in soft daylight and keep the horizon straight.","Take each subject in horizontal and vertical versions, with and without space for text.","Check sharpness at 100% zoom before keeping a photo."],"est_minutes":240,"resources":[],"tools":[],"xp":50,"metric_to_track":"Photos shot"}]},{"id":"p2","title":"First uploads","goal":"Edit, keyword and upload your first 50 files.","weeks":"3-5","steps":[{"id":"p2s1","title":"Edit and add keywords","why":"Buyers only find what's keyworded well. A precise title and relevant keywords are half of every sale.","instructions":["Do light edits: exposure, straightening, cropping. Avoid heavy filters.","Write a descriptive title that says what, who, where and the concept.","Add relevant keywords, most important first. Don't add unrelated words."],"est_minutes":120,"resources":[],"tools":[],"xp":40,"metric_to_track":"Files ready"},{"id":"p2s2","title":"Upload your first 50 files","why":"Stock income grows with portfolio size. The sooner files are live, the sooner they can start selling.","instructions":["Upload the same files to both agencies.","Pick categories carefully and attach releases where needed.","Submit and note the date so you can track review times."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Files uploaded"},{"id":"p2s3","title":"Learn from rejections","why":"Rejections are free feedback. Fixing the common reason can double your acceptance rate.","instructions":["Group rejections by reason (focus, noise, trademark, similar content).","Fix the most common issue in your next shoot.","Resubmit only files where the problem is fixable."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Acceptance rate"},{"id":"p2s4","title":"Track earnings and taxes","why":"Stock earnings come in small amounts from several agencies. A simple log shows your real progress.","instructions":["Log files online, downloads and earnings per agency each week.","Note your earnings per file per month.","Check how licensing income is taxed where you live."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Earnings per file"}]},{"id":"p3","title":"Series & video","goal":"Shoot themed series, add video clips and learn what sells.","weeks":"6-8","steps":[{"id":"p3s1","title":"Shoot 3 themed series","why":"Buyers often need several related images. Series of 20–40 shots on one theme sell better than random single photos.","instructions":["Pick 3 concepts from your research (e.g. ‘working from home’, ‘healthy breakfast’, ‘budgeting’).","Shoot each from many angles: close-ups, wide shots, details, flat lays.","Keyword and upload each series."],"est_minutes":300,"resources":[],"tools":[],"xp":60,"metric_to_track":"Files uploaded"},{"id":"p3s2","title":"Add 20 short video clips","why":"Video clips usually earn more per download than photos and face less competition.","instructions":["Film 10–20 second clips on a tripod, with steady, slow movement.","Shoot in the highest quality your phone supports.","Trim the start and end, then keyword and upload."],"est_minutes":240,"resources":[],"tools":[],"xp":50,"metric_to_track":"Clips uploaded"},{"id":"p3s3","title":"Find what sells and shoot more of it","why":"Your first downloads reveal what buyers want from you specifically.","instructions":["Check which files got downloads and why (subject, style, keywords).","Plan a new series around your top file.","Improve keywords on similar files that haven't sold."],"est_minutes":45,"resources":[],"tools":[],"xp":40,"metric_to_track":"Downloads"}]},{"id":"p4","title":"Build volume","goal":"Grow your portfolio steadily and add another agency.","weeks":"9-12","steps":[{"id":"p4s1","title":"Grow to 300 files","why":"Stock is a volume game. Portfolios of several hundred strong files are where monthly income becomes noticeable.","instructions":["Set a weekly upload target (e.g. 40 files).","Batch shooting on one day and keywording on another.","Keep quality high. Rejections waste time."],"est_minutes":600,"resources":[],"tools":[],"xp":60,"metric_to_track":"Files online"},{"id":"p4s2","title":"Plan seasonal shoots","why":"Buyers look for seasonal images weeks before holidays. Uploading early catches that demand.","instructions":["List holidays and seasons for the next 4 months.","Plan one shoot for each, 6–8 weeks before it.","Include diverse, inclusive scenes where possible."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Seasonal shoots planned"},{"id":"p4s3","title":"Add a third agency","why":"Pond5 is strong for video. Another agency means more buyers for files you already have.","instructions":["Create a contributor account on Pond5.","Upload your best clips and photos first.","Compare earnings per agency after one month."],"est_minutes":90,"resources":[],"tools":[{"name":"Pond5","url":"https://www.pond5.com","affiliate":false}],"xp":40,"metric_to_track":"Earnings per agency"}]}],"weekly_metrics":["files_uploaded","downloads"],"earning_milestones":[{"label":"Months 1–3","range":"$0–$50 / month","note":"First downloads trickle in as your portfolio grows."},{"label":"Months 4–8","range":"$30–$200 / month","note":"Several hundred files and a few best sellers."},{"label":"Months 9–18","range":"$100–$800 / month","note":"Typical for portfolios of 500+ strong files, including video."}]}$roadmap$),
  ('stock-media', 'pl', $roadmap${"hustle_slug":"stock-media","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Konta i pierwsza sesja","goal":"Dowiedz się, czego potrzebują kupujący, załóż konta współtwórcy i zrób pierwsze 30 zdjęć.","weeks":"1-2","steps":[{"id":"p1s1","title":"Sprawdź, co się sprzedaje","why":"Kupujący stock to firmy. Potrzebują czytelnych, użytecznych obrazów codziennych pojęć (praca, jedzenie, zdrowie, pieniądze, dom), a nie artystycznych pejzaży.","instructions":["Przejrzyj najpopularniejsze wyniki w Adobe Stock i Shutterstock dla tematów z Twojego otoczenia.","Zanotuj popularne motywy, kompozycje i miejsce zostawione na tekst.","Wypisz 20 ujęć, które zrobisz przy użyciu tego, co masz wokół siebie."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Lista 20 ujęć"},{"id":"p1s2","title":"Załóż konta współtwórcy","why":"Wgrywanie do kilku agencji zwielokrotnia szansę sprzedaży każdego pliku niemal bez dodatkowej pracy.","instructions":["Zarejestruj się jako współtwórca w Adobe Stock i Shutterstock.","Uzupełnij dane tożsamości i podatkowe, by wypłaty działały.","Przeczytaj zasady przesyłania w każdej agencji."],"est_minutes":60,"resources":[{"title":"Pomoc dla współtwórców Adobe Stock (ang.)","url":"https://helpx.adobe.com/stock/contributor.html"}],"tools":[{"name":"Adobe Stock Contributor","url":"https://contributor.stock.adobe.com","affiliate":false},{"name":"Shutterstock Contributor","url":"https://submit.shutterstock.com","affiliate":false}],"xp":30,"metric_to_track":"Zatwierdzone konta"},{"id":"p1s3","title":"Poznaj zasady prawne","why":"Większość odrzuceń wynika z logotypów, znaków towarowych lub osób bez zgody. Znajomość zasad oszczędza godziny zmarnowanych uploadów.","instructions":["Unikaj logotypów, nazw marek, dzieł sztuki i rozpoznawalnych budynków wymagających zgody.","Uzyskaj podpisaną zgodę modela dla każdej rozpoznawalnej osoby.","Jeśli używasz narzędzi AI, stosuj się do zasad oznaczania lub przesyłania treści AI w każdej agencji."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Gotowa lista zasad"},{"id":"p1s4","title":"Zrób pierwsze 30 zdjęć","why":"Na start wystarczy nowoczesny telefon. Dobre światło, ostrość i wyraźny motyw są ważniejsze niż aparat.","instructions":["Fotografuj w miękkim świetle dziennym i trzymaj prosty horyzont.","Każdy motyw zrób w poziomie i pionie, z miejscem na tekst i bez.","Zanim zostawisz zdjęcie, sprawdź ostrość w powiększeniu 100%."],"est_minutes":240,"resources":[],"tools":[],"xp":50,"metric_to_track":"Zrobione zdjęcia"}]},{"id":"p2","title":"Pierwsze uploady","goal":"Obrób, opisz słowami kluczowymi i prześlij pierwsze 50 plików.","weeks":"3-5","steps":[{"id":"p2s1","title":"Obróbka i słowa kluczowe","why":"Kupujący znajdą tylko to, co jest dobrze opisane. Precyzyjny tytuł i trafne słowa kluczowe to połowa każdej sprzedaży.","instructions":["Zrób lekką obróbkę: ekspozycja, prostowanie, kadrowanie. Unikaj mocnych filtrów.","Napisz opisowy tytuł: co, kto, gdzie i jakie pojęcie.","Dodaj trafne słowa kluczowe, najważniejsze na początku. Nie dodawaj niezwiązanych słów."],"est_minutes":120,"resources":[],"tools":[],"xp":40,"metric_to_track":"Gotowe pliki"},{"id":"p2s2","title":"Prześlij pierwsze 50 plików","why":"Dochód ze stocku rośnie wraz z portfolio. Im szybciej pliki są online, tym szybciej mogą się sprzedawać.","instructions":["Prześlij te same pliki do obu agencji.","Starannie wybieraj kategorie i dołączaj zgody, gdzie trzeba.","Wyślij do weryfikacji i zanotuj datę, by śledzić czas oceny."],"est_minutes":180,"resources":[],"tools":[],"xp":50,"metric_to_track":"Przesłane pliki"},{"id":"p2s3","title":"Ucz się na odrzuceniach","why":"Odrzucenia to darmowa informacja zwrotna. Naprawa najczęstszej przyczyny może podwoić odsetek akceptacji.","instructions":["Pogrupuj odrzucenia według przyczyny (ostrość, szum, znak towarowy, podobne treści).","W kolejnej sesji wyeliminuj najczęstszy problem.","Wysyłaj ponownie tylko pliki, które da się poprawić."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Odsetek akceptacji"},{"id":"p2s4","title":"Śledź zarobki i podatki","why":"Zarobki ze stocku to małe kwoty z kilku agencji. Prosty zapis pokazuje realne postępy.","instructions":["Co tydzień zapisuj pliki online, pobrania i zarobki w każdej agencji.","Notuj miesięczny zarobek na plik.","Sprawdź, jak rozlicza się dochody z licencji w Twoim kraju."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Zarobek na plik"}]},{"id":"p3","title":"Serie i wideo","goal":"Rób serie tematyczne, dodaj klipy wideo i sprawdź, co się sprzedaje.","weeks":"6-8","steps":[{"id":"p3s1","title":"Zrób 3 serie tematyczne","why":"Kupujący często potrzebują kilku powiązanych obrazów. Serie po 20–40 ujęć na jeden temat sprzedają się lepiej niż przypadkowe zdjęcia.","instructions":["Wybierz 3 pojęcia z badania (np. „praca z domu”, „zdrowe śniadanie”, „budżet domowy”).","Sfotografuj każde z wielu ujęć: zbliżenia, plany ogólne, detale, zdjęcia z góry.","Opisz i prześlij każdą serię."],"est_minutes":300,"resources":[],"tools":[],"xp":60,"metric_to_track":"Przesłane pliki"},{"id":"p3s2","title":"Dodaj 20 krótkich klipów wideo","why":"Klipy wideo zwykle zarabiają więcej na pobraniu niż zdjęcia i mają mniejszą konkurencję.","instructions":["Nagrywaj 10–20-sekundowe klipy ze statywu, ze stabilnym, powolnym ruchem.","Nagrywaj w najwyższej jakości, jaką obsługuje telefon.","Przytnij początek i koniec, opisz i prześlij."],"est_minutes":240,"resources":[],"tools":[],"xp":50,"metric_to_track":"Przesłane klipy"},{"id":"p3s3","title":"Znajdź to, co się sprzedaje, i rób więcej","why":"Pierwsze pobrania pokazują, czego kupujący chcą właśnie od Ciebie.","instructions":["Sprawdź, które pliki zostały pobrane i dlaczego (motyw, styl, słowa kluczowe).","Zaplanuj nową serię wokół najlepszego pliku.","Popraw słowa kluczowe w podobnych plikach, które się nie sprzedały."],"est_minutes":45,"resources":[],"tools":[],"xp":40,"metric_to_track":"Pobrania"}]},{"id":"p4","title":"Budowa skali","goal":"Regularnie powiększaj portfolio i dodaj kolejną agencję.","weeks":"9-12","steps":[{"id":"p4s1","title":"Dojdź do 300 plików","why":"Stock to gra skali. Przy portfolio z kilkuset dobrymi plikami miesięczny dochód staje się zauważalny.","instructions":["Ustal tygodniowy cel uploadów (np. 40 plików).","Grupuj zdjęcia w jeden dzień, a opisywanie w inny.","Dbaj o jakość. Odrzucenia marnują czas."],"est_minutes":600,"resources":[],"tools":[],"xp":60,"metric_to_track":"Pliki online"},{"id":"p4s2","title":"Zaplanuj sesje sezonowe","why":"Kupujący szukają zdjęć sezonowych na tygodnie przed świętami. Wczesny upload łapie ten popyt.","instructions":["Wypisz święta i sezony na najbliższe 4 miesiące.","Zaplanuj jedną sesję na każde, 6–8 tygodni wcześniej.","Tam, gdzie to możliwe, uwzględnij różnorodne, inkluzywne sceny."],"est_minutes":60,"resources":[],"tools":[],"xp":40,"metric_to_track":"Zaplanowane sesje sezonowe"},{"id":"p4s3","title":"Dodaj trzecią agencję","why":"Pond5 jest mocny w wideo. Kolejna agencja to więcej kupujących dla plików, które już masz.","instructions":["Załóż konto współtwórcy w Pond5.","Najpierw prześlij najlepsze klipy i zdjęcia.","Po miesiącu porównaj zarobki w każdej agencji."],"est_minutes":90,"resources":[],"tools":[{"name":"Pond5","url":"https://www.pond5.com","affiliate":false}],"xp":40,"metric_to_track":"Zarobki w agencji"}]}],"weekly_metrics":["files_uploaded","downloads"],"earning_milestones":[{"label":"Miesiące 1–3","range":"0–50 $ / mies.","note":"Pierwsze pobrania pojawiają się w miarę wzrostu portfolio."},{"label":"Miesiące 4–8","range":"30–200 $ / mies.","note":"Kilkaset plików i kilka bestsellerów."},{"label":"Miesiące 9–18","range":"100–800 $ / mies.","note":"Typowe dla portfolio z 500+ dobrymi plikami, także wideo."}]}$roadmap$),
  ('ugc-creator', 'en', $roadmap${"hustle_slug":"ugc-creator","locale":"en","total_weeks":12,"phases":[{"id":"p1","title":"Setup & samples","goal":"Choose your product categories, set up simple gear and film 3 sample videos.","weeks":"1-2","steps":[{"id":"p1s1","title":"Pick 2–3 product categories","why":"Brands hire creators who look like their customers. Focusing on products you actually use makes your videos believable.","instructions":["List the products you use every day (skincare, kitchen, pets, fitness, tech, home).","Pick 2–3 categories where you'd naturally be the customer.","Save 20 UGC-style ads in those categories from TikTok or Instagram for inspiration."],"est_minutes":30,"resources":[],"tools":[],"xp":30,"metric_to_track":"Categories chosen"},{"id":"p1s2","title":"Set up your filming corner","why":"You don't need expensive gear. Good light and clear sound matter more than the camera.","instructions":["Film near a window with soft daylight, or add an affordable ring or panel light.","Use a phone tripod and, if possible, a small clip-on microphone.","Test-record 30 seconds and check sound and light on another screen."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Setup ready"},{"id":"p1s3","title":"Film 3 sample videos","why":"Brands judge you by your samples. Three polished videos with products you own are your entry ticket.","instructions":["Film 3 formats: a testimonial, an unboxing or first impression, and a problem → solution demo.","Start each with a strong hook in the first 2 seconds.","Keep them 15–45 seconds, vertical, with captions.","Make it clear these are samples, not paid ads."],"est_minutes":240,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false}],"xp":50,"metric_to_track":"Sample videos"},{"id":"p1s4","title":"Build a simple portfolio page","why":"One link with your videos, categories and contact makes every pitch easier to say yes to.","instructions":["Create a one-page portfolio in Canva or Notion.","Add your 3 videos, a short intro, your categories and your email.","Test the link on a phone."],"est_minutes":90,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false},{"name":"Notion","url":"https://www.notion.com","affiliate":false}],"xp":40,"metric_to_track":"Portfolio live"}]},{"id":"p2","title":"First paid videos","goal":"Set your rates, join UGC platforms and pitch brands directly.","weeks":"3-5","steps":[{"id":"p2s1","title":"Set your rates and usage terms","why":"UGC is priced per video plus how long and where the brand can use it. Clear terms prevent awkward talks later.","instructions":["Set a starting price per video (beginners often charge $50–$150).","Decide what's included: number of hooks, revisions, raw footage.","Add a separate fee for paid-ads usage beyond organic posting."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Rate card ready"},{"id":"p2s2","title":"Join 2 UGC platforms","why":"UGC marketplaces connect you with brands already looking for creators, which is great for first jobs and reviews.","instructions":["Create profiles on 2 platforms such as Collabstr, Billo or JoinBrands.","Upload your 3 sample videos and fill in your categories.","Apply to 5 matching campaigns."],"est_minutes":60,"resources":[],"tools":[{"name":"Collabstr","url":"https://collabstr.com","affiliate":false},{"name":"Billo","url":"https://billo.app","affiliate":false},{"name":"JoinBrands","url":"https://joinbrands.com","affiliate":false}],"xp":40,"metric_to_track":"Applications sent"},{"id":"p2s3","title":"Pitch 15 brands directly","why":"Small and growing brands need content constantly and often pay better than marketplaces.","instructions":["Find 15 brands running ads in your categories (check Meta Ad Library or TikTok).","Find a marketing contact via their website or LinkedIn.","Send a short email with one idea for their product and your portfolio link.","Follow up once after 5 days."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Pitches sent"},{"id":"p2s4","title":"Track income and taxes","why":"Payments come from many brands and platforms. A simple log keeps you organized and ready for taxes.","instructions":["Log each job: brand, videos, price, paid or unpaid, date.","Update it before each weekly check-in.","Check how creator income is taxed where you live."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Unpaid invoices"}]},{"id":"p3","title":"Deliver & grow","goal":"Deliver paid work professionally and grow your portfolio with new formats.","weeks":"6-8","steps":[{"id":"p3s1","title":"Deliver your first paid job like a pro","why":"Brands that are happy come back and refer you. Professional delivery is how one client becomes five.","instructions":["Agree on brief, deadline, price and usage rights in writing before filming.","Deliver 2–3 hook variations so the brand can test them in ads.","Send files in an organized folder with clear names, on time."],"est_minutes":180,"resources":[],"tools":[],"xp":60,"metric_to_track":"Videos delivered"},{"id":"p3s2","title":"Ask for a testimonial and results","why":"A quote or ad result from a real brand is the strongest proof in your next pitch.","instructions":["Ask the brand for a one-sentence testimonial.","Ask if they can share how the video performed.","Add it to your portfolio (with permission)."],"est_minutes":30,"resources":[],"tools":[],"xp":30,"metric_to_track":"Testimonials"},{"id":"p3s3","title":"Add 3 new formats to your portfolio","why":"Showing range (voice-over, tutorial, ‘3 reasons why’) helps you win more types of briefs.","instructions":["Film one voice-over video, one tutorial and one ‘3 reasons’ video.","Use products from your chosen categories.","Update your portfolio and platform profiles."],"est_minutes":180,"resources":[],"tools":[],"xp":40,"metric_to_track":"Portfolio videos"}]},{"id":"p4","title":"Steady clients","goal":"Turn one-off jobs into monthly packages and raise your rates.","weeks":"9-12","steps":[{"id":"p4s1","title":"Offer monthly packages","why":"Brands running ads need fresh videos every month. A package gives them a steady supply and you steady income.","instructions":["Create a package, e.g. 4 videos per month at a small discount.","Offer it to every brand you've worked with.","Put the terms in a simple written agreement."],"est_minutes":60,"resources":[],"tools":[],"xp":50,"metric_to_track":"Monthly clients"},{"id":"p4s2","title":"Raise your rates","why":"With paid work and testimonials in your portfolio, you can charge more for the same video.","instructions":["Raise your base rate by 25–50% for new clients.","Charge separately for ad usage, extra hooks and rush delivery.","Update your rate card."],"est_minutes":30,"resources":[],"tools":[],"xp":40,"metric_to_track":"Average price per video"},{"id":"p4s3","title":"Build a weekly pitching routine","why":"Clients come and go. Five pitches a week keeps your pipeline full even when you're busy.","instructions":["Block 30 minutes twice a week for pitching.","Keep a simple list of brands, dates contacted and replies.","Pitch new brands with your best result from a past client."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Pitches sent"}]}],"weekly_metrics":["pitches_sent","clients","videos_delivered"],"earning_milestones":[{"label":"Weeks 3–8","range":"$50–$300","note":"First paid videos usually bring $50–$150 each."},{"label":"Months 3–6","range":"$300–$1,500 / month","note":"A few repeat brands plus platform jobs."},{"label":"Months 6–12","range":"$500–$3,000 / month","note":"Typical for creators with monthly packages and higher rates."}]}$roadmap$),
  ('ugc-creator', 'pl', $roadmap${"hustle_slug":"ugc-creator","locale":"pl","total_weeks":12,"phases":[{"id":"p1","title":"Przygotowanie i próbki","goal":"Wybierz kategorie produktów, przygotuj prosty sprzęt i nagraj 3 filmy próbne.","weeks":"1-2","steps":[{"id":"p1s1","title":"Wybierz 2–3 kategorie produktów","why":"Marki zatrudniają twórców, którzy wyglądają jak ich klienci. Skupienie na produktach, których naprawdę używasz, czyni filmy wiarygodnymi.","instructions":["Wypisz produkty, których używasz na co dzień (pielęgnacja, kuchnia, zwierzęta, fitness, technologia, dom).","Wybierz 2–3 kategorie, w których naturalnie jesteś klientem.","Zapisz 20 reklam w stylu UGC z tych kategorii z TikToka lub Instagrama jako inspirację."],"est_minutes":30,"resources":[],"tools":[],"xp":30,"metric_to_track":"Wybrane kategorie"},{"id":"p1s2","title":"Przygotuj miejsce do nagrań","why":"Nie potrzebujesz drogiego sprzętu. Dobre światło i czysty dźwięk są ważniejsze niż kamera.","instructions":["Nagrywaj przy oknie w miękkim świetle dziennym albo dodaj niedrogą lampę pierścieniową lub panel.","Użyj statywu do telefonu i, jeśli to możliwe, małego mikrofonu krawatowego.","Nagraj 30 sekund próbnie i sprawdź dźwięk oraz światło na innym ekranie."],"est_minutes":60,"resources":[],"tools":[],"xp":30,"metric_to_track":"Gotowe stanowisko"},{"id":"p1s3","title":"Nagraj 3 filmy próbne","why":"Marki oceniają Cię po próbkach. Trzy dopracowane filmy z produktami, które masz, to Twój bilet wstępu.","instructions":["Nagraj 3 formaty: rekomendacja, unboxing lub pierwsze wrażenie, demo problem → rozwiązanie.","Każdy zacznij mocnym haczykiem w pierwszych 2 sekundach.","Niech trwają 15–45 sekund, w pionie, z napisami.","Zaznacz jasno, że to próbki, a nie płatne reklamy."],"est_minutes":240,"resources":[],"tools":[{"name":"CapCut","url":"https://www.capcut.com","affiliate":false}],"xp":50,"metric_to_track":"Filmy próbne"},{"id":"p1s4","title":"Zbuduj prostą stronę portfolio","why":"Jeden link z filmami, kategoriami i kontaktem sprawia, że łatwiej odpowiedzieć „tak” na każdą propozycję.","instructions":["Stwórz jednostronicowe portfolio w Canvie lub Notion.","Dodaj 3 filmy, krótkie przedstawienie, kategorie i e-mail.","Sprawdź link na telefonie."],"est_minutes":90,"resources":[],"tools":[{"name":"Canva","url":"https://www.canva.com","affiliate":false},{"name":"Notion","url":"https://www.notion.com","affiliate":false}],"xp":40,"metric_to_track":"Portfolio online"}]},{"id":"p2","title":"Pierwsze płatne filmy","goal":"Ustal stawki, dołącz do platform UGC i kontaktuj się bezpośrednio z markami.","weeks":"3-5","steps":[{"id":"p2s1","title":"Ustal stawki i warunki wykorzystania","why":"UGC wycenia się za film oraz za to, jak długo i gdzie marka może go używać. Jasne warunki zapobiegają niezręcznym rozmowom.","instructions":["Ustal cenę startową za film (początkujący często biorą 50–150 $).","Określ, co obejmuje: liczba haczyków, poprawki, surowy materiał.","Dodaj osobną opłatę za użycie w płatnych reklamach poza zwykłymi postami."],"est_minutes":45,"resources":[],"tools":[],"xp":30,"metric_to_track":"Gotowy cennik"},{"id":"p2s2","title":"Dołącz do 2 platform UGC","why":"Marketplace'y UGC łączą Cię z markami, które już szukają twórców. To świetne na pierwsze zlecenia i opinie.","instructions":["Załóż profile na 2 platformach, np. Collabstr, Billo lub JoinBrands.","Wgraj 3 filmy próbne i uzupełnij kategorie.","Zgłoś się do 5 pasujących kampanii."],"est_minutes":60,"resources":[],"tools":[{"name":"Collabstr","url":"https://collabstr.com","affiliate":false},{"name":"Billo","url":"https://billo.app","affiliate":false},{"name":"JoinBrands","url":"https://joinbrands.com","affiliate":false}],"xp":40,"metric_to_track":"Wysłane zgłoszenia"},{"id":"p2s3","title":"Napisz bezpośrednio do 15 marek","why":"Małe i rosnące marki stale potrzebują treści i często płacą lepiej niż marketplace'y.","instructions":["Znajdź 15 marek, które reklamują się w Twoich kategoriach (sprawdź Bibliotekę reklam Meta lub TikToka).","Znajdź kontakt do marketingu na ich stronie lub LinkedIn.","Wyślij krótki e-mail z jednym pomysłem na ich produkt i linkiem do portfolio.","Przypomnij się raz po 5 dniach."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Wysłane propozycje"},{"id":"p2s4","title":"Śledź dochody i podatki","why":"Płatności przychodzą od wielu marek i platform. Prosty zapis porządkuje finanse i przygotowuje do podatków.","instructions":["Zapisuj każde zlecenie: marka, filmy, cena, opłacone lub nie, data.","Aktualizuj zapis przed każdym cotygodniowym podsumowaniem.","Sprawdź, jak rozlicza się dochody twórców w Twoim kraju (w Polsce np. działalność nierejestrowana)."],"est_minutes":30,"resources":[],"tools":[],"xp":20,"metric_to_track":"Nieopłacone faktury"}]},{"id":"p3","title":"Realizacja i rozwój","goal":"Profesjonalnie realizuj płatne zlecenia i poszerzaj portfolio o nowe formaty.","weeks":"6-8","steps":[{"id":"p3s1","title":"Zrealizuj pierwsze płatne zlecenie profesjonalnie","why":"Zadowolone marki wracają i polecają Cię dalej. Profesjonalna realizacja zamienia jednego klienta w pięciu.","instructions":["Przed nagraniem ustal na piśmie brief, termin, cenę i prawa do wykorzystania.","Dostarcz 2–3 warianty haczyka, by marka mogła je testować w reklamach.","Przekaż pliki na czas, w uporządkowanym folderze z czytelnymi nazwami."],"est_minutes":180,"resources":[],"tools":[],"xp":60,"metric_to_track":"Dostarczone filmy"},{"id":"p3s2","title":"Poproś o rekomendację i wyniki","why":"Cytat lub wynik reklamy od prawdziwej marki to najmocniejszy dowód w kolejnej propozycji.","instructions":["Poproś markę o jednozdaniową rekomendację.","Zapytaj, czy może podzielić się wynikami filmu.","Dodaj to do portfolio (za zgodą)."],"est_minutes":30,"resources":[],"tools":[],"xp":30,"metric_to_track":"Rekomendacje"},{"id":"p3s3","title":"Dodaj 3 nowe formaty do portfolio","why":"Pokazanie różnorodności (lektor, tutorial, „3 powody”) pozwala wygrywać więcej rodzajów zleceń.","instructions":["Nagraj jeden film z lektorem, jeden tutorial i jeden „3 powody”.","Użyj produktów z wybranych kategorii.","Zaktualizuj portfolio i profile na platformach."],"est_minutes":180,"resources":[],"tools":[],"xp":40,"metric_to_track":"Filmy w portfolio"}]},{"id":"p4","title":"Stali klienci","goal":"Zamień jednorazowe zlecenia w miesięczne pakiety i podnieś stawki.","weeks":"9-12","steps":[{"id":"p4s1","title":"Zaproponuj pakiety miesięczne","why":"Marki prowadzące reklamy potrzebują co miesiąc nowych filmów. Pakiet daje im stałe dostawy, a Tobie stały dochód.","instructions":["Stwórz pakiet, np. 4 filmy miesięcznie z niewielką zniżką.","Zaproponuj go każdej marce, z którą już pracujesz.","Spisz warunki w prostej umowie."],"est_minutes":60,"resources":[],"tools":[],"xp":50,"metric_to_track":"Klienci miesięczni"},{"id":"p4s2","title":"Podnieś stawki","why":"Z płatnymi realizacjami i rekomendacjami w portfolio możesz brać więcej za ten sam film.","instructions":["Podnieś stawkę bazową dla nowych klientów o 25–50%.","Osobno wyceniaj użycie w reklamach, dodatkowe haczyki i ekspresowe terminy.","Zaktualizuj cennik."],"est_minutes":30,"resources":[],"tools":[],"xp":40,"metric_to_track":"Średnia cena za film"},{"id":"p4s3","title":"Ustal cotygodniowy rytm propozycji","why":"Klienci przychodzą i odchodzą. Pięć propozycji tygodniowo utrzymuje stały dopływ zleceń nawet w zabieganym czasie.","instructions":["Zarezerwuj dwa razy w tygodniu po 30 minut na propozycje.","Prowadź prostą listę marek, dat kontaktu i odpowiedzi.","Pisz do nowych marek, pokazując najlepszy wynik z poprzedniego zlecenia."],"est_minutes":120,"resources":[],"tools":[],"xp":50,"metric_to_track":"Wysłane propozycje"}]}],"weekly_metrics":["pitches_sent","clients","videos_delivered"],"earning_milestones":[{"label":"Tygodnie 3–8","range":"50–300 $","note":"Pierwsze płatne filmy to zwykle 50–150 $ za sztukę."},{"label":"Miesiące 3–6","range":"300–1500 $ / mies.","note":"Kilka powracających marek i zlecenia z platform."},{"label":"Miesiące 6–12","range":"500–3000 $ / mies.","note":"Typowe dla twórców z pakietami miesięcznymi i wyższymi stawkami."}]}$roadmap$)
) as v(slug, locale, content)
join public.hustles h on h.slug = v.slug
on conflict (hustle_id, locale, version) do update
  set content = excluded.content, status = excluded.status;

insert into public.daily_messages (locale, text)
select v.locale, v.text
from (values
  ('en', 'Done beats perfect. Ship one small thing today.'),
  ('en', 'Talk to one real customer before you build anything new.'),
  ('en', 'Consistency compounds. Show up for 30 minutes, even on a bad day.'),
  ('en', 'Your first sale matters more than your logo.'),
  ('en', 'Ask for feedback early. Silence is the only real failure.'),
  ('en', 'Track your numbers. What gets measured gets better.'),
  ('en', 'Small steps, every day. That is the whole secret.'),
  ('en', 'You don''t need more ideas. You need one finished task.'),
  ('en', 'Motivation follows action. Start with the smallest step.'),
  ('en', 'Every expert started with clumsy first attempts.'),
  ('en', 'Protect your 30 minutes today like a meeting you can''t miss.'),
  ('en', 'Progress, not perfection. Publish, learn, improve.'),
  ('en', 'The market can''t reward what it can''t see. Put your work out there.'),
  ('en', 'One uncomfortable message could bring your first client.'),
  ('en', 'Boring consistency beats brilliant bursts.'),
  ('en', 'Finish before you polish.'),
  ('en', 'Rejection is data, not a verdict.'),
  ('en', 'Compare yourself with last week, not with someone''s highlight reel.'),
  ('en', 'A plan you follow beats a perfect plan you don''t.'),
  ('en', 'Today''s step is small. In 30 days you''ll be glad you took it.'),
  ('en', 'Charge for your work. Free forever is not a business.'),
  ('en', 'Clarity beats cleverness. Say exactly what you offer.'),
  ('en', 'When you''re stuck, make the task smaller.'),
  ('en', 'Your future customers are searching right now. Help them find you.'),
  ('en', 'Tiny wins count. Log them and keep going.'),
  ('en', 'Busy isn''t the same as productive. Do the step that moves money.'),
  ('en', 'Tired? Do the 10-minute version and keep your streak alive.'),
  ('en', 'Good work that''s shared beats great work that''s hidden.'),
  ('en', 'Ask one more person today. Momentum is built one yes at a time.'),
  ('en', 'You chose this. Now make it work, one step at a time.'),
  ('pl', 'Zrobione jest lepsze niż idealne. Wypuść dziś jedną małą rzecz.'),
  ('pl', 'Porozmawiaj z jednym prawdziwym klientem, zanim zbudujesz coś nowego.'),
  ('pl', 'Regularność się sumuje. Poświęć 30 minut, nawet w gorszy dzień.'),
  ('pl', 'Pierwsza sprzedaż jest ważniejsza niż logo.'),
  ('pl', 'Proś o opinie wcześnie. Jedyną prawdziwą porażką jest cisza.'),
  ('pl', 'Mierz swoje wyniki. To, co mierzone, się poprawia.'),
  ('pl', 'Małe kroki, codziennie. To cały sekret.'),
  ('pl', 'Nie potrzebujesz więcej pomysłów. Potrzebujesz jednego skończonego zadania.'),
  ('pl', 'Motywacja przychodzi po działaniu. Zacznij od najmniejszego kroku.'),
  ('pl', 'Każde mistrzostwo zaczyna się od pierwszych, niezdarnych prób.'),
  ('pl', 'Chroń dzisiejsze 30 minut jak spotkanie, którego nie można przegapić.'),
  ('pl', 'Postęp, nie perfekcja. Publikuj, ucz się, poprawiaj.'),
  ('pl', 'Rynek nie nagrodzi tego, czego nie widzi. Pokaż swoją pracę.'),
  ('pl', 'Jedna niewygodna wiadomość może przynieść Ci pierwszego klienta.'),
  ('pl', 'Nudna regularność wygrywa z genialnymi zrywami.'),
  ('pl', 'Najpierw skończ, potem szlifuj.'),
  ('pl', 'Odmowa to informacja, nie wyrok.'),
  ('pl', 'Porównuj się z sobą sprzed tygodnia, a nie z czyimiś najlepszymi momentami.'),
  ('pl', 'Plan, którego się trzymasz, jest lepszy niż idealny plan w szufladzie.'),
  ('pl', 'Dzisiejszy krok jest mały. Za 30 dni sobie za niego podziękujesz.'),
  ('pl', 'Bierz pieniądze za swoją pracę. Wiecznie za darmo to nie biznes.'),
  ('pl', 'Jasność wygrywa ze sprytem. Powiedz dokładnie, co oferujesz.'),
  ('pl', 'Gdy utkniesz, zmniejsz zadanie.'),
  ('pl', 'Twoi przyszli klienci szukają właśnie teraz. Pomóż im Cię znaleźć.'),
  ('pl', 'Małe sukcesy się liczą. Zapisuj je i idź dalej.'),
  ('pl', 'Zajętość to nie produktywność. Zrób krok, który przybliża pieniądze.'),
  ('pl', 'Brak sił? Zrób wersję na 10 minut i utrzymaj serię.'),
  ('pl', 'Dobra praca pokazana światu wygrywa ze świetną schowaną do szuflady.'),
  ('pl', 'Zapytaj dziś jeszcze jedną osobę. Rozpęd buduje się z kolejnych „tak”.'),
  ('pl', 'To był Twój wybór. Teraz krok po kroku spraw, by zadziałał.')
) as v(locale, text)
